// === MapStops JSON block markers (frontend parses these) ===
const MAP_JSON_START = "<<<MAP_STOPS_JSON>>>";
const MAP_JSON_END = "<<<END_MAP_STOPS_JSON>>>";

function stablePromptVariantIndex(seed = "", count = 1) {
  const size = Math.max(1, Number(count) || 1);
  let hash = 0;
  for (const ch of String(seed || "")) {
    hash = ((hash << 5) - hash + ch.charCodeAt(0)) | 0;
  }
  return Math.abs(hash) % size;
}

function buildGenerateItineraryQuestion(seed = "", dayCount = 0) {
  const topic = Number(dayCount) > 0 ? `the updated ${Number(dayCount)}-day itinerary` : "the full itinerary";
  const variants = [
    `Want me to generate ${topic} from this?`,
    `Shall I turn this into ${topic}?`,
    `Ready for the itinerary draft based on this summary?`,
  ];
  return variants[stablePromptVariantIndex(seed || topic, variants.length)];
}

const ITINERARY_INTAKE_ALL_REPLY =
  "Happy to help — where are you headed?\n- **Destination or area:** Where are you headed?\n- **Duration:** How many days is the trip?\n- **Date/month:** When are you going?";

const ITINERARY_INTAKE_INTERESTS_ONLY_REPLY =
  "Understood — I’ll follow your itinerary format strictly. What specific interests do you have (food, history, nature, adventure, etc.)?";

// Layla.ai-style progressive clarifier. Asks at most TWO questions per
// turn in this priority order:
//   1. destination
//   2. duration
//   3. theme / vibe
//   4. date
//   5. budget OR origin (whichever is missing first)
//   6. travelers
// Lead-in acknowledges everything already gathered ("Got it — Bantayan,
// 3 days, mid-range vibe.") so the user feels heard, not interrogated.
// Common short-trip islands where origin meaningfully changes the day plan.
// (1-day Bantayan from Cebu City vs already in Santa Fe is a totally
// different itinerary — same goes for Bohol / Boracay / Coron / Siargao / El Nido.)
const SHORT_TRIP_REMOTE_DESTINATION_RX =
  /\b(island|isle|archipelago|beach|coast|coastal|countryside|province|rural|remote|national\s+park|mountain|mountains|volcano|lake|peninsula|islet|atoll)\b/i;

function isShortTripIslandDestination(destinationLabel = "") {
  return SHORT_TRIP_REMOTE_DESTINATION_RX.test(String(destinationLabel || ""));
}

function getOriginPromptForIsland() {
  return "Are you already near the destination, or where are you coming from that day?";
}

function cleanPendingTripShortAnswer(text = "") {
  return String(text || "")
    .replace(/^\s*(?:yes|yeah|yep|yup|sure|ok|okay|no|nope|nah)\b[:,\s-]*/i, "")
    .replace(/\s+(?:for this trip|for the trip|that day|today|tomorrow)$/i, "")
    .replace(/[?.!,;]+$/, "")
    .trim();
}

// Strip day-plan ordinals from a destination-like phrase so a casual answer
// like "Moalboal day 1", "Moalboal d2", or "Moalboal ay 2" (typo of "day 2")
// resolves to the destination "Moalboal" instead of being baked into the
// destination name. Conservative: only strips trailing day/night ordinals.
function stripTripDayPlanPhrases(text = "") {
  return String(text || "")
    .replace(/[\s,;:-]+(?:day|days|night|nights|d|ay)\s*\d+\b[\s\S]*$/i, "")
    .replace(/[\s,;:-]+\d+\s*(?:day|days|night|nights)\b[\s\S]*$/i, "")
    .replace(/[\s,;:-]+(?:day|days|night|nights)\s*\d*\s*$/i, "")
    .replace(/[?.!,;]+$/, "")
    .trim();
}

function looksLikeTripUnknownAnswer(text = "") {
  const t = String(text || "").trim().toLowerCase();
  if (!t) return false;
  // Strict-anchored short answers (existing behavior).
  if (/^(?:i\s+don'?t\s+know|don'?t\s+know|not\s+sure|unsure|no\s+idea|you\s+decide|you\s+can\s+decide|up\s+to\s+you|recommend|recommend\s+one|whatever\s+works|anything\s+works|no\s+preference|flexible)$/i.test(t)) {
    return true;
  }
  // Looser phrasings that clearly mean "I don't know" but include extra
  // filler words ("i have no idea", "no clue", "im not sure", "idk",
  // "honestly no idea", "tbh no idea"). Without this, intake repeats the
  // same question because the strict regex above doesn't match.
  if (/\b(?:i\s+have\s+no\s+(?:idea|clue)|i\s+have\s+no\s+real\s+(?:idea|preference)|no\s+clue|no\s+real\s+(?:idea|preference)|i'?m\s+not\s+sure|im\s+not\s+sure|i\s+do\s+not\s+know|idk|honestly\s+(?:no\s+idea|not\s+sure|i\s+don'?t\s+know)|tbh\s+(?:no\s+idea|not\s+sure)|i\s+really\s+don'?t\s+know|no\s+idea\s+(?:really|honestly|tbh)|i\s+have\s+no\s+strong\s+preference)\b/i.test(t)) {
    return true;
  }
  return false;
}

// Map a peso amount the user mentions ("20k budget per person",
// "₱30,000", "PHP 8000") to the closest budget tier. For PH 2-day trips
// the breakpoints are: <₱10k=budget, ₱10k–₱25k=mid-range, >₱25k=luxury.
// Returns "" when no amount is found, so the caller can keep the
// keyword-based budget if any.
function inferTripBudgetTierFromAmount(text = "") {
  const t = String(text || "").toLowerCase();
  if (!t) return "";

  const match = t.match(/(?:₱|php\s*)?\b(\d{1,3}(?:[,.]?\d{3})*|\d+)\s*(k|thousand)?\b/i);
  if (!match) return "";

  const numericRaw = String(match[1] || "").replace(/[,.]/g, "");
  const num = Number(numericRaw);
  if (!Number.isFinite(num) || num <= 0) return "";
  const multiplier = match[2] ? 1000 : 1;
  const amount = num * multiplier;

  // Guard: ignore amounts that are clearly not a trip-level budget.
  // Per-night accommodation amounts (₱2,000–₱4,000) are handled
  // separately by extractAccommodationBudgetPreference, but if the user
  // wrote them WITHOUT "per night", we still don't want them to
  // overwrite the trip budget here.
  if (amount < 3000) return "";

  // Anchor on "budget" / "per person" / "for the trip" keywords nearby
  // to avoid false positives like "8 am" or "2 days" matching the
  // numeric pattern. If the keyword is not present, only fire when the
  // amount looks like a typical trip-budget magnitude (>= ₱5,000).
  const hasBudgetKeyword =
    /\b(budget|per\s+person|each|all\s+in|all-in|for\s+the\s+trip|spend|spending|allowance|wallet)\b/i.test(t);
  if (!hasBudgetKeyword && amount < 5000) return "";

  if (amount < 10000) return "budget";
  if (amount < 25000) return "mid-range";
  return "luxury";
}

function formatPhpAmount(amount = 0) {
  const n = Number(amount);
  if (!Number.isFinite(n) || n <= 0) return "";
  return `₱${Math.round(n).toLocaleString("en-US")}`;
}

function extractTripBudgetPerPersonFromText(text = "") {
  const raw = String(text || "").trim();
  if (!raw) return null;

  const lower = raw.toLowerCase();
  if (/\b(?:per\s+night|\/night|nightly|a\s+night|each\s+night)\b/i.test(lower)) {
    return null;
  }

  const amountPatterns = [
    /(?:₱|php\s*)?\b(\d{1,3}(?:[,.]?\d{3})*|\d+)\s*(k|thousand)?\s*(?:each|per\s+(?:person|pax|head)|\/person|pp)\b/i,
    /(?:₱|php\s*)?\b(\d{1,3}(?:[,.]?\d{3})*|\d+)\s*(k|thousand)?\s*(?:budget|allowance|all[-\s]?in|spending)\s*(?:each|per\s+(?:person|pax|head)|\/person|pp)?\b/i,
    /\b(?:budget|spend|spending|bring|allowance|all[-\s]?in|around|about|max(?:imum)?|up to)[^\n.?!]{0,80}?(?:₱|php\s*)?\b(\d{1,3}(?:[,.]?\d{3})*|\d+)\s*(k|thousand)?\b/i,
  ];

  for (const rx of amountPatterns) {
    const match = raw.match(rx);
    if (!match) continue;

    const numericRaw = String(match[1] || "").replace(/[,.]/g, "");
    const num = Number(numericRaw);
    if (!Number.isFinite(num) || num <= 0) continue;

    const amount = num * (match[2] ? 1000 : 1);
    if (amount < 3000) continue;

    return {
      amount,
      label: `${formatPhpAmount(amount)} per person`,
      sourceText: raw,
    };
  }

  return null;
}

function extractLatestTripBudgetPerPerson(messages = []) {
  const userMessages = [...messages]
    .filter((m) => m && m.role === "user")
    .map((m) => String(m.content || ""))
    .filter(Boolean);

  for (let i = userMessages.length - 1; i >= 0; i -= 1) {
    const parsed = extractTripBudgetPerPersonFromText(userMessages[i]);
    if (parsed) return parsed;
  }

  return null;
}

function recentBlueprintHasKnownBudgetTier(messages = []) {
  for (let i = messages.length - 1; i >= 0; i -= 1) {
    const m = messages[i];
    if (!m || m.role !== "assistant") continue;
    const text = String(m.content || "");
    if (!/(?:trip summary|should i generate the full itinerary now)/i.test(text)) continue;
    return /\*\*Budget:\*\*\s*(?:budget|mid-range|luxury)\b/i.test(text);
  }
  return false;
}

function extractBudgetTierFromRecentBlueprint(messages = []) {
  for (let i = messages.length - 1; i >= 0; i -= 1) {
    const m = messages[i];
    if (!m || m.role !== "assistant") continue;
    const text = String(m.content || "");
    const match = text.match(/\*?\*?Budget:\*?\*?\s*(budget|mid-range|luxury)\b/i);
    if (match) return match[1].toLowerCase();
  }
  return "";
}

function extractDaysFromRecentBlueprint(messages = []) {
  for (let i = messages.length - 1; i >= 0; i -= 1) {
    const m = messages[i];
    if (!m || m.role !== "assistant") continue;
    const text = String(m.content || "");
    const match = text.match(/\*?\*?Duration:\*?\*?\s*(\d+)\s+days?/i);
    if (match) return Number(match[1]);
  }
  return null;
}

function extractExpectedDurationDays(messages = [], replyText = "") {
  // Worldwide-safe authoritative-blueprint rule: when the latest assistant
  // trip-summary contains a Duration line, that wins over historical user
  // "N-day" mentions. Without this, an initial "plan a 3-day trip" stayed
  // pinned at 3 even after the user later confirmed "day trip" (= 1 day)
  // in the latest blueprint — and the itinerary builder generated 3 days.
  const blueprintDays = extractDaysFromRecentBlueprint(messages) || null;
  // Find the index of the latest blueprint so we can detect EXPLICIT user
  // corrections that come AFTER it.
  let latestBlueprintIndex = -1;
  for (let i = (Array.isArray(messages) ? messages.length : 0) - 1; i >= 0; i -= 1) {
    const m = messages[i];
    if (!m || m.role !== "assistant") continue;
    const text = String(m.content || "");
    if (/\*?\*?Duration:\*?\*?\s*\d+\s+days?/i.test(text)) {
      latestBlueprintIndex = i;
      break;
    }
  }

  let days = blueprintDays;
  for (let i = 0; i < (Array.isArray(messages) ? messages.length : 0); i += 1) {
    const m = messages[i];
    if (!m || m.role !== "user") continue;
    // Skip historical user "N-day" mentions BEFORE the latest blueprint —
    // the blueprint reflects the user's latest confirmed intent.
    if (blueprintDays && latestBlueprintIndex >= 0 && i < latestBlueprintIndex) continue;
    const text = String(m.content || "");
    const corrected = extractRequestedDurationCorrectionDays(text);
    if (corrected) {
      days = corrected;
      continue;
    }
    if (looksLikeItineraryDurationMismatchCorrection(text)) continue;
    const explicit =
      text.match(/\b(\d{1,2})\s*[- ]?\s*(?:day|days)\b/i) ||
      text.match(/\b(one|two|three|four|five|six|seven|eight|nine|ten)\s*[- ]?\s*(?:day|days)\b/i);
    if (explicit) {
      const parsed = parseDayNumberToken(explicit[1]);
      if (parsed) days = parsed;
    }
    // Worldwide-safe "day trip" = 1 day signal that the regex above misses.
    if (/\bday\s+trip\b/i.test(text) && !/\b(?:overnight|two\s+day|three\s+day|\d{1,2}[-\s]?day)\b/i.test(text)) {
      days = 1;
    }
  }
  if (!days && replyText) {
    const summaryMatch = String(replyText || "").match(/\*?\*?Duration:\*?\*?\s*(\d{1,2})\s+days?/i);
    if (summaryMatch) days = Number(summaryMatch[1]) || null;
  }
  return days && days >= 1 ? days : null;
}

function hotelPricingGroupLabel(travelers = "") {
  const text = String(travelers || "").toLowerCase();
  if (/\bfamily|parents?|kids?|children|seniors?\b/.test(text)) return "family total";
  if (/\bsolo|alone|just me|by myself|on my own\b/.test(text)) return "trip total";
  return "group total";
}

function buildDeterministicCostBreakdown({ budgetTier, days, includeNightlife = false, transferLabel = "Major transfer + local transfers", travelers = "", isLocalTrip = false, accommodationNotNeeded = false } = {}) {
  const tier = String(budgetTier || "mid-range").toLowerCase();
  const label = String(transferLabel || "");
  const isFerry = /\bferry\b/i.test(label) && !/\bcamiguin\b/i.test(label);
  const isBus = /\bbus\b/i.test(label) && !/\bcamiguin\b/i.test(label);
  // Camiguin is its own profile: flight to CDO + ferry to Camiguin makes
  // the transfer cost noticeably higher than a straight ferry trip and
  // island-hopping boat fees push tour ranges higher than mainland-Bohol.
  const isCamiguin = /\bcamiguin\b/i.test(label);
  // Major-transfer ranges are PER-PERSON, round-trip when realistic. For
  // Cebu↔Bohol ferry the typical fast-ferry round-trip per person is
  // around ₱1,000–₱2,500 depending on class and operator; bus + ferry
  // legs (e.g. Bantayan) are similar. Flights are higher and stay as
  // the previous defaults.
  const tierConfig = isCamiguin
    ? {
        "budget":    { flights: [2200, 4500], hotel: [600, 1500],  food: [600, 1200],  transport: [300, 700],  tours: [1200, 2500], nightlife: [200, 800] },
        "mid-range": { flights: [3500, 6500], hotel: [1500, 3000], food: [1200, 2500], transport: [600, 1200], tours: [2000, 3500], nightlife: [400, 1000] },
        "luxury":    { flights: [6000, 12000], hotel: [3500, 8000], food: [2500, 5000], transport: [1200, 3000], tours: [3500, 7000], nightlife: [1200, 3000] },
      }
    : isFerry
    ? {
        "budget":    { flights: [1000, 1800], hotel: [600, 1500],  food: [600, 1200],  transport: [200, 500],  tours: [800, 1800],  nightlife: [200, 800] },
        "mid-range": { flights: [1200, 2500], hotel: [1500, 3000], food: [1200, 2500], transport: [500, 1000], tours: [1500, 2500], nightlife: [500, 1500] },
        "luxury":    { flights: [2000, 4000], hotel: [3500, 8000], food: [2500, 5000], transport: [1000, 3000], tours: [3000, 6000], nightlife: [1500, 4000] },
      }
    : isBus
    ? {
        "budget":    { flights: [600, 1500],  hotel: [600, 1500],  food: [600, 1200],  transport: [200, 500],  tours: [800, 1800],  nightlife: [200, 800] },
        "mid-range": { flights: [900, 2200],  hotel: [1500, 3000], food: [1200, 2500], transport: [500, 1000], tours: [1500, 2500], nightlife: [500, 1500] },
        "luxury":    { flights: [1500, 3500], hotel: [3500, 8000], food: [2500, 5000], transport: [1000, 3000], tours: [3000, 6000], nightlife: [1500, 4000] },
      }
    : {
        "budget":    { flights: [2500, 5500], hotel: [600, 1500],  food: [600, 1200],  transport: [200, 500],  tours: [800, 1800],  nightlife: [200, 800] },
        "mid-range": { flights: [4500, 8000], hotel: [1500, 3000], food: [1200, 2500], transport: [500, 1000], tours: [1500, 2500], nightlife: [500, 1500] },
        "luxury":    { flights: [8000, 15000], hotel: [3500, 8000], food: [2500, 5000], transport: [1000, 3000], tours: [3000, 6000], nightlife: [1500, 4000] },
      };
  const cfg = tierConfig[tier] || tierConfig["mid-range"];
  const dayCount = Math.max(1, Number(days) || 2);
  const nights = Math.max(0, dayCount - 1);

  // Worldwide-safe: when accommodation is not needed (local trip, user has
  // own house/place in destination), hotel cost MUST be ₱0. Skip the hotel
  // range from totals so the per-person estimate reflects reality and stop
  // showing a "Hotel share estimate" that contradicts the trip summary.
  const skipHotel = Boolean(accommodationNotNeeded || isLocalTrip);
  // Local trips also have no major transfer (the traveler lives in the
  // destination). Skip flights/major-transfer too.
  const skipMajorTransfer = Boolean(isLocalTrip);
  const ranges = {
    ...(skipMajorTransfer ? {} : { flights: cfg.flights }),
    ...(skipHotel ? {} : { hotel: [cfg.hotel[0] * nights, cfg.hotel[1] * nights] }),
    food: [cfg.food[0] * dayCount, cfg.food[1] * dayCount],
    transport: cfg.transport,
    tours: cfg.tours,
  };
  if (includeNightlife) ranges.nightlife = cfg.nightlife;

  const totalLow = Object.values(ranges).reduce((s, r) => s + r[0], 0);
  const totalHigh = Object.values(ranges).reduce((s, r) => s + r[1], 0);
  const bufferLow = Math.round(totalLow * 0.05);
  const bufferHigh = Math.round(totalHigh * 0.10);

  const fmt = (n) => `₱${Number(n).toLocaleString("en-PH")}`;
  const fmtRange = (r) => `${fmt(r[0])}–${fmt(r[1])}`;

  const lines = [
    "## Estimated Budget",
    `**Estimated total per person:** ~${fmt(totalLow)}–${fmt(totalHigh + bufferHigh)}`,
    skipMajorTransfer
      ? `- **${transferLabel}:** Not applicable for a local trip`
      : `- **${transferLabel}:** ${fmtRange(ranges.flights)}`,
    skipHotel
      ? `- **Accommodation:** ₱0 — ${isLocalTrip ? "staying at own home/base" : "no accommodation needed"}`
      : `- **Hotel share estimate (${nights} night${nights > 1 ? "s" : ""}):** ${fmtRange(ranges.hotel)} per person if rooms are shared`,
    `- **Food (${dayCount} day${dayCount > 1 ? "s" : ""}):** ${fmtRange(ranges.food)}`,
    `- **Local transport:** ${fmtRange(ranges.transport)}`,
    `- **Tours/activities:** ${fmtRange(ranges.tours)}`,
  ];
  if (includeNightlife) lines.push(`- **Nightlife:** ${fmtRange(ranges.nightlife)}`);
  lines.push(`- **Buffer/remaining:** ${fmtRange([bufferLow, bufferHigh])}`);
  // Skip the hotel-pricing note when the trip uses no hotel — it would
  // contradict the "Accommodation: ₱0" line above.
  if (!skipHotel) {
    lines.push(`- **Hotel pricing note:** Hotels are usually priced per room/night, so the ${hotelPricingGroupLabel(travelers)} depends on room count and sharing.`);
  }
  return lines.join("\n");
}

// Decide whether the cost breakdown should include Nightlife. Default is OFF;
// add it only when the user explicitly mentions nightlife, bars, clubs,
// evening markets, drinks, or similar evening entertainment.
function shouldIncludeNightlifeInCostBreakdown(messages = []) {
  const text = String(activeUserConversationText(messages) || "").toLowerCase();
  const explicitNightlife = /\b(nightlife|bar|bars|club|clubs|rooftop|night\s*market|live\s+music|drink|drinks|pub|pubs)\b/.test(text);
  return Boolean(explicitNightlife);
}

function pickCostBreakdownTransferLabel(messages = []) {
  // Active-trip scope first. Reading the full conversation text causes
  // a prior trip's "ferry" mention to leak into a later Camiguin trip
  // and mislabel transport. Prefer the latest assistant blueprint /
  // itinerary block's transport line; only fall back to the full text
  // when nothing is found.
  const activeText = (() => {
    for (let i = messages.length - 1; i >= 0; i -= 1) {
      const m = messages[i];
      if (!m || m.role !== "assistant") continue;
      const t = String(m.content || "");
      const transportLine = t.match(/(?:^|\n)\s*-?\s*\*?\*?Transport:\*?\*?\s*([^\n]+)/i);
      if (transportLine?.[1]) {
        // Also pull the destination/header so the Camiguin/Bohol regional
        // rules below can match the latest blueprint, not stale history.
        const blueprintBlock = t.match(/Trip summary[\s\S]+?(?=\n\n[^-]|$)/i);
        const destLine = t.match(/(?:^|\n)\s*-?\s*\*?\*?Destination:\*?\*?\s*([^\n]+)/i);
        return [
          transportLine[1],
          destLine?.[1] || "",
          blueprintBlock?.[0] || "",
        ].join(" ").toLowerCase();
      }
      // Itinerary header like "Camiguin • Jun 20–22" also locates the
      // active destination for label-picking purposes.
      const headerLine = t.match(/^([A-Z][^\n•]+)\s+•\s+\w+\s+\d{1,2}/m);
      if (headerLine?.[1]) return String(headerLine[1] || "").toLowerCase();
    }
    return "";
  })();

  const text = activeText || String(allConversationText(messages) || "").toLowerCase();
  // Strong destination-aware rule for Camiguin — there is no daily direct
  // Cebu → Camiguin flight, the realistic route is plane to CDO + ferry,
  // so the label must reflect that even when the user typed "flight".
  if (/\bcamiguin\b/.test(text)) {
    if (/\bcebu\b/.test(text)) {
      return "Cebu → CDO + ferry to Camiguin + local transfers";
    }
    return "Major transfer to Camiguin + ferry + local transfers";
  }
  if (/\bferry\b|\bpier\b|\bboat\b|\btubigon\b|\btagbilaran port\b/.test(text)) {
    return "Ferry + local transfers";
  }
  if (/\bbus\b|\bvan\b|\bcoach\b|\bnorth bus terminal\b|\bsouth bus terminal\b/.test(text)) {
    return "Bus + local transfers";
  }
  if (/\bflight\b|\bplane\b|\bfly(?:ing)?\b|\bairport\b/i.test(text)) {
    return "Flight + local transfers";
  }
  if (/\b(?:bohol|panglao|tagbilaran|tubigon)\b/.test(text) && /\bcebu\b/.test(text)) {
    return "Ferry + local transfers";
  }
  return "Major transfer + local transfers";
}

function injectCostBreakdownIntoReply(reply, costSection) {
  const text = String(reply || "");
  const block = `\n\n---\n${costSection}\n`;

  const saveIdx = text.indexOf("Would you like to save this itinerary?");
  if (saveIdx >= 0) {
    return text.slice(0, saveIdx).replace(/\s+$/, "") + block + "\n" + text.slice(saveIdx);
  }

  const mapIdx = text.indexOf("<<<MAP_STOPS_JSON>>>");
  if (mapIdx >= 0) {
    return text.slice(0, mapIdx).replace(/\s+$/, "") + block + "\n" + text.slice(mapIdx);
  }

  return `${text.trim()}${block}`;
}

function replyHasEstimatedCostBreakdown(reply = "") {
  const text = String(reply || "");
  return /(?:^|\n)\s*(?:#{1,3}\s+)?\*?\*?Estimated\s+(?:Budget|Total|Cost|Spending)\b[^\n]*per\s*person/mi.test(text) ||
    /(?:^|\n)\s*\*\*Estimated total[^*\n]*\*\*/mi.test(text);
}

function costBreakdownMatchesDuration(reply = "", days = null) {
  const dayCount = Number(days) || 0;
  if (!dayCount || !replyHasEstimatedCostBreakdown(reply)) return true;
  const text = String(reply || "");
  const expectedNights = Math.max(0, dayCount - 1);
  const hotelMatch = text.match(/\bHotel\s*\((\d+)\s+night/i);
  const foodMatch = text.match(/\bFood\s*\((\d+)\s+day/i);
  if (hotelMatch && Number(hotelMatch[1]) !== expectedNights) return false;
  if (foodMatch && Number(foodMatch[1]) !== dayCount) return false;
  return true;
}

function stripEstimatedCostBreakdown(reply = "") {
  return String(reply || "")
    .replace(
      /\n{0,2}---\s*\n\s*(?:#{1,3}\s+)?\*?\*?Estimated\s+(?:Budget|Total|Cost|Spending)\b[\s\S]*?(?=\n---\s*\n|\nWould you like to save this itinerary\?|<<<MAP_STOPS_JSON>>>|$)/i,
      "\n"
    )
    .replace(
      /\n{0,2}(?:#{1,3}\s+)?\*?\*?Estimated\s+(?:Budget|Total|Cost|Spending)\b[\s\S]*?(?=\n---\s*\n|\nWould you like to save this itinerary\?|<<<MAP_STOPS_JSON>>>|$)/i,
      "\n"
    )
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function ensureDeterministicCostBreakdown(reply = "", messages = [], shouldInclude = false) {
  const days = extractExpectedDurationDays(messages, reply) || extractDaysFromRecentBlueprint(messages);
  const hasBreakdown = replyHasEstimatedCostBreakdown(reply);
  const needsDurationRepair = hasBreakdown && days && !costBreakdownMatchesDuration(reply, days);
  if ((!shouldInclude && !needsDurationRepair) || (hasBreakdown && !needsDurationRepair)) return reply;
  const budgetTier = extractBudgetTierFromRecentBlueprint(messages) || "mid-range";
  const tripDetails = buildConfirmedTripDetailsForValidation(messages);
  // Worldwide-safe: respect "Accommodation: Not needed / local trip" and
  // "Transport: Local transport only" from the blueprint/reply when sizing
  // the budget. Without this the deterministic cost generator emits a
  // hotel-share estimate that contradicts the trip summary.
  const isLocalTrip = typeof detectLocalTripFromMessages === "function"
    ? detectLocalTripFromMessages(messages) || (typeof detectLocalTripFromReplyText === "function" && detectLocalTripFromReplyText(reply, messages))
    : false;
  const accommodationNotNeeded = isLocalTrip || /\b(?:Accommodation|Hotel):\s*Not\s+needed\b/i.test(latestConfirmedBlueprintText(messages) || "");
  const baseReply = needsDurationRepair ? stripEstimatedCostBreakdown(reply) : reply;
  return injectCostBreakdownIntoReply(
    baseReply,
    buildDeterministicCostBreakdown({
      budgetTier,
      days,
      includeNightlife: shouldIncludeNightlifeInCostBreakdown(messages),
      transferLabel: pickCostBreakdownTransferLabel(messages),
      travelers: tripDetails.travelers,
      isLocalTrip,
      accommodationNotNeeded,
    })
  );
}

function ensureCostBreakdownPresent(reply = "", messages = []) {
  const text = String(reply || "");
  if (!isLikelyItineraryText(text)) return text;
  if (replyHasEstimatedCostBreakdown(text)) return text;

  try {
    return ensureDeterministicCostBreakdown(text, messages, true);
  } catch (err) {
    console.warn("[Itinerary] ensureCostBreakdownPresent failed", {
      err: String(err?.message || err || ""),
    });
    return text;
  }
}

// Worldwide-safe local-trip detection: same origin & destination, OR the
// trip summary / latest user message says it's a local/home-based trip / the
// user has their own house/place in the destination.
function detectLocalTripFromMessages(messages = []) {
  const details = buildConfirmedTripDetailsForValidation(messages);
  const summary = latestConfirmedBlueprintText(messages);
  const convo = `${summary}\n${activeUserConversationText(messages)}`;
  const origin = String(details.origin || "").toLowerCase().replace(/\s+/g, " ").trim();
  const destination = String(details.destinationName || "").toLowerCase().replace(/\s+/g, " ").trim();
  const subArea = String(details.subArea || "").toLowerCase().replace(/\s+/g, " ").trim();
  const sameOriginDestination = Boolean(
    origin && destination && (
      origin === destination ||
      destination.includes(origin) ||
      origin.includes(destination) ||
      (subArea && (subArea.includes(origin) || origin.includes(subArea)))
    )
  );
  // Worldwide-safe override: if the confirmed transport mode explicitly
  // names a flight, ferry, or other long-distance leg AND origin and
  // destination are NOT the same place, this is NOT a local trip —
  // regardless of whether the user once said "no hotel" or "we have our
  // own place" (which can leak across prior trips in the conversation).
  // This stops the airport-strip cleanup from removing legitimate flight
  // stops on real inter-island/inter-country routes (e.g. Cebu → Siargao,
  // Cebu → Bohol, Manila → Bangkok).
  const transport = String(details.transportMode || "").toLowerCase();
  const flightTransport = /\b(?:flight|fly|plane|airplane|airline|international\s+flight|domestic\s+flight|ferry|sea\s+connection|boat\s+transfer|inter[-\s]?island|long[-\s]?distance|cross[-\s]?country)\b/i.test(transport);
  if (!sameOriginDestination && flightTransport) {
    return false;
  }
  const summaryFlagsLocal =
    /\b(?:Accommodation:\s*Not\s+needed(?:\s*[\/-]\s*|\s+)?(?:local|home(?:[\s-]+based)?)\s+trip|Transport:\s*Local\s+transport\s+only|Accommodation:\s*Not\s+needed)\b/i.test(summary);
  const userSaidLocal =
    /\b(?:i|we)\s+(?:have|own|got|already\s+have)\s+(?:a\s+|an\s+|my\s+|our\s+|the\s+)?(?:house|home|condo|apartment|flat|place|room|villa|cottage|unit)\s+(?:in|at|near)\s+/i.test(convo) ||
    /\b(?:i|we)\s+live\s+(?:in|at|near|around)\b/i.test(convo) ||
    /\b(?:local\s+trip|staycation|home[\s-]based(?:\s+trip)?)\b/i.test(convo) ||
    /\b(?:no\s+need|don'?t\s+need|do\s+not\s+need|skip)\b[^.\n]{0,40}\b(?:hotel|stay|accommodation|base)\b/i.test(convo);
  return sameOriginDestination || summaryFlagsLocal || userSaidLocal;
}

// Worldwide-safe: strip airport/long-distance terminal "return flight" stops
// from local-trip itineraries. The LLM occasionally tacks on "Mactan-Cebu
// International Airport — Transfer to the airport for the return flight"
// even when the user said they live in the destination. There is no return
// flight; drop the line and let the previous local stop close the day.
const AIRPORT_OR_INTERCITY_TERMINAL_RX =
  /\b(?:international\s+airport|domestic\s+airport|airport\s+terminal|airport|airfield|airstrip|departure\s+terminal|arrival\s+terminal|terminal\s+\d+|naia|sayak|mactan[-\s]?cebu\s+international|kalibo\s+international|cebu\s+international|manila\s+international|caticlan\s+airport|puerto\s+princesa\s+airport|davao\s+international|iloilo\s+international|tagbilaran[-\s]?bohol[-\s]?panglao\s+international|bohol[-\s]?panglao\s+international|bohol[-\s]?panglao\s+airport|laguindingan\s+airport|cagayan\s+de\s+oro\s+airport)\b/i;
const RETURN_FLIGHT_INTENT_RX =
  /\b(?:return\s+flight|flight\s+(?:out|home|back|departure)|departure\s+flight|catch\s+(?:the\s+)?flight|head\s+to\s+(?:the\s+)?airport|airport\s+(?:for\s+the\s+)?(?:return\s+flight|departure|flight\s+out|flight\s+home))\b/i;

// Worldwide-safe destination-scope post-validator. After the LLM produces
// the itinerary, any activity whose label or description names a place that
// clearly belongs to a DIFFERENT country than the active trip's country is
// stripped. Departure-airport stops in the origin country are preserved
// (Day 1 Mactan-Cebu International Airport on a Cebu→Thailand trip stays).
const COUNTRY_PLACE_KEYWORDS = {
  Philippines: /\b(?:cebu(?:\s+city)?|mandaue|lapu[-\s]?lapu|mactan|talisay|carcar|sibonga|naga\s+cebu|bohol|tagbilaran|panglao|alona|loboc|baclayon|chocolate\s+hills|camiguin|mambajao|yumbing|catarman|sagay|mahinog|white\s+island|sunken\s+cemetery|katibawasan|tuasan|ardent|hibok-hibok|palawan|el\s+nido|coron|puerto\s+princesa|siargao|general\s+luna|cloud\s+9|sayak|davao|iloilo|baguio|session\s+road|burnham|manila|intramuros|makati|bgc|naia|piso|jollibee|sm\s+(?:city|seaside|cebu|moa)|ayala\s+(?:center\s+cebu|cebu)|basilica\s+minore|santo\s+ni[ñn]o|magellan'?s?\s+cross|fort\s+san\s+pedro|temple\s+of\s+leah|sirao\s+garden|simala|carmelite\s+monastery|taoist\s+temple|moalboal|panagsama|kawasan\s+falls|bantayan|santa\s+fe|siquijor|boracay|kalibo|caticlan)\b/i,
  Thailand: /\b(?:bangkok|krung\s+thep|phuket|chiang\s+mai|chiang\s+rai|pattaya|hua\s+hin|krabi|koh\s+samui|koh\s+phangan|koh\s+tao|ayutthaya|sukhothai|wat\s+(?:arun|pho|phra\s+kaew|saket|traimit)|grand\s+palace|emerald\s+buddha|reclining\s+buddha|yaowarat|chatuchak|jim\s+thompson|erawan\s+shrine|mbk|siam\s+(?:square|paragon|center|centre)|silom|sukhumvit|khao\s+san|asiatique|don\s+mueang|suvarnabhumi|sea\s+life\s+bangkok|bangkok\s+(?:art|national\s+museum|city\s+pillar|chinatown))\b/i,
  Japan: /\b(?:tokyo|kyoto|osaka|sapporo|nagoya|fukuoka|hiroshima|nara|okinawa|yokohama|kamakura|hakone|nikko|mt\.?\s+fuji|fushimi\s+inari|kinkaku-?ji|senso-?ji|asakusa|shibuya|shinjuku|akihabara|ginza|harajuku|odaiba|dotonbori|narita|haneda|kansai\s+international|tokyo\s+(?:tower|skytree|station))\b/i,
  Vietnam: /\b(?:hanoi|ho\s+chi\s+minh(?:\s+city)?|saigon|da\s+nang|hoi\s+an|hue|halong\s+bay|nha\s+trang|sapa|mekong|noi\s+bai|tan\s+son\s+nhat|cu\s+chi|war\s+remnants|temple\s+of\s+literature)\b/i,
  Indonesia: /\b(?:bali|jakarta|yogyakarta|jogja|borobudur|prambanan|ubud|kuta|seminyak|nusa\s+dua|nusa\s+penida|gili|lombok|denpasar|ngurah\s+rai|soekarno-?hatta|tanah\s+lot|tegalalang|monkey\s+forest)\b/i,
  Malaysia: /\b(?:kuala\s+lumpur|petaling\s+jaya|penang|george\s+town|langkawi|malacca|melaka|johor\s+bahru|kota\s+kinabalu|kuching|kuala\s+terengganu|petronas|klcc|batu\s+caves|kl\s+tower|klia)\b/i,
  Singapore: /\b(?:singapore|sentosa|marina\s+bay|gardens\s+by\s+the\s+bay|orchard\s+road|merlion|chinatown\s+singapore|little\s+india|changi|jewel\s+changi|universal\s+studios\s+singapore|night\s+safari|river\s+safari)\b/i,
  "South Korea": /\b(?:seoul|busan|incheon|jeju|gyeongju|myeongdong|gangnam|itaewon|hongdae|insadong|namsan|n\s+seoul\s+tower|gyeongbokgung|changdeokgung|bukchon|dongdaemun|coex|lotte\s+world)\b/i,
  Italy: /\b(?:rome|florence|venice|milan|naples|turin|bologna|verona|cinque\s+terre|amalfi|positano|capri|sicily|sardinia|colosseum|vatican|st\.\s+peter'?s|trevi|pantheon|uffizi|duomo|piazza\s+san\s+marco|leaning\s+tower)\b/i,
  France: /\b(?:paris|nice|cannes|marseille|lyon|bordeaux|strasbourg|provence|loire|normandy|eiffel\s+tower|louvre|notre[-\s]?dame|champs[-\s]?[éeè]lys[éeè]es|sacr[ée]\s+c[œoe]ur|versailles|mont\s+saint[-\s]?michel|charles\s+de\s+gaulle)\b/i,
  "United Kingdom": /\b(?:london|edinburgh|manchester|liverpool|oxford|cambridge|bath|york|big\s+ben|tower\s+bridge|buckingham\s+palace|westminster|british\s+museum|hyde\s+park|covent\s+garden|piccadilly|heathrow)\b/i,
  "United States": /\b(?:new\s+york|nyc|manhattan|brooklyn|times\s+square|central\s+park|statue\s+of\s+liberty|empire\s+state|los\s+angeles|hollywood|venice\s+beach|santa\s+monica|las\s+vegas|grand\s+canyon|san\s+francisco|golden\s+gate|alcatraz|chicago|miami|seattle|space\s+needle|jfk\s+airport|lax)\b/i,
};

function detectActiveTripCountryFromMessages(messages = []) {
  const details = buildConfirmedTripDetailsForValidation(messages);
  const candidates = [
    details.country,
    inferCountryFromPlace(details.destinationName || ""),
    inferCountryFromPlace(details.subArea || ""),
  ];
  for (const c of candidates) {
    const value = String(c || "").trim();
    if (!value) continue;
    if (COUNTRY_PLACE_KEYWORDS[value]) return value;
    // Soft match for spelling variants like "philippines" → "Philippines".
    for (const key of Object.keys(COUNTRY_PLACE_KEYWORDS)) {
      if (key.toLowerCase() === value.toLowerCase()) return key;
    }
  }
  return "";
}

function detectActiveTripOriginCountryFromMessages(messages = []) {
  const details = buildConfirmedTripDetailsForValidation(messages);
  const origin = String(details.origin || "").trim();
  if (!origin) return "";
  const inferred = inferCountryFromPlace(origin);
  if (inferred && COUNTRY_PLACE_KEYWORDS[inferred]) return inferred;
  for (const [country, rx] of Object.entries(COUNTRY_PLACE_KEYWORDS)) {
    if (rx.test(origin)) return country;
  }
  return "";
}

function stripCrossCountryStopsFromItinerary(reply = "", messages = []) {
  const text = String(reply || "");
  if (!isLikelyItineraryText(text)) return text;
  const activeCountry = detectActiveTripCountryFromMessages(messages);
  if (!activeCountry || !COUNTRY_PLACE_KEYWORDS[activeCountry]) return text;

  const activeRx = COUNTRY_PLACE_KEYWORDS[activeCountry];
  const originCountry = detectActiveTripOriginCountryFromMessages(messages);
  const originRx = originCountry && originCountry !== activeCountry
    ? COUNTRY_PLACE_KEYWORDS[originCountry]
    : null;

  const { prose, mapBlock } = splitReplyAndMapBlock(text);
  if (!prose.trim()) return text;
  const lines = prose.split(/\r?\n/);
  const kept = [];
  let removed = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    const trimmed = String(line || "").trim();
    // Only inspect activity lines, not headers/notes. Accept three shapes:
    //   1. combined: "HH:MM–HH:MM - Label - note"
    //   2. label line with em-dash separator: "Label — note"
    //   3. label line with spaced-hyphen separator: "Label - note"
    //      (the strict LLM format; previously this slipped past the
    //      stripper, letting Cebu stops like Basilica Minore del Santo
    //      Niño leak into a Japan itinerary.)
    const isActivityLine =
      /^(?:\d{1,2}:\d{2})[–—-](?:\d{1,2}:\d{2})\s*-\s+[A-Z]/.test(trimmed) ||
      /^[A-Z][^\n]+\s—\s/.test(trimmed) ||
      (/^[A-Z][^\n]+\s-\s/.test(trimmed) &&
        kept.length &&
        /^\d{1,2}:\d{2}[–—-]\d{1,2}:\d{2}\s*$/.test(String(kept[kept.length - 1] || "").trim()));
    if (!isActivityLine) {
      kept.push(line);
      continue;
    }
    // Find country keywords in this line.
    let matchedOther = "";
    for (const [country, rx] of Object.entries(COUNTRY_PLACE_KEYWORDS)) {
      if (country === activeCountry) continue;
      if (rx.test(trimmed)) {
        matchedOther = country;
        break;
      }
    }
    if (!matchedOther) {
      kept.push(line);
      continue;
    }
    // Origin-country airport for departure logistics is OK (e.g. Mactan-Cebu
    // International Airport on a Cebu→Thailand trip's Day 1).
    if (matchedOther === originCountry && /\b(?:airport|international|terminal\s+\d|departure|check[-\s]?in)\b/i.test(trimmed)) {
      kept.push(line);
      continue;
    }
    // The line is a cross-country leak. Drop it; also drop the previous
    // time-only line if this was a split label format.
    if (kept.length && /^\d{1,2}:\d{2}[–—-]\d{1,2}:\d{2}\s*$/.test(String(kept[kept.length - 1] || "").trim())) {
      kept.pop();
    }
    removed += 1;
  }
  if (!removed) return text;
  console.log(`[Itinerary] cross-country scope strip: removed ${removed} stop(s) belonging to a different country than ${activeCountry}`);
  const cleaned = kept.join("\n").replace(/\n{3,}/g, "\n\n").trim();
  return mapBlock ? `${cleaned}\n\n${mapBlock}`.trim() : cleaned;
}

// Worldwide-safe Stations-of-the-Cross merger. The LLM occasionally splits
// the "Walkway to the Old Volcano / Stations of the Cross" walk into
// separate "1st Station", "4th Station", ... activity entries — these are
// not meaningful standalone destinations. Collapse them into one stop.
function mergeStationsOfTheCrossStops(reply = "") {
  const text = String(reply || "");
  if (!isLikelyItineraryText(text)) return text;
  const { prose, mapBlock } = splitReplyAndMapBlock(text);
  if (!prose.trim()) return text;
  const lines = prose.split(/\r?\n/);
  const stationActivityRx = /\b(?:\d{1,2}(?:st|nd|rd|th)\s+station|station\s+(?:no\.?\s*)?\d{1,2}|first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|tenth|eleventh|twelfth|thirteenth|fourteenth)\s+station\b/i;
  const out = [];
  let collapsedStart = "";
  let collapsedEnd = "";
  let removed = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    const trimmed = String(line || "").trim();
    const isStation =
      /^(?:\d{1,2}:\d{2}[–—-]\d{1,2}:\d{2}\s*-\s*)?[^A-Za-z]*\d{1,2}(?:st|nd|rd|th)\s+station\b/i.test(trimmed) ||
      stationActivityRx.test(trimmed);
    if (isStation && /^\d{1,2}:\d{2}[–—-]\d{1,2}:\d{2}\s*-/.test(trimmed)) {
      const tm = trimmed.match(/^(\d{1,2}:\d{2})[–—-](\d{1,2}:\d{2})/);
      if (tm) {
        if (!collapsedStart) collapsedStart = tm[1];
        collapsedEnd = tm[2];
        removed += 1;
        continue;
      }
    }
    // Split label form: prior line was time, this is "Nth Station" label.
    if (isStation && out.length && /^\d{1,2}:\d{2}[–—-]\d{1,2}:\d{2}\s*$/.test(String(out[out.length - 1] || "").trim())) {
      const prev = out[out.length - 1].trim();
      const tm = prev.match(/^(\d{1,2}:\d{2})[–—-](\d{1,2}:\d{2})/);
      if (tm) {
        if (!collapsedStart) collapsedStart = tm[1];
        collapsedEnd = tm[2];
        out.pop();
        removed += 1;
        continue;
      }
    }
    if (collapsedStart && collapsedEnd) {
      // Flush the merged stop before continuing the normal stream.
      out.push(`${collapsedStart}–${collapsedEnd} - Walkway to the Old Volcano (Stations of the Cross) — Walk the pilgrimage route at a slow pace and stop briefly at each station; wear closed shoes and bring water.`);
      collapsedStart = "";
      collapsedEnd = "";
    }
    out.push(line);
  }
  if (collapsedStart && collapsedEnd) {
    out.push(`${collapsedStart}–${collapsedEnd} - Walkway to the Old Volcano (Stations of the Cross) — Walk the pilgrimage route at a slow pace and stop briefly at each station; wear closed shoes and bring water.`);
  }
  if (!removed) return text;
  console.log(`[Itinerary] Stations-of-the-Cross merge: collapsed ${removed} station entries into one walkway stop`);
  const cleaned = out.join("\n").replace(/\n{3,}/g, "\n\n").trim();
  return mapBlock ? `${cleaned}\n\n${mapBlock}`.trim() : cleaned;
}

// Worldwide-safe cross-day exact-label duplicate dropper. If the same
// attraction name appears as an activity on two different days WITHOUT an
// explicit differentiator (sunrise/sunset/morning/afternoon/return visit
// note), drop the second occurrence. The LLM has been repeating White
// Island on Day 1 and Day 3 of a 3-day Camiguin trip; the second instance
// pushes a real Camiguin stop out of the itinerary.
function dropCrossDayExactDuplicateStops(reply = "") {
  const text = String(reply || "");
  if (!isLikelyItineraryText(text)) return text;
  const { prose, mapBlock } = splitReplyAndMapBlock(text);
  if (!prose.trim()) return text;
  const lines = prose.split(/\r?\n/);
  const out = [];
  const seen = new Map(); // label-key → {dayIdx, hasDifferentiator}
  let currentDay = 0;
  let removed = 0;

  const labelKey = (raw) => String(raw || "")
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "") // explicit combining-marks range (handles ñ→n, é→e, ü→u)
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  // Worldwide-safe: ONLY explicit revisit-intent phrases exempt a cross-day
  // duplicate. Bare time-of-day words like "morning" / "afternoon" appear
  // in routine stop descriptions and previously let duplicates slip through
  // (e.g. Simala Shrine on Day 1 + "afternoon prayer visit" on Day 2 + Day 3).
  const DIFFERENTIATOR_RX = /\b(?:sunrise\s+(?:visit|view|stop)|sunset\s+(?:visit|view|stop)|return\s+visit|second\s+visit|third\s+visit|revisit|come\s+back|return\s+for\s+(?:a|another)\s+(?:visit|stop)|low\s+tide\s+(?:visit|stop)|high\s+tide\s+(?:visit|stop)|different\s+(?:angle|route|side)|alternate\s+(?:route|entrance)|night\s+(?:market|show))\b/i;

  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    const trimmed = String(line || "").trim();
    const dayMatch = trimmed.match(/^Day\s+(\d+)\s*[—-]/i);
    if (dayMatch) {
      currentDay = Number(dayMatch[1]) || currentDay;
      out.push(line);
      continue;
    }
    // Combined-format activity line.
    const combined = trimmed.match(/^\d{1,2}:\d{2}[–—-]\d{1,2}:\d{2}\s*-\s+([^\n—-]+?)(?:\s+[—-]\s+(.+))?$/);
    let label = "";
    let note = "";
    let timeOnlyPrev = false;
    if (combined) {
      label = combined[1].trim();
      note = (combined[2] || "").trim();
    } else if (
      out.length &&
      /^\d{1,2}:\d{2}[–—-]\d{1,2}:\d{2}\s*$/.test(String(out[out.length - 1] || "").trim()) &&
      /^[A-Z]/.test(trimmed)
    ) {
      // Split label form. The label line includes "— description".
      const splitLabelMatch = trimmed.match(/^([^—-]+?)\s+[—-]\s+(.+)$/);
      if (splitLabelMatch) {
        label = splitLabelMatch[1].trim();
        note = splitLabelMatch[2].trim();
        timeOnlyPrev = true;
      }
    }
    if (!label) {
      out.push(line);
      continue;
    }
    const key = labelKey(label);
    if (!key) {
      out.push(line);
      continue;
    }
    if (seen.has(key)) {
      const prior = seen.get(key);
      const differentiator = DIFFERENTIATOR_RX.test(note);
      const priorDifferentiator = DIFFERENTIATOR_RX.test(prior.note);
      if (prior.day !== currentDay && !differentiator && !priorDifferentiator) {
        // Drop this duplicate (and its preceding time-only line if split).
        if (timeOnlyPrev) out.pop();
        removed += 1;
        continue;
      }
    }
    seen.set(key, { day: currentDay, note });
    out.push(line);
  }
  if (!removed) return text;
  console.log(`[Itinerary] cross-day duplicate stop drop: removed ${removed} repeated stop(s) (no sunrise/sunset/return differentiator)`);
  const cleaned = out.join("\n").replace(/\n{3,}/g, "\n\n").trim();
  return mapBlock ? `${cleaned}\n\n${mapBlock}`.trim() : cleaned;
}

// Worldwide-safe: also detect local trip from the itinerary REPLY text
// itself. The trip summary that precedes the itinerary lives in the message
// history, but for the fallback / recovery paths the messages context can
// be thin. The reply itself usually carries "Transport: Local transport
// only", "Accommodation: Not needed", or a Base equal to the origin city —
// those are reliable local-trip signals at strip time.
function detectLocalTripFromReplyText(reply = "", messages = []) {
  const text = String(reply || "");
  if (!text) return false;
  // Trip-summary style signals.
  if (/\bTransport:\s*Local\s+transport\s+only\b/i.test(text)) return true;
  if (/\b(?:Accommodation|Hotel):\s*Not\s+needed(?:\s*[\/-]\s*|\s+)?(?:local|home(?:[\s-]+based)?|local\s+trip)?\b/i.test(text)) return true;
  if (/\bHotel:\s*Not\s+needed\s+(?:[\/—-]\s+)?(?:local|home)/i.test(text)) return true;
  // Budget-breakdown style signals (the deterministic cost block writes these
  // for local trips — they're a reliable in-reply marker that the airport
  // strip otherwise missed when message-history extraction also missed).
  if (/\bNot\s+applicable\s+(?:for\s+)?a\s+local\s+(?:Cebu\s+)?trip\b/i.test(text)) return true;
  if (/\bstaying\s+at\s+(?:own|your|the)\s+(?:home|house)\s*\/?\s*base\b/i.test(text)) return true;
  if (/\b(?:Flights?\s*\/\s*major\s+transfer|Major\s+transfer\s*\+\s*local\s+transfers|Flight\s*\+\s*major\s+transfer)[^\n:]*:\s*Not\s+(?:applicable|needed|required)\b/i.test(text)) return true;
  if (/\bno\s+(?:flight|major\s+transfer|accommodation|hotel)\s+needed\s+for\s+(?:a|this)\s+local\s+(?:Cebu\s+)?trip\b/i.test(text)) return true;

  const convo = activeUserConversationText(messages).toLowerCase();
  const cebuLocalSignals =
    /\b(?:i|we)(?:'re| are| am|m)?\s+from\s+cebu\b/i.test(convo) ||
    /\b(?:i|we)\s+live\s+(?:in|at|near|around)\s+cebu\b/i.test(convo) ||
    /\b(?:my|our)\s+(?:house|home|place)\s+is\s+(?:in|at|near)\s+cebu\b/i.test(convo) ||
    /\b(?:from|origin)\s*:\s*cebu\b/i.test(`${convo}\n${text}`) ||
    /\b(?:no\s+need|don'?t\s+need|do\s+not\s+need|skip)\b[^.\n]{0,50}\b(?:hotel|stay|accommodation|base)\b/i.test(convo);

  const cebuReplySignals =
    /\bDestination:\s*Cebu,\s*Philippines\b/i.test(text) ||
    /^Cebu,\s*Philippines\s*•/im.test(text) ||
    /\bBase:\s*Cebu(?:\s+City)?\b/i.test(text);

  if (cebuLocalSignals && cebuReplySignals) return true;

  // Reply header "Base: <city>" + conversation says "i have a house in <city>" / "i live in <city>".
  const baseMatch = text.match(/^Base:\s*([^•\n]+?)(?:\s*•|$)/im);
  if (baseMatch?.[1]) {
    const base = baseMatch[1].trim().toLowerCase();
    if (
      base &&
      (
        new RegExp(`\\b(?:i|we)\\s+(?:have|own|got|already\\s+have)\\s+(?:a|an|my|our|the)?\\s*(?:house|home|condo|apartment|flat|place|room)\\s+(?:in|at|near)\\s+${base.replace(/[.*+?^${}()|[\\]\\\\]/g, "\\\\$&").split(/[,\s]+/)[0]}`, "i").test(convo) ||
        new RegExp(`\\b(?:i|we)\\s+live\\s+(?:in|at|near|around)\\s+${base.replace(/[.*+?^${}()|[\\]\\\\]/g, "\\\\$&").split(/[,\s]+/)[0]}`, "i").test(convo)
      )
    ) {
      return true;
    }
  }
  return false;
}

function localTripShouldNeverUseAirport(reply = "", messages = []) {
  const text = String(reply || "");
  const convo = activeUserConversationText(messages).toLowerCase();
  const details = buildConfirmedTripDetailsForValidation(messages);
  const destination = String(details.destinationName || details.subArea || "").toLowerCase();

  const isLocal =
    detectLocalTripFromMessages(messages) ||
    detectLocalTripFromReplyText(text, messages) ||
    (
      /\bcebu\b/i.test(destination || text) &&
      (
        /\b(?:i|we)(?:'re| are| am|m)?\s+from\s+cebu\b/i.test(convo) ||
        /\b(?:i|we)\s+live\s+(?:in|at|near|around)\s+cebu\b/i.test(convo) ||
        /\b(?:my|our)\s+(?:house|home|place)\s+is\s+(?:in|at|near)\s+cebu\b/i.test(convo) ||
        /\b(?:no\s+need|don'?t\s+need|do\s+not\s+need|skip)\b[^.\n]{0,50}\b(?:hotel|stay|accommodation|base)\b/i.test(convo)
      )
    );

  if (!isLocal) return false;

  const userExplicitlyNeedsAirport =
    /\b(?:my|our|the)\s+flight\b/i.test(convo) ||
    /\b(?:flight|plane)\s+(?:leaves|departs|arrives|arrival|departure)\b/i.test(convo) ||
    /\b(?:pick\s+up|pickup|drop\s+off|dropoff)\s+(?:at|from|to)\s+(?:the\s+)?airport\b/i.test(convo);

  return !userExplicitlyNeedsAirport;
}

// Worldwide-safe: drop activity blocks whose ENTIRE description is one of
// the known weak filler phrases (legacy repair-note text the LLM has been
// learning from past replies). If the stop is nameless or generic and the
// only note is filler, the block is dropped; if the stop has a real name,
// the filler note alone is replaced with an empty note so the LLM-supplied
// description (when present) is kept.
const WEAK_FILLER_NOTE_RX =
  /\b(?:quick\s+nearby\s+stop\s+to\s+round\s+out\s+the\s+day|easy\s+nearby\s+stop\s+with\s+enough\s+time\s+for\s+transfers?|practical\s+nearby\s+stop\s+that\s+fits\s+the\s+day|use\s+this\s+as\s+a\s+nearby\s+mappable\s+stop[^.\n]*|use\s+this\s+as\s+a\s+practical\s+(?:city[-\s]?center\s+)?buffer[^.\n]*|practical\s+(?:city[-\s]?center|town[-\s]?center|town\s+proper)\s+buffer[^.\n]*|main\s+destination\s+area[^.\n]*|verify\s+current\s+hours\s+before\s+going)\b/i;

// Worldwide-safe: stop LABELS that are vague generic city zones — not real
// attractions. The LLM occasionally inserts these as filler when the
// candidate pool is thin. Reject regardless of description quality.
const VAGUE_GENERIC_AREA_LABEL_RX =
  /^(?:[A-Z][\w'.\-]+\s+)?(?:business\s+park|city\s+center|city\s+centre|town\s+center|town\s+centre|town\s+proper|main\s+destination\s+area|nearby\s+area|town\s+highway|main\s+highway|highway|main\s+road|main\s+street|public\s+plaza|plaza|central\s+park\s+area|downtown\s+area)$/i;

// Worldwide-safe: labels that look like a barangay / subdivision / multi-
// part street address instead of an attraction. Examples: "Pit-os Cebu",
// "Urbanville, Tapuco, Pit-os, Cebu City", "Brgy Cantiplan, Cebu". These
// are administrative-area fragments returned by provider fallback and have
// no value as an itinerary stop.
function looksLikeAddressOrBarangayFragmentLabel(label = "") {
  const t = String(label || "").trim();
  if (!t) return false;
  // Multi-comma addresses (3+ parts separated by commas).
  if ((t.match(/,/g) || []).length >= 2) return true;
  // Starts with barangay / sitio / purok / zone / subdivision marker.
  if (/^(?:brgy\.?|barangay|sitio|purok|zone|subdivision|village|ward|township)\b/i.test(t)) return true;
  // "<word> <country/province>" where the trailing token is the broad
  // destination — e.g. "Pit-os Cebu", "Mahogany Iloilo".
  if (/^[A-Z][a-z'-]+\s+(?:Cebu|Bohol|Palawan|Camiguin|Manila|Iloilo|Davao|Baguio|Bantayan|Siquijor|Boracay|Siargao)$/i.test(t)) return true;
  if (/\b(?:school|campus|soccer\s+field|garden\s+center|airport|terminal|port|pier)\b/i.test(t)) return true;
  return false;
}

function stripUnrequestedBantayanStopsFromCebuItinerary(reply = "", messages = []) {
  const text = String(reply || "");
  if (!isLikelyItineraryText(text)) return text;

  const details = buildConfirmedTripDetailsForValidation(messages);
  const destination = String(details.destinationName || details.subArea || "").toLowerCase();
  const userText = activeUserConversationText(messages).toLowerCase();

  const isCebuTrip = /\bcebu\b/.test(destination) || /^Cebu,\s*Philippines\s*•/im.test(text);
  const userExplicitlyAskedBantayan = /\b(?:bantayan|santa\s+fe|sta\.?\s*fe|hagnaya)\b/i.test(userText);

  if (!isCebuTrip || userExplicitlyAskedBantayan) return text;

  const { prose, mapBlock } = splitReplyAndMapBlock(text);
  if (!prose.trim()) return text;

  const lines = prose.split(/\r?\n/);
  const kept = [];
  let removed = 0;

  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    const trimmed = String(line || "").trim();

    const combined = trimmed.match(/^\d{1,2}:\d{2}[–—-]\d{1,2}:\d{2}\s*-\s*([^\n—]+?)(?:\s+—\s+(.+))?$/);
    if (combined && /\b(?:bantayan|santa\s+fe|sta\.?\s*fe|hagnaya)\b/i.test(`${combined[1] || ""} ${combined[2] || ""}`)) {
      removed += 1;
      continue;
    }

    const timeOnly = /^\d{1,2}:\d{2}[–—-]\d{1,2}:\d{2}$/.test(trimmed);
    if (timeOnly && i + 1 < lines.length) {
      const nextLine = String(lines[i + 1] || "").trim();
      if (/\b(?:bantayan|santa\s+fe|sta\.?\s*fe|hagnaya)\b/i.test(nextLine)) {
        removed += 1;
        i += 1;
        continue;
      }
    }

    kept.push(line);
  }

  if (!removed) return text;

  let cleaned = kept.join("\n").replace(/\n{3,}/g, "\n\n").trim();

  if (mapBlock) {
    try {
      const parsed = extractMapStopsJson(mapBlock);
      if (parsed && Array.isArray(parsed.mapStops)) {
        const filtered = parsed.mapStops.filter((stop) => {
          const combined = `${stop?.label || ""} ${stop?.query || ""}`;
          return !/\b(?:bantayan|santa\s+fe|sta\.?\s*fe|hagnaya)\b/i.test(combined);
        });
        const nextMapBlock = `MAP_STOPS_JSON\n${JSON.stringify({ ...parsed, mapStops: renumberMapStopsByDay(filtered) }, null, 2)}\nEND_MAP_STOPS_JSON`;
        cleaned = `${cleaned}\n\n${nextMapBlock}`.trim();
      } else {
        cleaned = `${cleaned}\n\n${mapBlock}`.trim();
      }
    } catch (e) {
      cleaned = `${cleaned}\n\n${mapBlock}`.trim();
    }
  }

  console.log(`[Itinerary] Cebu realism cleanup: removed ${removed} unrequested Bantayan/Hagnaya stop(s)`);
  return cleaned;
}

function stripWeakFillerStops(reply = "") {
  const text = String(reply || "");
  if (!isLikelyItineraryText(text)) return text;
  const { prose, mapBlock } = splitReplyAndMapBlock(text);
  if (!prose.trim()) return text;
  const lines = prose.split(/\r?\n/);
  const out = [];
  let removed = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    const trimmed = String(line || "").trim();
    // Combined-format activity line where the description is JUST the
    // filler phrase ("HH:MM–HH:MM - <name> — Quick nearby stop to round
    // out the day."), OR where the LABEL is a vague generic area like
    // "Cebu Business Park", "Main destination area", "Town proper".
    // The label/note separator can be either an em-dash (U+2014) or a
    // SPACED hyphen (`<label> - <note>`). The required surrounding spaces
    // are what protects in-label hyphens like "Chika-an sa Cebu",
    // "CEBU HI-Q", "Mt. Hibok-Hibok" — those have no spaces and stay
    // glued to their label.
    const combined = trimmed.match(/^(\d{1,2}:\d{2})[–—-](\d{1,2}:\d{2})\s*-\s*(.+?)\s+(?:—|-)\s+(.+)$/);
    if (combined) {
      const label = combined[3].trim();
      const note = combined[4].trim();
      const noteIsOnlyFiller = WEAK_FILLER_NOTE_RX.test(note) && note.length < 120;
      const labelIsVague =
        VAGUE_GENERIC_AREA_LABEL_RX.test(label) ||
        looksLikeAddressOrBarangayFragmentLabel(label) ||
        (typeof SCHOOL_OR_INSTITUTION_LABEL_RX !== "undefined" && SCHOOL_OR_INSTITUTION_LABEL_RX.test(label));
      if (noteIsOnlyFiller || labelIsVague) {
        removed += 1;
        continue;
      }
    }
    // Split-label form: time on previous kept line, label+description here.
    if (
      out.length &&
      /^\d{1,2}:\d{2}[–—-]\d{1,2}:\d{2}\s*$/.test(String(out[out.length - 1] || "").trim()) &&
      /^[A-Z]/.test(trimmed)
    ) {
      // Label may contain regular hyphens ("Chika-an sa Cebu", "CEBU HI-Q",
      // "Mt. Hibok-Hibok"); the label/note separator is either em-dash
      // (U+2014) or a SPACED hyphen — both require surrounding spaces, so
      // in-label hyphens (no spaces) stay attached to the label.
      const splitLabel = trimmed.match(/^(.+?)\s+(?:—|-)\s+(.+)$/);
      if (splitLabel) {
        const label = splitLabel[1].trim();
        const note = splitLabel[2].trim();
        const noteIsOnlyFiller = WEAK_FILLER_NOTE_RX.test(note) && note.length < 120;
        const labelIsVague = VAGUE_GENERIC_AREA_LABEL_RX.test(label);
        if (noteIsOnlyFiller || labelIsVague) {
          out.pop(); // drop the time-only line
          removed += 1;
          continue;
        }
      }
    }
    out.push(line);
  }
  if (!removed) return text;
  console.log(`[Itinerary] weak-filler strip: removed ${removed} filler stop(s) ("Quick nearby stop to round out the day" etc.)`);
  const cleaned = out.join("\n").replace(/\n{3,}/g, "\n\n").trim();
  return mapBlock ? `${cleaned}\n\n${mapBlock}`.trim() : cleaned;
}

// Worldwide-safe: collapse back-to-back stops whose normalized labels share
// the same significant landmark token ("Hibok-Hibok Summit Viewpoint" +
// "Mt. Hibok-Hibok Viewpoint" right after it). Keep the first, drop the
// second. Different-day duplicates are handled by
// dropCrossDayExactDuplicateStops; this catches same-day adjacent repeats.
function collapseAdjacentSameLandmarkStops(reply = "") {
  const text = String(reply || "");
  if (!isLikelyItineraryText(text)) return text;
  const { prose, mapBlock } = splitReplyAndMapBlock(text);
  if (!prose.trim()) return text;
  const lines = prose.split(/\r?\n/);
  const out = [];
  let lastLandmarkKey = "";
  let removed = 0;
  const landmarkKeyOf = (label) => {
    const t = String(label || "")
      .toLowerCase()
      .replace(/^(?:mt\.?|mount|brgy\.?|barangay|the|st\.?|saint)\s+/i, "")
      .replace(/\s+(?:viewpoint|summit|peak|trailhead|lookout|lookout\s+point|trail|park|garden|beach|falls?|spring|hot\s+spring|cold\s+spring|temple|shrine|church|cathedral|basilica|monastery|museum|market|terminal|station|airport|port|pier|harbor|harbour)\b.*$/i, "")
      .replace(/[^a-z0-9\s]/g, " ")
      .replace(/\s+/g, " ")
      .trim();
    return t;
  };
  const labelFromLine = (raw) => {
    const trimmed = String(raw || "").trim();
    const combined = trimmed.match(/^\d{1,2}:\d{2}[–—-]\d{1,2}:\d{2}\s*-\s*([^\n—-]+?)(?:\s+[—-]\s+.+)?$/);
    if (combined) return combined[1].trim();
    if (/^[A-Z]/.test(trimmed) && /^[^—-]+\s+[—-]\s+/.test(trimmed)) {
      const splitLabel = trimmed.match(/^([^—-]+?)\s+[—-]\s+/);
      if (splitLabel) return splitLabel[1].trim();
    }
    return "";
  };
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    const trimmed = String(line || "").trim();
    const label = labelFromLine(trimmed);
    if (!label) {
      if (!/^\d{1,2}:\d{2}[–—-]\d{1,2}:\d{2}\s*$/.test(trimmed)) lastLandmarkKey = "";
      out.push(line);
      continue;
    }
    const key = landmarkKeyOf(label);
    if (key && lastLandmarkKey && key === lastLandmarkKey) {
      // Adjacent same-landmark stop. Drop this line and its preceding
      // time-only line if split.
      if (
        out.length &&
        /^\d{1,2}:\d{2}[–—-]\d{1,2}:\d{2}\s*$/.test(String(out[out.length - 1] || "").trim()) &&
        !/^\d{1,2}:\d{2}[–—-]\d{1,2}:\d{2}\s*-/.test(trimmed)
      ) {
        out.pop();
      }
      removed += 1;
      continue;
    }
    lastLandmarkKey = key;
    out.push(line);
  }
  if (!removed) return text;
  console.log(`[Itinerary] adjacent-landmark collapse: removed ${removed} same-landmark back-to-back stop(s)`);
  const cleaned = out.join("\n").replace(/\n{3,}/g, "\n\n").trim();
  return mapBlock ? `${cleaned}\n\n${mapBlock}`.trim() : cleaned;
}

// Worldwide-safe single-day zigzag dropper. When a single day mixes a stop
// from a clearly-far cluster (e.g. south Cebu pilgrimage: Simala, Carcar,
// Sibonga, Oslob, Boljoon, Dalaguete, Alcoy, Badian, Moalboal) with a stop
// from the destination's main city cluster, the city stop is removed from
// that day — the route can't realistically zigzag the long drive twice in
// one day. Mirrors the same principle for any destination by listing only
// the far-cluster anchor names + the city-anchor names; if the day has
// only one cluster, nothing is dropped.
const FAR_CLUSTER_RX_BY_DEST = {
  cebu: {
    far: /\b(?:Simala(?:\s+Shrine)?|Carcar(?:\s+Church|\s+Public\s+Market|\s+Public)?|Sibonga|Argao|Oslob|Boljoon|Dalaguete|Alcoy|Badian|Moalboal|Kawasan\s+Falls|Aguinid\s+Falls|Tumalog\s+Falls)\b/i,
    city: /\b(?:Basilica\s+Minore\s+del\s+Santo\s+Ni[ñn]o|Magellan'?s\s+Cross|Cebu\s+Metropolitan\s+Cathedral|Fort\s+San\s+Pedro|Yap[-\s]?San\s+Diego|Casa\s+Gorordo|Museo\s+Sugbo|Cebu\s+Taoist\s+Temple|Temple\s+of\s+Leah|Sirao\s+Garden|TOPS\s+Cebu|Carbon\s+Market|SM\s+(?:City|Seaside)|Ayala\s+Center\s+Cebu|Archdiocesan\s+Shrine|Santuario\s+di\s+Padre\s+Pio|Mactan(?:[-\s]?Cebu)?\s+International\s+Airport|Mactan\s+Shrine|Lapu-Lapu|Mandaue|National\s+Shrine\s+of\s+Saint\s+Joseph|Our\s+Lady\s+of\s+the\s+Rule)\b/i,
  },
  bohol: {
    far: /\b(?:Chocolate\s+Hills|Sagbayan\s+Peak|Anda(?:\s+Beach)?|Candijay|Cabilao|Inabanga)\b/i,
    city: /\b(?:Tagbilaran|Panglao|Alona\s+Beach|Dumaluan\s+Beach|Dauis|Hinagdanan\s+Cave|Bohol\s+Bee\s+Farm)\b/i,
  },
};

function detectActiveDestKeyForZigzag(messages = []) {
  const details = buildConfirmedTripDetailsForValidation(messages);
  const key = String(details.destinationName || details.subArea || "").toLowerCase();
  for (const destKey of Object.keys(FAR_CLUSTER_RX_BY_DEST)) {
    if (key.includes(destKey)) return destKey;
  }
  return "";
}

function dropZigzagCityStopsFromFarClusterDay(reply = "", messages = []) {
  const text = String(reply || "");
  if (!isLikelyItineraryText(text)) return text;
  const destKey = detectActiveDestKeyForZigzag(messages);
  if (!destKey) return text;
  const cfg = FAR_CLUSTER_RX_BY_DEST[destKey];
  if (!cfg) return text;

  const { prose, mapBlock } = splitReplyAndMapBlock(text);
  if (!prose.trim()) return text;

  const lines = prose.split(/\r?\n/);
  // First pass: bucket lines per day and detect which days contain BOTH far
  // and city anchors.
  const daySpans = [];
  let current = null;
  for (let i = 0; i < lines.length; i += 1) {
    const trimmed = String(lines[i] || "").trim();
    if (/^Day\s+\d+\s*[—-]/i.test(trimmed)) {
      if (current) daySpans.push(current);
      current = { start: i, end: i, hasFar: false, hasCity: false };
      continue;
    }
    if (!current) continue;
    current.end = i;
    if (cfg.far.test(trimmed)) current.hasFar = true;
    if (cfg.city.test(trimmed)) current.hasCity = true;
  }
  if (current) daySpans.push(current);

  const zigDays = daySpans.filter((d) => d.hasFar && d.hasCity);
  if (!zigDays.length) return text;

  const dropRanges = new Set();
  for (const span of zigDays) {
    for (let i = span.start; i <= span.end; i += 1) {
      const trimmed = String(lines[i] || "").trim();
      if (!cfg.city.test(trimmed)) continue;
      // Match the activity row this line belongs to: either a combined
      // `HH:MM–HH:MM - <city stop> — ...` line, OR a split-label form
      // (`<city stop> — ...` preceded by a time-only line).
      const isCombined = /^\d{1,2}:\d{2}[–—-]\d{1,2}:\d{2}\s*-\s+/.test(trimmed);
      const isSplitLabel =
        /^[A-Z]/.test(trimmed) &&
        i > span.start &&
        /^\d{1,2}:\d{2}[–—-]\d{1,2}:\d{2}\s*$/.test(String(lines[i - 1] || "").trim());
      if (isCombined) {
        dropRanges.add(i);
      } else if (isSplitLabel) {
        dropRanges.add(i - 1);
        dropRanges.add(i);
      }
    }
  }
  if (!dropRanges.size) return text;
  const kept = lines.filter((_, idx) => !dropRanges.has(idx));
  console.log(`[Itinerary] zigzag day cleanup: removed ${dropRanges.size} city-cluster line(s) from a far-cluster day (${destKey})`);
  const cleaned = kept.join("\n").replace(/\n{3,}/g, "\n\n").trim();
  return mapBlock ? `${cleaned}\n\n${mapBlock}`.trim() : cleaned;
}

function stripAirportFromLocalTripItinerary(reply = "", messages = []) {
  const text = String(reply || "");
  if (!isLikelyItineraryText(text)) return text;
  // OR — local-trip indicator can come from history OR from the reply text.
  const isLocal = detectLocalTripFromMessages(messages) || detectLocalTripFromReplyText(text, messages);
  if (!isLocal) return text;

  const { prose, mapBlock } = splitReplyAndMapBlock(text);
  if (!prose.trim()) return text;

  const lines = prose.split(/\r?\n/);
  const kept = [];
  let removed = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    const trimmed = String(line || "").trim();
    // Match an activity line whose label or description mentions an airport
    // or a return-flight intent. These come as either:
    //   "HH:MM–HH:MM - Mactan-Cebu International Airport - ..."
    //   "HH:MM–HH:MM\nMactan-Cebu International Airport — Transfer to ..."
    // Detect either single-line or split label/description.
    if (
      /^\d{1,2}:\d{2}[–—-]\d{1,2}:\d{2}\s*-\s*[^\n]+/.test(trimmed) &&
      (AIRPORT_OR_INTERCITY_TERMINAL_RX.test(trimmed) || RETURN_FLIGHT_INTENT_RX.test(trimmed))
    ) {
      removed += 1;
      continue;
    }
    // Split style: time on previous line, label on this line.
    if (
      /^[A-Z][^\n]+$/.test(trimmed) &&
      (AIRPORT_OR_INTERCITY_TERMINAL_RX.test(trimmed) || RETURN_FLIGHT_INTENT_RX.test(trimmed)) &&
      kept.length &&
      /^\d{1,2}:\d{2}[–—-]\d{1,2}:\d{2}\s*$/.test(String(kept[kept.length - 1] || "").trim())
    ) {
      kept.pop();
      removed += 1;
      continue;
    }
    kept.push(line);
  }
  // Always also rewrite the cost-breakdown line for local trips: there is no
  // flight/major transfer and no hotel when the user lives in the
  // destination. Replace contradictory budget lines with reality.
  let cleanedJoin = kept.join("\n");
  cleanedJoin = cleanedJoin
    .replace(/(^|\n)[-•*]\s*(?:Flights?\s*\/\s*major\s+transfer|Major\s+transfer\s*\+\s*local\s+transfers|Flight\s*\+\s*local\s+transfers|Flight\s*\+\s*major\s+transfer|Cebu\s*[→\->]\s*[A-Z][^:\n]*?(?:transfer|connection))[^:\n]*:\s*[^\n]+/gi, "$1- Flights/major transfer: Not applicable for a local trip")
    .replace(/(^|\n)\s*Flights?\s*\/\s*major\s+transfer[^:\n]*:\s*[^\n]+/gi, "$1Flights/major transfer: Not applicable for a local trip")
    // Drop hotel-share / hotel-pricing-note lines for local trips.
    .replace(/(^|\n)[-•*]\s*Hotel\s+share\s+estimate[^\n]*/gi, "$1- Accommodation: ₱0 — staying at own home/base")
    .replace(/(^|\n)[-•*]\s*Hotel\s+pricing\s+note[^\n]*\n?/gi, "$1")
    .replace(/(^|\n)[-•*]\s*Hotel:\s*[^\n]+/gi, "$1- Accommodation: ₱0 — staying at own home/base")
    .replace(/(^|\n)[-•*]\s*Accommodation:\s*₱?\s*[\d,]+[^\n]*/gi, "$1- Accommodation: ₱0 — staying at own home/base");
  if (!removed) {
    // Even if no airport stop was found, the budget rewrite may still apply.
    if (cleanedJoin === kept.join("\n")) return text;
  } else {
    console.log(`[Itinerary] local-trip airport strip: removed ${removed} airport/return-flight stop(s)`);
  }
  const cleaned = cleanedJoin.replace(/\n{3,}/g, "\n\n").trim();

  if (!mapBlock) return cleaned;

  try {
    const parsed = extractMapStopsJson(mapBlock);
    if (parsed && Array.isArray(parsed.mapStops)) {
      const filtered = parsed.mapStops.filter((stop) => {
        const combined = `${stop?.label || ""} ${stop?.query || ""}`;
        return !AIRPORT_OR_INTERCITY_TERMINAL_RX.test(combined) && !RETURN_FLIGHT_INTENT_RX.test(combined);
      });
      if (filtered.length !== parsed.mapStops.length) {
        const nextMapBlock = `MAP_STOPS_JSON\n${JSON.stringify({ ...parsed, mapStops: renumberMapStopsByDay(filtered) }, null, 2)}\nEND_MAP_STOPS_JSON`;
        return `${cleaned}\n\n${nextMapBlock}`.trim();
      }
    }
  } catch (e) {
    // keep prose cleanup even if map-stop cleanup fails
  }

  return `${cleaned}\n\n${mapBlock}`.trim();
}

function allConversationText(messages = []) {
  return messages
    .filter((m) => m && (m.role === "user" || m.role === "assistant"))
    .map((m) => String(m.content || ""))
    .join("\n");
}

function activeConversationText(messages = []) {
  const scoped = getActiveTripScopedMessages(messages);
  return allConversationText(scoped.length ? scoped : messages);
}

function activeUserConversationText(messages = []) {
  const scoped = getActiveTripScopedMessages(messages);
  const list = scoped.length ? scoped : messages;
  return (Array.isArray(list) ? list : [])
    .filter((m) => m?.role === "user")
    .map((m) => String(m.content || ""))
    .join("\n");
}

function conversationRequestsNightlifeEveryDay(messages = []) {
  const text = activeUserConversationText(messages);
  return /\bnight\s*life|nightlife|bars?|clubs?|live\s+music\b/i.test(text) &&
    /\b(?:every|each|per)\s+(?:day|night)|daily|nightly\b/i.test(text);
}

function conversationRequestsMustTryFood(messages = []) {
  const text = activeUserConversationText(messages);
  const asksForFoodStops =
    /\b(?:food\s+stops?|restaurants?|eateries|places?\s+to\s+eat|food\s*crawl)\b/i.test(text);
  const asksForNamedDish =
    /\b(?:dish|dishes|must[-\s]?try\s+(?:food|dish|meal)|signature\s+(?:food|dish|meal)|what\s+to\s+eat|local\s+specialty|specialties)\b/i.test(text);
  if (asksForFoodStops && !asksForNamedDish) return false;
  return /\b(?:must[-\s]?try|famous|signature|known)\b[^\n.?!]{0,80}\b(?:food|dish|meal|eat)\b/i.test(text) ||
    /\b(?:food|dish|meal|eat)\b[^\n.?!]{0,80}\b(?:must[-\s]?try|famous|signature|known)\b/i.test(text);
}

function conversationRequestsFamousFoodStops(messages = []) {
  const text = activeUserConversationText(messages);
  return /\b(?:add|include|insert|put|recommend|suggest)\b[^\n.?!]{0,80}\b(?:famous|must[-\s]?try|signature|known|local)\b[^\n.?!]{0,80}\b(?:food\s+stops?|restaurants?|eateries|places?\s+to\s+eat|food\s*crawl)\b/i.test(text) ||
    /\b(?:add|include|insert|put)\b[^\n.?!]{0,80}\b(?:food\s+stops?|food\s*crawl)\b/i.test(text) ||
    /\b(?:famous|must[-\s]?try|signature|known|local)\b[^\n.?!]{0,80}\b(?:food\s+stops?|restaurants?|eateries|places?\s+to\s+eat|food\s*crawl)\b/i.test(text);
}

function conversationRequestsLagoonCategory(messages = []) {
  return /\b(?:hidden\s+)?lagoons?\b|\bturquoise\s+waters?\b/i.test(activeUserConversationText(messages));
}

function replyLooksLikeElNidoTrip(reply = "", messages = []) {
  return /\bel\s+nido\b/i.test(`${reply}\n${activeConversationText(messages)}`);
}

function replaceReplyProse(reply = "", nextProse = "") {
  const split = splitReplyAndMapBlock(reply);
  const prose = sanitizeStrictItineraryReply(String(nextProse || "").trim());
  return split.mapBlock ? `${prose}\n\n${split.mapBlock}`.trim() : prose;
}

function parseStrictActivitiesWithIndexes(prose = "") {
  const lines = String(prose || "").split("\n");
  const activities = [];
  let currentDay = null;
  let order = 0;

  for (let i = 0; i < lines.length; i += 1) {
    const line = String(lines[i] || "").trim();
    const dayMatch = line.match(/^Day\s+(\d+)\s+—/i);
    if (dayMatch) {
      currentDay = Number(dayMatch[1]) || null;
      order = 0;
      continue;
    }

    const activityMatch = line.match(STRICT_ACTIVITY_LINE_RX);
    if (!activityMatch || !currentDay) continue;
    order += 1;
    activities.push({
      day: currentDay,
      order,
      lineIndex: i,
      start: String(activityMatch[1] || "").trim(),
      end: String(activityMatch[2] || "").trim(),
      label: normalizePlaceLabel(activityMatch[3]),
      note: String(activityMatch[4] || "").trim(),
    });
  }

  return { lines, activities };
}

function parseItineraryActivities(text = "") {
  const prose = splitReplyAndMapBlock(text).prose || String(text || "");
  const parsed = parseStrictActivitiesWithIndexes(prose);
  return parsed.activities.map((activity) => {
    const place = normalizePlaceLabel(activity.label || "");
    const start = String(activity.start || "").trim();
    const end = String(activity.end || "").trim();
    const day = Number(activity.day || 0) || 0;
    const order = Number(activity.order || 0) || 0;
    return {
      ...activity,
      day,
      order,
      start,
      end,
      place,
      label: place,
      note: String(activity.note || "").trim(),
      key: `${day}|${start}|${end}|${place}`.toLowerCase(),
      looseKey: `${day}|${place}`.toLowerCase(),
      placeKey: place.toLowerCase(),
    };
  });
}

function itineraryMinutesFromHHMM(value = "") {
  const match = String(value || "").trim().match(/^(\d{2}):(\d{2})$/);
  if (!match) return null;
  const h = Number(match[1]);
  const m = Number(match[2]);
  if (!Number.isFinite(h) || !Number.isFinite(m)) return null;
  return (h * 60) + m;
}

function isNightlifeActivityLabel(label = "", note = "") {
  const labelText = String(label || "");
  const noteText = String(note || "");
  if (/\b(bar|beach\s+bar|sunset\s+bar|cocktail\s+bar|wine\s+bar|pub|club|nightclub|lounge|live\s+music|speakeasy|rooftop|brewery|taproom|night\s+market)\b/i.test(labelText)) {
    return true;
  }
  return /\b(?:nightlife\s+stop|bar\s+stop|live\s+music\s+stop|drinks?\s+at\s+(?:a\s+)?(?:bar|pub|lounge|club))\b/i.test(noteText);
}

function chooseNightlifeVenueForReply(reply = "", day = 1) {
  const used = new Set(
    parseStrictActivitiesWithIndexes(splitReplyAndMapBlock(reply).prose)
      .activities
      .map((a) => normalizeMapStopIdentityText(a.label))
      .filter(Boolean)
  );
  const elNidoPool = [
    "SAVA Beach Bar",
    "Pukka Bar",
    "The Pangolin Bar",
    "Frendz Hostel Rooftop Bar",
  ];
  const genericPool = [
    "Local Night Market",
    "Town Center Live Music Bar",
    "Rooftop Lounge",
  ];
  const pool = replyLooksLikeElNidoTrip(reply) ? elNidoPool : genericPool;
  return pool.find((name) => !used.has(normalizeMapStopIdentityText(name))) || pool[(Math.max(1, day) - 1) % pool.length];
}

function ensureNoBasePlaceholderStops(reply = "", messages = []) {
  if (!replyLooksLikeElNidoTrip(reply, messages)) return { reply, changed: false };

  const split = splitReplyAndMapBlock(reply);
  let parsed = parseStrictActivitiesWithIndexes(split.prose);
  let changed = false;

  for (const activity of parsed.activities) {
    if (!/\bel\s+nido\s+(?:town\s+proper|town\s+center|town\s+centre)\b/i.test(activity.label)) continue;
    parsed.lines[activity.lineIndex] =
      `${activity.start}–${activity.end} - Gusto Gelato - Plan this as a named town lunch or snack anchor; confirm current hours and keep the stop short so the schedule stays realistic.`;
    changed = true;
  }

  if (!changed) return { reply, changed: false };
  return { reply: replaceReplyProse(reply, parsed.lines.join("\n")), changed: true };
}

function ensureLagoonRequestVisible(reply = "", messages = []) {
  if (!conversationRequestsLagoonCategory(messages) || !replyLooksLikeElNidoTrip(reply, messages)) {
    return { reply, changed: false };
  }
  if (/\b(?:Big Lagoon|Small Lagoon|Secret Lagoon|Shimizu Island|Tour A|lagoon[-\s]?set)\b/i.test(reply)) {
    return { reply, changed: false };
  }

  const split = splitReplyAndMapBlock(reply);
  let parsed = parseStrictActivitiesWithIndexes(split.prose);
  const candidates = parsed.activities.filter((a) =>
    a.day >= 2 && /\b(?:beach|view|cliff|island|bay|tour|cadlao|nacpan|las\s+cabañas|las\s+cabanas|corong)\b/i.test(`${a.label} ${a.note}`)
  );
  const target = candidates[0] || parsed.activities.find((a) => a.day >= 2) || parsed.activities[0];
  if (!target) return { reply, changed: false };

  parsed.lines[target.lineIndex] =
    `${target.start}–${target.end} - Big Lagoon - Join an El Nido island-hopping Tour A style lagoon stop for hidden-lagoon scenery and turquoise water; confirm boat timing, environmental fees, and sea conditions before departure.`;
  return { reply: replaceReplyProse(reply, parsed.lines.join("\n")), changed: true };
}

function ensureNamedMustTryDish(reply = "", messages = []) {
  if (!conversationRequestsMustTryFood(messages)) return { reply, changed: false };

  const split = splitReplyAndMapBlock(reply);
  const parsed = parseStrictActivitiesWithIndexes(split.prose);
  const dishRx = /\b(?:kinilaw|tamilok|lato|danggit|sinigang|sisig|lechon|halo-halo|balut|pancit|bicol\s+express)\b/i;
  const foodVenueRx = /\b(?:artcafe|restaurant|trattoria|cafe|kitchen|grill|eatery|bistro|food|market|gelato)\b/i;
  let changed = false;

  for (const activity of parsed.activities) {
    if (!dishRx.test(activity.note) || foodVenueRx.test(activity.label)) continue;
    if (/\b(?:beach|lagoon|lake|park|view|viewpoint|falls?|island)\b/i.test(activity.label)) {
      parsed.lines[activity.lineIndex] =
        `${activity.start}–${activity.end} - ${activity.label} - Make this the scenic stop in the route; save the requested must-try local dish for a named food venue.`;
      changed = true;
    }
  }

  const hasDishAtFoodVenue = parsed.activities.some((a) =>
    dishRx.test(parsed.lines[a.lineIndex] || a.note) && foodVenueRx.test(a.label)
  );
  if (hasDishAtFoodVenue && !changed) {
    return { reply, changed: false };
  }

  const target = parsed.activities.find((a) =>
    foodVenueRx.test(a.label) ||
    /\b(?:dinner|lunch|meal|food|eat)\b/i.test(a.note)
  );
  if (!target) {
    return changed
      ? { reply: replaceReplyProse(reply, parsed.lines.join("\n")), changed: true }
      : { reply, changed: false };
  }

  const dish = replyLooksLikeElNidoTrip(reply, messages) ? "tamilok or kinilaw" : "kinilaw";
  parsed.lines[target.lineIndex] =
    `${target.start}–${target.end} - ${target.label} - Try ${dish} as the named must-try local dish, keep the order flexible for your travel party, and check current menu availability and prices before ordering.`;
  return { reply: replaceReplyProse(reply, parsed.lines.join("\n")), changed: true };
}

function replyLooksLikeManilaOrIntramurosTrip(reply = "", messages = []) {
  return /\b(?:manila|intramuros|binondo|ermita|malate|rizal\s+park)\b/i.test(`${reply}\n${allConversationText(messages)}`);
}

function chooseManilaFoodStopForDay(reply = "", day = 1) {
  const used = new Set(
    parseStrictActivitiesWithIndexes(splitReplyAndMapBlock(reply).prose)
      .activities
      .map((a) => normalizeMapStopIdentityText(a.label))
      .filter(Boolean)
  );
  const pools = {
    1: [
      {
        label: "Ilustrado Restaurant",
        note: "Add the requested famous Manila food stop with heritage Filipino dishes in Intramuros; reserve ahead and keep the meal paced for the day's church-and-history route.",
      },
      {
        label: "Barbara's Heritage Restaurant",
        note: "Add the requested famous Manila food stop for a heritage-style Filipino meal near Intramuros; check current show or buffet availability before going.",
      },
    ],
    2: [
      {
        label: "Wai Ying Fast Food",
        note: "Add a famous Binondo food stop for dim sum, mami, or roast meats; keep orders shareable and expect a busy casual dining setup.",
      },
      {
        label: "Dong Bei Dumplings",
        note: "Add a famous Binondo dumpling stop for kuchay dumplings and quick Chinatown food-crawl energy; bring cash and expect simple seating.",
      },
      {
        label: "Eng Bee Tin Binondo",
        note: "Add a famous pasalubong food stop for hopia and tikoy after the Chinatown church visit; keep it short so the route still flows.",
      },
      {
        label: "Classic Savory Escolta",
        note: "Add a classic Manila food stop near the Quiapo and Binondo route for fried chicken and shareable comfort dishes; confirm the nearest open branch before going.",
      },
    ],
    3: [
      {
        label: "The Aristocrat Restaurant",
        note: "Add a classic Manila food stop for chicken barbecue and Filipino dishes near Malate; use it as the main lunch anchor before the final stops.",
      },
      {
        label: "Café Adriatico",
        note: "Add a classic Malate food stop for a relaxed Filipino-Spanish meal; keep it as the sit-down break before the afternoon route.",
      },
    ],
  };

  const ordered = [
    ...(pools[day] || []),
    ...Object.keys(pools)
      .filter((key) => Number(key) !== Number(day))
      .flatMap((key) => pools[key]),
  ];

  return ordered.find((item) => !used.has(normalizeMapStopIdentityText(item.label))) || null;
}

function ensureFamousFoodStops(reply = "", messages = []) {
  if (!conversationRequestsFamousFoodStops(messages)) return { reply, changed: false };
  if (!replyLooksLikeManilaOrIntramurosTrip(reply, messages)) return { reply, changed: false };

  const split = splitReplyAndMapBlock(reply);
  let parsed = parseStrictActivitiesWithIndexes(split.prose);
  if (!parsed.activities.length) return { reply, changed: false };

  const famousFoodRx = /\b(?:Ilustrado|Barbara'?s|Wai\s+Ying|Dong\s+Bei|Eng\s+Bee\s+Tin|Savory|The\s+Aristocrat|Cafe\s+Adriatico|Café\s+Adriatico)\b/i;
  const existingFamousFood = parsed.activities.filter((a) => famousFoodRx.test(a.label));
  const itineraryDayCount = new Set(parsed.activities.map((a) => a.day)).size;
  const neededCount = Math.min(Math.max(itineraryDayCount, 1), 3);
  if (existingFamousFood.length >= neededCount) return { reply, changed: false };

  let changed = false;
  const targetDays = [...new Set(parsed.activities.map((a) => a.day))]
    .sort((a, b) => a - b)
    .filter((day) => !existingFamousFood.some((a) => a.day === day));

  for (const day of targetDays) {
    parsed = parseStrictActivitiesWithIndexes(parsed.lines.join("\n"));
    const currentFamousFood = parsed.activities.filter((a) => famousFoodRx.test(a.label));
    if (currentFamousFood.length >= neededCount) break;
    if (currentFamousFood.some((a) => a.day === day)) continue;

    const dayActivities = parsed.activities.filter((a) => a.day === day);
    const foodStop = chooseManilaFoodStopForDay(replaceReplyProse(reply, parsed.lines.join("\n")), day);
    if (!foodStop) continue;

    const mealCandidate = dayActivities.find((a) =>
      /\b(?:lunch|dinner|meal|food|eat|restaurant|cafe|café|market)\b/i.test(`${a.label} ${a.note}`) &&
      !/\b(?:public\s+market|church|cathedral|park|shrine|museum|fort|garden)\b/i.test(a.label)
    );

    if (mealCandidate) {
      parsed.lines[mealCandidate.lineIndex] =
        `${mealCandidate.start}–${mealCandidate.end} - ${foodStop.label} - ${foodStop.note}`;
      changed = true;
    } else {
      const lunchGapTarget =
        dayActivities.find((a) => itineraryMinutesFromHHMM(a.start) !== null && itineraryMinutesFromHHMM(a.start) >= 12 * 60) ||
        dayActivities[Math.min(1, dayActivities.length - 1)] ||
        dayActivities[0];
      if (!lunchGapTarget) continue;

      const startMin = itineraryMinutesFromHHMM(lunchGapTarget.start);
      const safeStart = Number.isFinite(startMin) ? Math.max(12 * 60, Math.min(startMin, 18 * 60)) : 12 * 60;
      const safeEnd = Math.min(safeStart + 60, 19 * 60);
      const insertionLine =
        `${formatItineraryMinutes(safeStart)}–${formatItineraryMinutes(safeEnd)} - ${foodStop.label} - ${foodStop.note}`;
      parsed.lines.splice(lunchGapTarget.lineIndex, 0, insertionLine);
      changed = true;
    }

    if (parsed.lines.filter((line) => famousFoodRx.test(line)).length >= neededCount) break;
  }

  if (!changed) return { reply, changed: false };
  return { reply: replaceReplyProse(reply, parsed.lines.join("\n")), changed: true };
}

function ensureNightlifeEveryDay(reply = "", messages = []) {
  if (!conversationRequestsNightlifeEveryDay(messages)) return { reply, changed: false };

  const split = splitReplyAndMapBlock(reply);
  const parsed = parseStrictActivitiesWithIndexes(split.prose);
  if (!parsed.activities.length) return { reply, changed: false };

  let changed = false;
  const dayNumbers = [...new Set(parsed.activities.map((a) => a.day))].sort((a, b) => a - b);
  const removeIndexes = new Set();
  const insertions = [];

  for (const day of dayNumbers) {
    const dayActivities = parsed.activities.filter((a) => a.day === day);
    const nightlife = dayActivities.filter((a) => isNightlifeActivityLabel(a.label, a.note));

    if (nightlife.length > 1) {
      for (const extra of nightlife.slice(1)) {
        removeIndexes.add(extra.lineIndex);
        changed = true;
      }
    }

    if (nightlife.length === 0) {
      const last = dayActivities[dayActivities.length - 1];
      if (!last) continue;
      const lastEnd = itineraryMinutesFromHHMM(last.end);
      const startMin = Number.isFinite(lastEnd) ? Math.min(Math.max(lastEnd + 30, 19 * 60), (22 * 60) + 30) : (20 * 60) + 30;
      const endMin = Math.min(startMin + 90, (23 * 60) + 45);
      const venue = chooseNightlifeVenueForReply(reply, day);
      const newLine =
        `${formatItineraryMinutes(startMin)}–${formatItineraryMinutes(endMin)} - ${venue} - Add the requested one-nightlife-stop-per-day block with drinks or music; keep it optional-light if you want more rest and check current opening hours.`;
      insertions.push({ index: last.lineIndex + 1, line: newLine });
      changed = true;
    }
  }

  let nextLines = parsed.lines;
  if (removeIndexes.size) {
    nextLines = nextLines.filter((_, idx) => !removeIndexes.has(idx));
  }

  for (const insertion of insertions.sort((a, b) => b.index - a.index)) {
    const removedBeforeInsertion = [...removeIndexes].filter((idx) => idx < insertion.index).length;
    nextLines.splice(Math.max(0, insertion.index - removedBeforeInsertion), 0, insertion.line);
  }

  if (!changed) return { reply, changed: false };
  return { reply: replaceReplyProse(reply, nextLines.join("\n")), changed: true };
}

function enforceFinalRequestedItineraryContent(reply = "", messages = []) {
  let nextReply = reply;
  let changed = false;

  for (const fixer of [
    ensureNoBasePlaceholderStops,
    ensureLagoonRequestVisible,
    ensureNamedMustTryDish,
    ensureFamousFoodStops,
    ensureNightlifeEveryDay,
  ]) {
    const result = fixer(nextReply, messages);
    if (result.changed) {
      nextReply = result.reply;
      changed = true;
    }
  }

  return { reply: nextReply, changed };
}

function buildPostItineraryAppendixInstruction({
  budgetPerPerson = null,
  includeCostBreakdown = false,
  includeHotelSuggestions = false,
  accommodationBudget = "",
} = {}) {
  if (!includeCostBreakdown && !includeHotelSuggestions) return "";

  const budgetLabel = budgetPerPerson?.label || "the visible trip budget";
  const hotelBudgetLabel = String(accommodationBudget || "").trim() || "the user's requested nightly budget";
  const hotelBudgetHeading = /^under\b/i.test(hotelBudgetLabel)
    ? `**Budget hotel suggestions ${hotelBudgetLabel}:**`
    : `**Budget hotel suggestions under ${hotelBudgetLabel}:**`;
  const lines = [
    "POST-ITINERARY APPENDIX REQUIRED:",
    "After the last daily activity, insert a clearly separated appendix. Do not include appendix items in MAP_STOPS_JSON.",
  ];

  if (includeCostBreakdown) {
    lines.push(
      `The user has a stated trip budget of ${budgetLabel}. Automatically include a realistic estimated cost breakdown per person; do not wait for the user to ask.`,
      'Use this exact compact section shape: "## Estimated Budget", then the next line "**Estimated total per person:** ~₱X–₱Y". Do not insert a blank line between the heading and estimated total.',
      'Under the estimated total, include consecutive bullet lines beginning with "- " for the trip-appropriate categories: ferry/major transfer or flight/major transfer as the actual route requires, accommodation, food, local transport/day-tour vehicle, entrance fees/activities, and buffer. Use **bold** category labels. Do not put blank lines between bullets. Do not include Nightlife unless the user explicitly asked for nightlife/bars/clubs/drinks.',
      "Keep the numbers realistic for the itinerary, budget tier, route, and dates. If the estimate may exceed the stated budget, say so briefly inside the breakdown.",
      "Insert '---' immediately before the cost heading.",
      "STRICT MARKDOWN: every bullet MUST start with the markdown hyphen \"- \" followed by a **bold** category label, a colon, and the value. Never use the Unicode bullet \"•\". Never separate bullets with blank lines. Never wrap bullets in extra paragraphs or headings.",
      "This appendix is MANDATORY when this instruction is present. Never drop it from the final reply, even when the user did not explicitly ask for cost in the latest message."
    );
  }

  if (includeHotelSuggestions) {
    lines.push(
      "After the cost breakdown if present, insert another '---'.",
      `Use this exact heading shape: "${hotelBudgetHeading}" unless the user gave a different hotel budget.`,
      "Under that heading, provide a compact bullet list of 3-5 specific named stays. Each bullet must start with \"- \" and the **bold stay name**, then rough nightly price/range, short reason, and best-fit note. Do not put blank lines between bullets.",
      "If exact prices are uncertain, give approximate ranges and say prices vary by date/platform.",
      "STRICT MARKDOWN: every bullet MUST start with the markdown hyphen \"- \" followed by the **bold stay name**. Never use the Unicode bullet \"•\". Never separate bullets with blank lines."
    );
  }

  return lines.join("\n");
}

function extractAccommodationBudgetPreference(text = "") {
  const raw = String(text || "").trim();
  if (!raw) return "";

  const m = raw.match(/\b(under|below|less than|max(?:imum)?|up to|around|about)?\s*((?:₱|php|p)\s*)?(\d+(?:[,.]\d+)?)\s*(k|thousand)?\s*(?:per\s*night|pernight|\/night|nightly|a\s+night|each\s+night)\b/i);
  if (!m) return "";

  const qualifierRaw = String(m[1] || "").trim().toLowerCase();
  const qualifier = qualifierRaw
    .replace(/^below$/, "under")
    .replace(/^less than$/, "under")
    .replace(/^maximum$/, "max");
  const numeric = Number(String(m[3] || "").replace(/[,.]/g, ""));
  const amountValue = Number.isFinite(numeric) && numeric > 0
    ? numeric * (m[4] ? 1000 : 1)
    : 0;
  const amount = amountValue
    ? `PHP ${Math.round(amountValue).toLocaleString("en-US")}`
    : String(m[3] || "").trim();

  return `${qualifier ? `${qualifier} ` : ""}${amount}/night per room`;
}

function wantsBaseRecommendationFromAnswer(text = "") {
  const t = String(text || "").trim();
  if (!t) return false;

  const hasRecommendationIntent = /\b(recommend|recommendation|suggest|find|look for|provide|give me|show me|pick|choose)\b/i.test(t);
  const hasBaseOrStayContext =
    /\b(base|area|hotel|hotels|hostel|hostels|accommodation|accommodations|place to stay|places to stay|guesthouse|guesthouses|inn|inns|resort|resorts|lodging|room|rooms|where to stay|budget friendly|budget-friendly)\b/i.test(t) ||
    Boolean(extractAccommodationBudgetPreference(t));

  if (hasRecommendationIntent && hasBaseOrStayContext) return true;

  // Bare recommendation answers in a base-presence context: "recommend
  // me a place first", "pick one for me", "you choose", "your call",
  // "recommend it please". The caller (basePresence branch) only fires
  // when the assistant just asked about a hotel/base, so it's safe to
  // treat a bare recommendation verb as "please pick a base for me"
  // even without an explicit hotel/stay noun.
  if (/^\s*(?:please\s+)?(?:recommend|suggest|pick|choose|find|show|look\s+for)\b[\s\S]{0,40}?\.?\s*$/i.test(t)) return true;
  if (/^\s*(?:you|your)\s+(?:choose|pick|call|decide|recommendation)\b[\s\S]{0,30}?\.?\s*$/i.test(t)) return true;

  return false;
}

function routeLikelyNeedsTransferScopeDecision(merged = {}) {
  // Always treat transferScope as decided. When origin differs from
  // destination, the transport branch in mergePendingTripFromHistory
  // already sets transferScope = "include_transfer". Asking the user a
  // separate "include the transfer or start after arrival?" question is
  // a micro-form-fill step that delays the trip summary; it gets in the
  // way of the conversational flow. The LLM still respects an explicit
  // "start after arrival" phrase if the user types one in any turn.
  void merged;
  return false;
}

function hasTripTransferScopeDecision(merged = {}) {
  return Boolean(String(merged.transferScope || "").trim()) || hasAcceptedTripAssumption(merged, "transferScope");
}

function breakfastPreferenceNeededForTrip(merged = {}) {
  // No longer ask the numbered "1. Fast food / 2. Café / 3. Local
  // Filipino / 4. Healthier" preference question during intake. Once
  // breakfast=included, the LLM picks a sensible venue from the trip
  // theme, budget, start time, and route. The user can still set a
  // specific style mid-conversation ("make breakfast Filipino") and the
  // edit pipeline will honor it. This removes the loop where free-text
  // answers like "near the south bus" failed to match and bounced the
  // user back to the same numbered prompt.
  void merged;
  return false;
}

function getAcceptedTripAssumptions(merged = {}) {
  return merged.acceptedAssumptions instanceof Set ? merged.acceptedAssumptions : new Set();
}

function hasAcceptedTripAssumption(merged = {}, field = "") {
  return getAcceptedTripAssumptions(merged).has(field);
}

function getPendingTripFieldFromAssistantText(text = "") {
  const t = String(text || "").trim();
  if (!t) return "";

  if (assistantMessageAskedMealPreferenceQuestion(t)) return "breakfastPreference";
  // Broad-area sub-area question. Match BEFORE other branches so a user
  // replying with a specific sub-area / "you choose" gets
  // captured as a sub-area choice in mergePendingTripFromHistory and
  // does not slip back through the destination/budget regexes.
  if (/\b(?:palawan|cebu|bohol|japan|thailand|vietnam|indonesia|malaysia|south\s+korea|philippines)\s+is\s+broad\b/i.test(t)) return "broadArea";
  if (/\bdo you want the itinerary to include\b[\s\S]*\btransfer\b|\bstart after you arrive\b|\bstart after arrival\b/i.test(t)) return "transferScope";
  if (/\bdo you want me to recommend a practical base area\b/i.test(t)) return "baseRecommendation";
  if (/\bwhat hotel or base area should i use\b|\bwhat hotel or base area\b|\bwhich hotel or base area\b|\bwhich hotel or area should i use\b/i.test(t)) return "baseArea";
  if (/\bdo you already have a hotel or base area\b|\bdo you have a hotel or base\b|\bgot a hotel\/?base\b|\bpick a practical (?:area|base)\b|\bshould i pick a practical\b|\bshould i recommend one\b/i.test(t)) return "basePresence";
  if (/\bwhat budget should i plan around\b|\bwhat'?s your budget\b|\bbudget, mid-range, or luxury\b|\brough budget\b/i.test(t)) return "budget";
  if (/\bwhere are you starting from\b|\bwhere are you coming from\b|\bstarting point\b|\borigin\b|\bplease share your(?: current)? location\b|\bshare your(?: current)? location\b|\btype your(?: real)? starting area\b|\ballow location access\b|\bdon'?t have your exact device location\b/i.test(t)) return "origin";
  if (/\bwhat time do you want to leave\b|\bwhat time do you expect to arrive\b|\bwhat time would you like\b|\bstart\/departure\/arrival time\b|\bwhat time do you plan to leave\b|\bwhat time do you plan to leave or arrive\b/i.test(t)) return "time";
  if (/\btransport preference\b|\bspecific transport mode\b|\bhow will you travel\b|\bhow are you getting\b|\bhow do you plan to get\b|\bhow will you get (?:there|around)\b|\bmajor transfer\b|\bferry\b|\btrain\b|\bbus\b|\bflight\b|\bcommute\b|\bpublic transport\b/i.test(t)) return "transport";
  if (/\binclude breakfast\b|\bbreakfast in the itinerary\b/i.test(t)) return "breakfast";
  if (/\bwho are you traveling with\b|\bsolo, with partner, family, friends, or group\b|\bwho'?s traveling\b|\bsolo, partner, family, or friends\b/i.test(t)) return "travelers";
  if (/\bwhat date or month\b|\bwhen are you going\b|\bwhat date\b|\bwhat month\b/i.test(t)) return "date";
  if (/\bwhat style of trip\b|\bwhat kind of trip\b|\btheme\b|\bstyle\/theme\b/i.test(t)) return "theme";
  if (/\bhow many days\b|\bnumber of days\b|\bhow many nights\b/i.test(t)) return "duration";
  if (/\bwhich city, island, or province\b|\bwhere exactly are we heading\b|\bdestination\b|\bwhere are you headed\b|\bwhere in [^?]+ are you going\b/i.test(t)) return "destination";

  return "";
}

function routeLikelyNeedsTransportPreference(merged = {}) {
  const origin = String(merged.origin || "").trim();
  const destination = String(merged.destinationName || merged.anchorPlace || "").trim();
  const normalizedOrigin = normalizeTripRegionName(origin);
  const normalizedDestination = normalizeTripRegionName(destination);
  const originAwayFromDestination =
    normalizedOrigin &&
    normalizedDestination &&
    !normalizedOrigin.includes(normalizedDestination) &&
    !normalizedDestination.includes(normalizedOrigin);
  const routeSensitiveDestination =
    isShortTripIslandDestination(destination) &&
    Number(merged.days || 0) >= 1 &&
    Number(merged.days || 0) <= 3;
  const transferSignal = /\b(port|pier|terminal|station|airport|ferry|train|flight|bus|boat)\b/i.test(
    [merged.arrivalPort, merged.transportMode].filter(Boolean).join(" ")
  );

  return Boolean(originAwayFromDestination || routeSensitiveDestination || transferSignal);
}

function isEarlyTripStart(value = "") {
  const t = String(value || "").trim().toLowerCase();
  if (!t) return false;
  if (/\b(early|morning|sunrise|first trip|first ferry)\b/i.test(t)) return true;

  const m = t.match(/\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\b/i);
  if (!m) return false;

  let hour = Number(m[1]);
  const meridiem = String(m[3] || "").toLowerCase();
  if (meridiem === "pm" && hour < 12) hour += 12;
  if (meridiem === "am" && hour === 12) hour = 0;
  return Number.isFinite(hour) && hour >= 4 && hour < 9;
}

function breakfastPreferenceIsRelevant(merged = {}) {
  // Only ask about breakfast when the user has explicitly anchored the
  // trip on breakfast or food/meal timing. 1-day trips and early-morning
  // starts are NOT enough — that turned breakfast into a default
  // micro-form-fill question that bounced the user away from the
  // blueprint summary. If the user mentions famous food, it's handled
  // inside the itinerary, not here.
  const combined = [
    merged.theme,
    merged.anchorPlace,
    merged.destinationName,
  ].filter(Boolean).join(" ");

  return /\b(breakfast|brunch|early\s+meal|silog|cafe|cafes|coffee\s+shop|food\s+(?:trip|tour|crawl)|where\s+to\s+eat)\b/i.test(combined);
}

function isCurrentLocationReference(value = "") {
  return /\b(my\s+current\s+location|current\s+location|device\s+location|my\s+location|from\s+here|where\s+i\s+am)\b/i.test(String(value || ""));
}

function hasExactDeviceLocation(locationContext = {}) {
  const exact = locationContext?.exact || null;
  return Boolean(
    exact &&
      Number.isFinite(Number(exact.lat)) &&
      Number.isFinite(Number(exact.lng))
  );
}

function tripOriginAndDestinationDiffer(merged = {}) {
  const origin = String(merged.origin || "").trim();
  const destination = String(merged.destinationName || merged.anchorPlace || "").trim();
  const normalizedOrigin = normalizeTripRegionName(origin);
  const normalizedDestination = normalizeTripRegionName(destination);

  if (isCurrentLocationReference(origin)) return false;

  return Boolean(
    normalizedOrigin &&
      normalizedDestination &&
      !normalizedOrigin.includes(normalizedDestination) &&
      !normalizedDestination.includes(normalizedOrigin)
  );
}

function looksLikeTransportUncertainty(text = "") {
  const t = String(text || "").trim();
  if (!t) return false;

  return Boolean(
    /\b(?:i|we)\s+(?:don'?t|do not)\s+know\s+(?:how|what|which|the way|the route|transport|transportation)\b/i.test(t) ||
    /\b(?:not familiar|unfamiliar|first time|first-time|no idea|no clue)\b[\s\S]*\b(?:how to get|transport|transportation|commute|bus|route|getting there|get there)\b/i.test(t) ||
    /\b(?:you choose|you decide|recommend|suggest)\s+(?:the\s+)?(?:transport|transportation|route|best way|way to get there)\b/i.test(t) ||
    /\b(?:don'?t|do not)\s+know\s+(?:how to get there|what to ride|which transport|what transport|the route)\b/i.test(t)
  );
}

// Destination-aware transport default. When the user says "no idea" /
// "you decide" / "I don't know transport there" — or has not been asked
// about transport yet but the route is well-known — this helper returns
// the practical mode travelers actually use. Without this, intake either
// re-asks transport or dumps the generic phrase "commute/public
// transport". Returns "" for routes we don't have a practical default
// for; caller falls back to generic mode.
function getDestinationAwareTransportDefault(merged = {}) {
  const dest = String(
    `${merged.destinationName || ""} ${merged.anchorPlace || ""} ${merged.baseArea || ""}`
  ).toLowerCase();
  const origin = String(merged.origin || "").toLowerCase();
  const startsFromCebuMainland =
    /\b(?:cebu|mandaue|mactan|lapu[-\s]?lapu|talisay|consolacion)\b/.test(origin);
  if (!dest) return "";

  if (/\bsiargao\b/.test(dest)) {
    return "airport van/tricycle to General Luna; habal-habal/tricycle around the island";
  }
  if (/\bmoalboal\b/.test(dest)) {
    if (/\bcebu\b/.test(origin)) {
      return "bus/van from Cebu South Bus Terminal to Moalboal; tricycle/habal-habal to Panagsama";
    }
    return "bus/van to Moalboal; tricycle/habal-habal to Panagsama";
  }
  if (/\b(?:bohol|panglao)\b/.test(dest)) {
    if (/\bcebu\b/.test(origin)) {
      return "ferry from Cebu to Tagbilaran; van/taxi/tricycle to Panglao";
    }
    return "ferry to Tagbilaran; van/taxi/tricycle to Panglao";
  }
  if (/\bcamiguin\b/.test(dest)) {
    if (/\bcebu\b/.test(origin)) {
      return "schedule-dependent sea/land or flight connection from Cebu to Camiguin; local multicab/habal-habal/van transfers around Camiguin";
    }
    return "schedule-dependent ferry/sea or flight connection to Camiguin; local multicab/habal-habal/van transfers around Camiguin";
  }
  if (/\b(?:bantayan|santa\s+fe|sta\.?\s*fe|madridejos)\b/.test(dest) && startsFromCebuMainland) {
    return "bus from Cebu North Bus Terminal to Hagnaya; ferry to Santa Fe; tricycle/habal-habal around the island";
  }
  if (/\bboracay\b/.test(dest)) {
    return "flight to Caticlan; van + Caticlan Jetty Port ferry to Cagban; tricycle/e-trike around stations";
  }
  return "";
}

function normalizeTripTransportAnswer(text = "", merged = {}) {
  const t = String(text || "").trim();
  if (!t) return null;

  const destinationText = String(merged.destinationName || merged.anchorPlace || "").trim();
  const destinationKey = normalizeTripRegionName(destinationText);
  const originAwayFromDestination = tripOriginAndDestinationDiffer(merged);
  const isSiargao = /\bsiargao\b/i.test(destinationText) || destinationKey.includes("siargao");
  const hasFlightLike = /\b(flight|fly|plane|airport)\b/i.test(t);
  const hasBusLike =
    /\b(bus|coach|v[-\s]?hire|van|public bus|ceres|mybus)\b/i.test(t);
  const hasCommuteLike =
    /\b(commute|commuting|we will commute|we'?ll commute|public transport|public transit|public transportation)\b/i.test(t);
  const hasPracticalLike =
    /\b(practical transfers?|local transport|use practical|as needed)\b/i.test(t);
  const noPreference =
    looksLikeTripUnknownAnswer(t) ||
    looksLikeTransportUncertainty(t) ||
    /\b(no preference|any|whatever works|not sure|unsure)\b/i.test(t);

  if (hasFlightLike) {
    return {
      mode: isSiargao
        ? "flight + airport van/tricycle + local habal-habal/tricycle"
        : "flight + airport/local transport",
      acceptedAssumption: false,
    };
  }

  if (/\b(private car|own car|car|drive|driving)\b/i.test(t) && /\bferr(?:y|ies)\b/i.test(t)) {
    return { mode: "private car + ferry", acceptedAssumption: false };
  }

  if (/\b(private car|own car|car|drive|driving)\b/i.test(t)) {
    return { mode: "private car", acceptedAssumption: false };
  }

  if (
    /\b(rent(?:al|ing)?\s+(?:a\s+)?)?(?:motor\s*cycle|motorcycle|motor\s*bike|motorbike|scooter|moped|habal[-\s]?habal)\b/i.test(t) ||
    /\brent\s+(?:a\s+|an\s+)?(?:motor\s*cycle|motorcycle|motor\s*bike|motorbike|scooter|moped)\b/i.test(t)
  ) {
    const islandLeg = isShortTripIslandDestination(destinationText);
    return {
      mode: islandLeg ? "commute/bus + ferry + rented motorcycle/scooter" : "rented motorcycle/scooter",
      acceptedAssumption: false,
    };
  }

  if (hasBusLike) {
    return {
      mode: originAwayFromDestination ? "bus/commute + local transport" : "bus/local transport",
      acceptedAssumption: false,
    };
  }

  if (hasCommuteLike) {
    return { mode: "commute/public transport", acceptedAssumption: false };
  }

  if (hasPracticalLike || noPreference) {
    const aware = getDestinationAwareTransportDefault(merged);
    if (aware) {
      return { mode: aware, acceptedAssumption: noPreference };
    }
    return {
      mode: originAwayFromDestination
        ? "commute/public transport"
        : "practical transfers/local transport as needed",
      acceptedAssumption: noPreference,
    };
  }

  return null;
}


function isSimpleLocalDayTrip(merged = {}) {
  const days = Number(merged.days || 0);
  const destination = String(merged.destinationName || merged.anchorPlace || "").trim();
  const combined = [
    merged.theme,
    merged.anchorPlace,
    merged.destinationName,
  ].filter(Boolean).join(" ");

  return Boolean(
    days === 1 &&
      !isShortTripIslandDestination(destination) &&
      /\b(shopping|mall|malls|food|cafe|cafes|city|highlights|museum|church|park|local)\b/i.test(combined)
  );
}

// Treat origin==destination (or "I'm from <destination>") as a local
// trip regardless of duration. Used to skip the hotel/base question and
// to render the local-trip summary section. The user can still get
// hotel recommendations later by explicitly asking — see buildTripBlueprintReply.
function isSameOriginDestinationLocalTrip(merged = {}) {
  const origin = normalizeTripRegionName(merged.origin || "");
  if (!origin) return false;
  const destinationCandidates = [
    merged.anchorPlace,
    merged.destinationName,
    merged.broadRegion,
    merged.country,
  ].map((v) => normalizeTripRegionName(v || "")).filter(Boolean);
  if (!destinationCandidates.length) return false;
  return destinationCandidates.some((d) =>
    d === origin || d.includes(origin) || origin.includes(d)
  );
}

function formatTripTransportNotes(merged = {}) {
  const originText = String(merged.origin || "").trim();
  const destinationText = String(merged.destinationName || merged.anchorPlace || "the destination").trim();
  const transportMode = String(merged.transportMode || "").trim();
  const arrivalPort = String(merged.arrivalPort || "").trim();
  const transferScope = String(merged.transferScope || "").trim();
  const originAwayFromDestination = tripOriginAndDestinationDiffer(merged);
  const localOnly = /\b(local transport|public transport|public transit|commute|practical transfers|as needed)\b/i.test(transportMode);
  const privateCar = /\b(private car|own car|car|drive|driving)\b/i.test(transportMode);
  const seaOrPortSignal = /\b(ferry|boat|sea|water|island|isle|archipelago|port|pier|harbor|harbour|coast|coastal)\b/i.test(
    [transportMode, arrivalPort, originText, destinationText].filter(Boolean).join(" ")
  );

  if (privateCar && (!originAwayFromDestination || isSimpleLocalDayTrip(merged))) {
    return "private car";
  }

  if (originText && originAwayFromDestination) {
    if (transferScope === "start_after_arrival") {
      return `start after arrival in ${destinationText}; local transport around the destination`;
    }

    if (/\bflight|airport\b/i.test(transportMode)) {
      const scopePrefix = transferScope === "include_transfer" ? "include transfer: " : "";
      if (/\bsiargao\b/i.test(destinationText)) {
        return `${scopePrefix}flight from ${originText} to Siargao, then airport van/tricycle to General Luna and habal-habal/tricycle around the island`;
      }
      return `${scopePrefix}flight from ${originText} to ${destinationText}, then airport/local transport around ${destinationText}`;
    }

    if (/\b(commute|public transport|public transit|bus|van)\b/i.test(transportMode)) {
      const transferType = seaOrPortSignal ? "public transport/ferry transfer" : "public transport";
      const routeHint = seaOrPortSignal ? "using the practical ferry/bus links to verify" : "using the practical bus/van route to verify";
      const scopePrefix = transferScope === "include_transfer" ? "include transfer: " : "";
      return `${scopePrefix}${transferType} from ${originText} to ${destinationText} (${routeHint}), then local transport around ${destinationText}`;
    }


    const transferLabel = seaOrPortSignal ? "ferry/sea transfer" : "major transfer";
    const transferCaveat = seaOrPortSignal ? "" : " using provider/map routing to confirm the exact transfer type";
    const preferredMode = transportMode && !localOnly ? `Preferred mode: ${transportMode}; ` : transportMode ? `Preferred mode: ${transportMode}; ` : "";
    const scopePrefix = transferScope === "include_transfer" ? "include transfer: " : "";
    return `${scopePrefix}${preferredMode}${transferLabel} from ${originText} to ${destinationText}${transferCaveat}, then local transport around the destination`;
  }

  const notes = [
    transportMode ? `Mode: ${transportMode}` : "",
    arrivalPort ? `Arrival point/port: ${arrivalPort}` : "",
  ].filter(Boolean);

  return notes.join("; ");
}

function formatTripRouteNote(merged = {}) {
  const originText = String(merged.origin || "").trim();
  const anchor = String(merged.anchorPlace || "").trim();

  if (isCurrentLocationReference(originText) && anchor) {
    return `start from current location, then ${anchor} first`;
  }

  if (anchor) {
    return `${anchor} first`;
  }

  return "";
}

// Small table of high-confidence "practical traveler base" defaults for
// destinations TravelMate's PH user base hits most. Each entry is a
// regex match on the destination text plus a function that returns the
// base area (function form lets us pick Station 1 vs Station 2 by
// budget). Add a row to extend coverage; do NOT add destinations the
// LLM can already reason about from world knowledge — for those we
// fall through and let formatTripBaseLine build a per-destination hint
// the LLM can act on (see PRACTICAL_BASE_FALLBACK_HINT below).
//
// Why this is intentionally small: a global hard-coded list rots fast
// (neighborhoods get popular and unpopular), and the LLM already knows
// that travelers to Bali base in Seminyak/Ubud, Tokyo travelers base
// in Shinjuku/Shibuya, Bangkok in Sukhumvit, etc. The table is only
// for cases where the LLM has been observed to pick a worse default
// than the practical local one (e.g. Bohol → "Tagbilaran" instead of
// "Panglao / Alona Beach").
const PRACTICAL_BASE_AREA_RULES = [
  { match: /\bsiargao\b/i, base: () => "General Luna" },
  { match: /\b(?:bohol|panglao)\b/i, base: () => "Panglao / Alona Beach" },
  { match: /\bcamiguin\b/i, base: () => "Mambajao / Yumbing" },
  { match: /\bmoalboal\b/i, base: () => "Panagsama" },
  { match: /\bboracay\b/i, base: ({ budget }) => (/\bluxury\b/i.test(budget) ? "Station 1" : "Station 2") },
  { match: /\bbantayan\b/i, base: () => "Santa Fe" },
];

function getPracticalBaseAreaDefault(merged = {}) {
  const dest = String(merged.destinationName || merged.anchorPlace || "").trim();
  const budget = String(merged.budget || "").trim();
  if (!dest) return "";

  for (const rule of PRACTICAL_BASE_AREA_RULES) {
    if (rule.match.test(dest)) {
      return String(rule.base({ dest, budget }) || "").trim();
    }
  }
  return "";
}

function formatTripBaseLine(merged = {}) {
  const base = String(merged.baseArea || "").trim();
  const baseStatus = String(merged.baseStatus || "").trim();
  const accommodationBudget = String(merged.accommodationBudget || "").trim();

  if (base) return base;
  if (baseStatus === "current_location") return "";
  if (baseStatus === "recommend") {
    const practical = getPracticalBaseAreaDefault(merged);
    if (practical) return `${practical} (recommended practical base)`;
    // Worldwide fallback: name the destination explicitly so the LLM
    // picks the typical traveler base area from world knowledge
    // (Seminyak/Ubud for Bali, Shinjuku for Tokyo, Sukhumvit for
    // Bangkok, etc.) instead of the previous generic placeholder that
    // the LLM was free to ignore.
    const dest = String(merged.destinationName || merged.anchorPlace || "").trim();
    if (dest) {
      return `recommend the typical practical traveler base area for ${dest} (popular neighborhood, walkable to the main attractions or transit hub) based on world/provider/map context`;
    }
    return "recommend a practical base area near the main route, based on provider/map context";
  }
  if (baseStatus === "destination_center") {
    return isSimpleLocalDayTrip(merged) ? "" : "no fixed base; keep route centered around the main destination route";
  }

  return "";
}


function formatAnchorPlaceForSummary(merged = {}) {
  const anchor = String(merged.anchorPlace || "").trim();
  const destination = String(merged.destinationName || "").trim();
  if (!anchor) return "";

  if (destination && !normalizeTripRegionName(anchor).includes(normalizeTripRegionName(destination))) {
    return `${anchor}, ${destination}`;
  }

  return anchor;
}

function buildClarifyingQuestionsReply({
  destinationName = "",
  country = "",
  anchorPlace = "",
  date = "",
  travelers = "",
  theme = "",
  budget = "",
  startTime = "",
  transportMode = "",
  hasDestination = false,
  hasDuration = false,
  hasTheme = false,
  hasDate = false,
  hasTravelers = false,
  hasBudget = false,
  hasOrigin = false,
  hasStartTime = false,
  hasBaseDecision = false,
  baseStatus = "",
  hasBaseArea = false,
  needsTransportPreference = false,
  hasTransportPreference = false,
  needsTransferScopeDecision = false,
  hasTransferScopeDecision = false,
  needsBreakfastDecision = false,
  hasBreakfastDecision = false,
  needsBreakfastPreference = false,
  hasBreakfastPreference = false,
  origin = "",
} = {}) {
  const destinationLabel = String(destinationName || anchorPlace || "").trim();
  const countryLabel = String(country || "").trim();
  const originLabel = String(origin || "").trim();
  const originDisplay = originLabel ? titleCaseTripPlace(originLabel) : "";
  const dateLabel = String(date || "").trim();
  const travelersLabel = String(travelers || "").trim();
  const themeLabel = String(theme || "").trim();
  const budgetLabel = String(budget || "").trim();
  const startLabel = String(startTime || "").trim();
  const transportLabel = String(transportMode || "").trim();
  const tripLabel = destinationLabel || countryLabel || "this trip";

  // 1. Destination — short, no option string.
  if (!hasDestination) {
    if (countryLabel) return `Got it — ${countryLabel} is broad. Where in ${countryLabel} are you going?`;
    return "Where are you headed?";
  }

  // 2. Duration — acknowledge destination, short ask.
  if (!hasDuration) {
    return `Nice — ${tripLabel}. How many days?`;
  }

  // 3. Group date + travelers + budget when 2+ are missing. The merge
  // function already extracts each field from one multi-fact reply.
  const missingDate = !hasDate;
  const missingTravelers = !hasTravelers;
  const missingBudget = !hasBudget;
  const missingDTBcount = (missingDate ? 1 : 0) + (missingTravelers ? 1 : 0) + (missingBudget ? 1 : 0);

  if (missingDTBcount >= 2) {
    const parts = [];
    if (missingDate) parts.push("when you're going");
    if (missingTravelers) parts.push("who's traveling");
    if (missingBudget) parts.push("rough budget — budget, mid-range, or luxury");
    return `Got it — ${tripLabel}. To shape it well, share ${parts.join(", ")}.`;
  }

  if (missingDate) return `Got it. What date or month?`;
  if (missingTravelers) {
    const ack = dateLabel ? `Got it — ${dateLabel}. ` : "";
    return `${ack}Who's traveling — solo, partner, family, or friends?`;
  }
  if (missingBudget) {
    const ack = travelersLabel ? `Got it — ${travelersLabel.toLowerCase()}. ` : "";
    return `${ack}Rough budget — budget, mid-range, or luxury?`;
  }

  // 4. Pair origin + style when both missing. The merge layer already
  // extracts origin and theme from a single multi-fact answer like
  // "cebu, i want to try all of it", so asking them together is safe.
  if (!hasTheme && !hasOrigin) {
    const ack = budgetLabel ? `Got it, ${budgetLabel}. ` : "";
    return `${ack}Where are you starting from, and what kind of trip do you want — relaxed, adventurous, food, or famous highlights?`;
  }

  if (!hasTheme) {
    const ack = travelersLabel ? `Got it, ${travelersLabel.toLowerCase()}. ` : "Got it. ";
    return `${ack}What kind of trip do you want — relaxed, adventurous, food, or famous highlights?`;
  }

  if (!hasOrigin) {
    const ack = themeLabel ? `Good — I'll shape it around ${themeLabel}. ` : "";
    return `${ack}Where are you starting from?`;
  }

  // 5. Pair start time + base presence when both missing. The generic
  // "no hotel yet" detector in mergePendingTripFromHistory captures the
  // base-presence answer even when the time pattern matches first.
  if (!hasStartTime && !hasBaseDecision) {
    const ack = originDisplay ? `Got it — coming from ${originDisplay}. ` : "";
    const dest = destinationLabel || "the destination";
    return `${ack}What time do you plan to leave or arrive, and do you already have a hotel/base in ${dest} or should I recommend one?`;
  }

  if (!hasStartTime) {
    const ack = originDisplay ? `Got it — coming from ${originDisplay}. ` : "";
    return `${ack}What time do you plan to leave or arrive?`;
  }

  if (!hasBaseDecision) {
    const timeAck = startLabel ? `Thanks — ${formatTripClockTime(startLabel)} as the start. ` : "";
    return destinationLabel
      ? `${timeAck}Got a hotel/base in ${destinationLabel}, or should I pick a practical area?`
      : `${timeAck}Got a hotel/base, or should I pick a practical area?`;
  }

  if (baseStatus === "has_base" && !hasBaseArea) {
    return "Which hotel or area should I use as the base?";
  }

  if (baseStatus === "none") {
    if (needsTransportPreference && !hasTransportPreference) {
      return `Got it — I'll pick a practical base. How will you get there and around — public transport, private car, or no preference?`;
    }
    return "Got it — I'll pick a practical base for the route.";
  }

  // 6. Transport — rare, because Edit L auto-fills transportMode for
  // well-known PH routes (Cebu→Bohol, Cebu→Moalboal, Siargao, etc.).
  if (needsTransportPreference && !hasTransportPreference) {
    const baseAck = baseStatus === "recommend" ? `Got it — I'll pick a practical base. ` : "";
    return `${baseAck}How will you get there and around — public transport, private car, or no preference?`;
  }

  // Once essentials are complete, return "" so the caller goes straight
  // to the trip blueprint summary. We deliberately do NOT ask:
  //   - transferScope (already decided in mergePendingTripFromHistory)
  //   - breakfast (handled in the itinerary, not as an intake question)
  //   - breakfast preference
  void needsTransferScopeDecision;
  void hasTransferScopeDecision;
  void needsBreakfastDecision;
  void hasBreakfastDecision;
  void needsBreakfastPreference;
  void hasBreakfastPreference;
  void transportLabel;
  return "";
}


// Layla.ai-style trip blueprint card. Restates the inferred plan with
// Route / Dates / Travelers / Purpose lines so the user can spot wrong
// assumptions before any tokens are spent on a full itinerary. Pulls
// from mergePendingTripFromHistory so multi-turn pending state shows up.
function isUnsafeTripSummaryValue(value = "") {
  const raw = String(value || "").trim();
  return !raw || /\b(?:provider[-\s]?resolved|placeholder|unknown|tbd|to confirm)\b/i.test(raw);
}

function cleanTripSummaryValue(value = "") {
  const raw = String(value || "").trim();
  if (isUnsafeTripSummaryValue(raw)) return "";

  return raw
    .replace(/\s+(?:which|because|since)\s+.+$/i, "")
    .replace(/\s*,\s*(?:which|because|since)\s+.+$/i, "")
    .replace(/\s+—\s+.+$/i, "")
    .replace(/\s+-\s+.+$/i, "")
    .replace(/\s+/g, " ")
    .replace(/[,.]\s*$/g, "")
    .trim();
}

async function buildTripBlueprintReply(messages = [], appContext = {}) {
  const merged = mergePendingTripFromHistory(messages, 20);
  const timeZone = String(appContext?.timezone || "").trim() || "UTC";
  const todayIso = getTodayISOForTimeZone(timeZone);
  const currentYear = String(todayIso || "").slice(0, 4);
  const locationContext = appContext?.location || {};

  // Resolve a real device-location label whenever the user said "current
  // location" / "my location" etc. Priority:
  //   1. reverseGeocode(exact lat/lng)         — actual GPS label
  //   2. selectedPlace.anchorText / .label     — anchor explicitly chosen in the app
  //   3. typedArea                             — area the user typed earlier
  //   4. declaredCity                          — "I'm in Cebu City" extracted upstream
  // Only ask the user again if NONE of these are available.
  if (isCurrentLocationReference(merged.origin)) {
    const exact = locationContext?.exact || null;
    const selectedPlace = locationContext?.selectedPlace || null;
    let resolvedLabel = "";

    if (exact && Number.isFinite(Number(exact.lat)) && Number.isFinite(Number(exact.lng))) {
      try {
        const resolved = await reverseGeocodeLabel(exact.lat, exact.lng);
        resolvedLabel = sanitizeLocationReplyLabel(resolved?.label || "");
      } catch {}
    }

    if (!resolvedLabel) {
      resolvedLabel =
        sanitizeLocationReplyLabel(selectedPlace?.anchorText || "") ||
        sanitizeLocationReplyLabel(selectedPlace?.label || "") ||
        sanitizeLocationReplyLabel(locationContext?.typedArea || "") ||
        sanitizeLocationReplyLabel(locationContext?.declaredCity || "");
    }

    if (resolvedLabel) {
      merged.origin = resolvedLabel;
      merged.alreadyThere = false;
    } else {
      const destinationLabel = String(merged.destinationName || merged.anchorPlace || "the destination").trim();
      return `I don't have your exact device location yet${destinationLabel ? ` for the ${destinationLabel} trip` : ""}. Allow location access in the app, or type the area/landmark you're starting from (e.g. "Cebu City" or "Doña Rosario Village, Pakna-an") and I'll route this accurately.`;
    }
  }

  const country = String(merged.country || merged.broadRegion || "").trim();
  // When the user named a sub-area (e.g. "El Nido" inside "Palawan"),
  // promote the anchor to the visible destination so the blueprint
  // card says "Destination: El Nido, Palawan, Philippines" instead of
  // "Destination: Palawan, Philippines". We still keep the broad name
  // attached so the user can see the full context, but the anchor leads.
  const broadDestination = String(merged.destinationName || "").trim();
  const subArea = String(merged.anchorPlace || "").trim();
  const subAreaIsMoreSpecific =
    subArea &&
    broadDestination &&
    subArea.toLowerCase() !== broadDestination.toLowerCase() &&
    !broadDestination.toLowerCase().includes(subArea.toLowerCase());
  const rawDestination = subAreaIsMoreSpecific
    ? (broadDestination ? `${subArea}, ${broadDestination}` : subArea)
    : (broadDestination || subArea || "your destination");
  const destination =
    country && rawDestination && !rawDestination.toLowerCase().includes(country.toLowerCase())
      ? `${rawDestination}, ${country}`
      : rawDestination;
  const safeDestination = cleanTripSummaryValue(destination) || "your destination";

  const days = Number(merged.days || 0);
  let dates = String(merged.date || "").trim();
  if (dates && currentYear && !/\b\d{4}\b/.test(dates) && /\b(?:january|february|march|april|may|june|july|august|september|october|november|december)\b/i.test(dates)) {
    dates = `${dates}, ${currentYear}`;
  }

  const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
  const monthDayMatch = dates.match(/^\s*(january|february|march|april|may|june|july|august|september|october|november|december)\s+(\d{1,2}),\s*(\d{4})\s*$/i);
  if (monthDayMatch) {
    const monthIndex = monthNames.findIndex((m) => m.toLowerCase() === String(monthDayMatch[1] || "").toLowerCase());
    const startDay = Number(monthDayMatch[2]);
    const year = Number(monthDayMatch[3]);
    const startDate = new Date(Date.UTC(year, monthIndex, startDay, 12, 0, 0));
    if (monthIndex >= 0 && Number.isFinite(startDay) && Number.isFinite(year) && !Number.isNaN(startDate.getTime())) {
      if (days > 1) {
        const endDate = new Date(startDate);
        endDate.setUTCDate(startDate.getUTCDate() + days - 1);
        const startMonth = monthNames[startDate.getUTCMonth()];
        const endMonth = monthNames[endDate.getUTCMonth()];
        const startLabel = `${startMonth} ${startDate.getUTCDate()}`;
        const endLabel =
          startMonth === endMonth && startDate.getUTCFullYear() === endDate.getUTCFullYear()
            ? `${endDate.getUTCDate()}`
            : `${endMonth} ${endDate.getUTCDate()}`;
        dates = `${startLabel}–${endLabel}, ${endDate.getUTCFullYear()}`;
      } else {
        dates = `${monthNames[monthIndex]} ${startDay}, ${year}`;
      }
    }
  }

  const acceptedAssumptions = getAcceptedTripAssumptions(merged);
  const duration = days ? `${days} day${days === 1 ? "" : "s"}` : "1 day (assumption accepted)";
  const travelers = cleanTripSummaryValue(merged.travelers) || "general traveler (assumption accepted)";
  const rawStyle = merged.theme || (merged.interests ? "Interests-based trip" : "General travel");
  // "all of it" / "everything" / "mixed" → human-readable summary so the
  // card explains what mixed actually means instead of dumping the keyword.
  const style = /\bmixed\b/i.test(rawStyle)
    ? "mixed — nature + beach + history + local food highlights"
    : rawStyle;
  const safeStyle = cleanTripSummaryValue(style) || "General travel";
  const startTime = String(merged.itineraryStartTime || merged.startTime || "").trim();
  const preTripTravel = cleanTripSummaryValue(merged.preTripTravel);
  const overnightBase = cleanTripSummaryValue(merged.overnightBase);
  const itineraryStartPoint = cleanTripSummaryValue(merged.itineraryStartPoint);
  const departureTime = String(merged.departureTime || "").trim();
  const arrivalTime = String(merged.arrivalTime || "").trim();
  const transportMode = String(merged.transportMode || "").trim();
  const arrivalPort = String(merged.arrivalPort || "").trim();
  const breakfastStatus = String(merged.breakfast || "").trim();
  const breakfastTiming = String(merged.breakfastTiming || "").trim();
  const breakfastPreference = String(merged.breakfastPreference || "").trim();
  const accommodationBudget = String(merged.accommodationBudget || "").trim();
  const breakfastDetails = [breakfastTiming, breakfastPreference].filter(Boolean).join(" — ");
  const breakfastLine =
    breakfastStatus === "included"
      ? breakfastDetails
        ? `included — ${breakfastDetails}`
        : "included"
      : breakfastStatus === "not included"
      ? "not included"
      : "not included unless requested";
  const scopeNote = /\bmixed\b/i.test(safeStyle)
    ? days === 1
      ? "For 1 day, I’ll keep this balanced instead of trying to fit everything: culture/history, local food, and one scenic or beach-style stop."
      : "I’ll keep this realistic — no overloaded days. Distant areas get travel buffers, and weak stops are dropped before times overlap."
    : "";
  const budget = merged.budget
    ? `${merged.budget.charAt(0).toUpperCase()}${merged.budget.slice(1)}${acceptedAssumptions.has("budget") ? " (assumption accepted)" : ""}`
    : "";
  const base = cleanTripSummaryValue(merged.baseArea);
  const baseStatus = String(merged.baseStatus || "").trim();

  const originText = cleanTripSummaryValue(merged.origin);
  const isIslandShortTrip =
    isShortTripIslandDestination(rawDestination) && days >= 1 && days <= 3;
  const normalizedOrigin = normalizeTripRegionName(originText);
  const normalizedDestination = normalizeTripRegionName(rawDestination);
  const originAwayFromDestination =
    normalizedOrigin &&
    normalizedDestination &&
    !normalizedOrigin.includes(normalizedDestination) &&
    !normalizedDestination.includes(normalizedOrigin);
  const assumptions = [];
  if (acceptedAssumptions.has("date")) assumptions.push("Date/month was flexible, so timing remains a planning assumption.");
  if (acceptedAssumptions.has("origin")) assumptions.push("Origin was unknown, so routing starts from the main destination area.");
  if (acceptedAssumptions.has("time")) assumptions.push("Start time was unknown, so I’ll use a practical morning start.");
  if (acceptedAssumptions.has("budget")) assumptions.push("Budget was unknown, so I’ll use a mid-range planning assumption.");
  if (acceptedAssumptions.has("transport")) assumptions.push("Transport was unclear, so I’ll choose the practical public-transport route and local transport.");
  if (baseStatus === "destination_center") assumptions.push("No hotel/base selected; route stays centered around the main destination area.");
  // Breakfast is not part of the default trip-summary contract. Only surface
  // an assumption line if the user explicitly opted into breakfast.
  const timeLineLabel = merged.itineraryStartTime ? "Start time" : departureTime ? "Departure" : arrivalTime ? "Arrival" : "Start time";
  const timeLineValue = merged.itineraryStartTime
    ? formatTripClockTime(startTime)
    : departureTime
    ? `${formatTripClockTime(departureTime)} from ${originText || "main destination area"}`
    : arrivalTime
    ? `${formatTripClockTime(arrivalTime)} in ${rawDestination || "destination"}`
    : startTime
    ? formatTripClockTime(startTime)
    : "practical morning start (assumption accepted)";
  const transportNotes = cleanTripSummaryValue(formatTripTransportNotes(merged));
  const routeNote = cleanTripSummaryValue(formatTripRouteNote(merged));
  const anchorLine = formatAnchorPlaceForSummary(merged);

  const baseLine = cleanTripSummaryValue(formatTripBaseLine(merged));

  // Local-trip detection: same origin & destination → skip hotel/base,
  // show "Accommodation: Not needed / local trip" and "Transport: Local
  // transport only" unless the user explicitly asked for a hotel or gave
  // a different transport.
  const isLocalTrip = Boolean(
    normalizedOrigin &&
    normalizedDestination &&
    (normalizedOrigin === normalizedDestination ||
      normalizedDestination.includes(normalizedOrigin) ||
      normalizedOrigin.includes(normalizedDestination))
  );
  const accommodationNotNeeded =
    baseStatus === "local_home" ||
    /\b(?:no need|don'?t need|do not need|skip)\b.*\b(?:hotel|stay|accommodation|place to stay|base stay)\b/i.test(String(merged.specialRequests || "")) ||
    /\b(?:have|already have)\s+(?:a\s+)?(?:house|home|place)\b/i.test(String(merged.specialRequests || ""));
  const userAskedForHotel =
    !accommodationNotNeeded &&
    (Boolean(merged.baseArea) || merged.noHotelYet === true || /\b(?:hotel|stay|accommodation|where to stay)\b/i.test(String(merged.specialRequests || "")));
  const showHotelBase = !accommodationNotNeeded && (!isLocalTrip || userAskedForHotel);
  const breakfastRequested = breakfastStatus === "included" || Boolean(breakfastDetails);

  // ALWAYS use bulleted markdown format. The frontend renders `- **Field:**
  // value` consistently as a clean list; plain `Field: value` lines often
  // collapse into a single paragraph block. Unified with the bulleted
  // builder in intake.controller.js so the user never sees two different
  // summary shapes across turns.
  const summaryLines = [
    "**Trip summary:**",
    "",
    `- **Destination:** ${safeDestination}`,
    `- **Origin:** ${originText || "main destination area (assumption accepted)"}`,
    `- **Dates:** ${dates || "flexible date/month (assumption accepted)"}`,
    `- **Duration:** ${duration}`,
    `- **Travelers:** ${travelers}`,
    `- **Style:** ${safeStyle}`,
    ...(merged.lastStopRule ? [`- **Beach rule:** ${merged.lastStopRule}`] : []),
    ...(scopeNote ? [`- **Scope note:** ${scopeNote}`] : []),
    ...(preTripTravel ? [`- **Pre-trip travel:** ${preTripTravel}`] : []),
    ...(overnightBase ? [`- **Overnight:** ${overnightBase}`] : []),
    ...(itineraryStartPoint ? [`- **Itinerary start point:** ${itineraryStartPoint}`] : []),
    `- **${timeLineLabel}:** ${timeLineValue}`,
    ...(budget ? [`- **Budget:** ${budget}`] : []),
    ...(showHotelBase && baseLine ? [`- **Hotel/base:** ${baseLine}`] : []),
    ...(!showHotelBase ? [accommodationNotNeeded ? "- **Accommodation:** Not needed — local/home-based trip" : "- **Accommodation:** Not needed / local trip"] : []),
    ...(accommodationBudget ? [`- **Accommodation budget:** ${accommodationBudget}`] : []),
    ...(transportNotes
      ? [`- **Transport:** ${transportNotes}`]
      : isLocalTrip
      ? ["- **Transport:** Local transport only"]
      : acceptedAssumptions.has("transport")
      ? ["- **Transport:** practical transfers/local transport as needed"]
      : []),
    ...(routeNote ? [`- **Route note:** ${routeNote}`] : []),
    ...(breakfastRequested ? [`- **Meals:** Breakfast ${breakfastLine}`] : []),
    ...(assumptions.length ? ["", "**Assumptions:**", ...assumptions.map((item) => `- ${item}`)] : []),
    "",
    buildGenerateItineraryQuestion(`${safeDestination}|${dates}|${travelers}`),
  ];
  void anchorLine; // anchor is internal-only; never expose in the user-facing summary

  return summaryLines.join("\n");
}

function previousAssistantIsBlueprint(messages = []) {
  const lastAssistant = [...messages].reverse().find((m) => m && m.role === "assistant");
  const text = String(lastAssistant?.content || "").trim();
  if (!text) return false;

  return (
    (
      /\blet me confirm before I build the full itinerary\b/i.test(text) &&
      /\bdoes this look right\b/i.test(text)
    ) ||
    (
      /\bplan brewing\b/i.test(text) &&
      /\bshall i go ahead\b/i.test(text)
    ) ||
    (
      /\b(?:trip summary|trip summary I’ll use|trip summary I'll use|plan checkpoint|updated trip summary)\b/i.test(text) &&
      /\b(?:should I generate|ready for me to generate|want me to generate|shall I turn|generate\b[\s\S]{0,40}\bitinerary|itinerary draft)\b/i.test(text)
    ) ||
    // Match the actual phrase emitted by buildTripBlueprintReply.
    // Without this branch, after the blueprint is shown, "generate this"
    // / "yes" / "1" / "Generate the itinerary now" are NOT recognized as
    // confirmations because isAfterBlueprint is false, and the assistant
    // re-shows the same blueprint instead of generating.
    (
      /\b(?:trip summary|trip summary I’ll use|trip summary I'll use|plan checkpoint|updated trip summary)\b/i.test(text) &&
      /\b(?:should I generate this itinerary for you now|ready for me to generate|want me to generate|shall I turn|itinerary draft)\b/i.test(text)
    ) ||
    // Fix #2: also recognise the "Okay — I won't generate it yet" pause
    // message so the very next turn ("also add local foods", "make it 4
    // days") routes back through the blueprint-edit path instead of
    // starting a new trip. Without this hook the paused message looks
    // like a generic assistant reply and the blueprint-edit gate misses.
    (
      /won'?t generate the itinerary yet/i.test(text) &&
      /trip draft is kept/i.test(text)
    )
  );
}

function previousAssistantAskedExactGenerateItineraryCta(messages = []) {
  const lastAssistant = [...messages].reverse().find((m) => m && m.role === "assistant");
  const text = String(lastAssistant?.content || "").trim();
  return /(?:Should I generate (?:the full itinerary|the updated \d{1,2}-day itinerary) now\?|Ready for me to generate (?:the full itinerary|the updated \d{1,2}-day itinerary|the itinerary)\?|Want me to generate .*itinerary.*\?|Shall I turn this into .*itinerary.*\?|Ready for the itinerary draft based on this summary\?)\s*$/i.test(text);
}

function latestUserExplicitlyRequestsItineraryGeneration(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;
  return /\b(?:generate|genrate|geneate|generte|henerate|build|create|make)\b[\s\S]{0,60}\b(?:the\s+)?(?:full\s+)?itinerary\b/i.test(t) ||
    /\b(?:the\s+)?(?:full\s+)?itinerary\b[\s\S]{0,60}\b(?:generate|genrate|geneate|generte|henerate|build|create|make)\b/i.test(t);
}

// Detect "X or Y?" style 2-choice questions in the previous assistant
// message so a user "yes" doesn't get silently bound to one option.
// Conservative: only fires when the LAST sentence ends with "?" and
// contains " or " separating two short alternatives.
function previousAssistantOfferedChoice(messages = []) {
  const lastAssistant = [...messages].reverse().find((m) => m && m.role === "assistant");
  const text = String(lastAssistant?.content || "").trim();
  if (!text) return { hasChoice: false, askWhichReply: "" };
  if (previousAssistantIsBlueprint(messages)) return { hasChoice: false, askWhichReply: "" };

  const sentences = text.split(/(?<=[.?!])\s+/).map((s) => s.trim()).filter(Boolean);
  const lastSentence = sentences.length ? sentences[sentences.length - 1] : "";
  if (!lastSentence.endsWith("?")) return { hasChoice: false, askWhichReply: "" };
  if (!/\bor\b/i.test(lastSentence)) return { hasChoice: false, askWhichReply: "" };

  if (/\bdoes this look right\b/i.test(lastSentence)) {
    return { hasChoice: false, askWhichReply: "" };
  }

  const orMatch = lastSentence.match(/\b(.{5,80}?)\s+or\s+(.{3,80}?)\??$/i);
  if (!orMatch) return { hasChoice: false, askWhichReply: "" };

  const optA = String(orMatch[1] || "").replace(/^[^\p{L}\p{N}]+/u, "").trim();
  const optB = String(orMatch[2] || "").replace(/[?.!]+$/, "").trim();
  if (!optA || !optB) return { hasChoice: false, askWhichReply: "" };

  return {
    hasChoice: true,
    askWhichReply: `Which one — (1) ${optA}, or (2) ${optB}?`,
  };
}

// Detect whether the previous assistant message is a clarifying question
// during trip-form setup. Used to gate place-status / named-place /
// route branches so short user answers like "with partner, mid range"
// are merged into trip state instead of being treated as a place name.
function previousAssistantIsClarifyingQuestion(messages = []) {
  const lastAssistant = [...messages].reverse().find((m) => m && m.role === "assistant");
  const text = String(lastAssistant?.content || "").trim();
  if (!text) return false;
  const hasTripFieldList =
    /[-*]\s+\*\*(?:Destination(?:\s+or\s+area)?|Duration|Date\/month|Travelers|Budget|Origin|Start time|Transport mode|Base stay|Hotel\/base):\*\*/i.test(text) ||
    /\bI still need (?:one|a few)|\bI can build this, but I (?:still )?need/i.test(text);
  if (!/\?\s*$/.test(text) && !hasTripFieldList) return false;

  // Recognize my JS clarifier lead-ins.
  if (/\b(to get the trip card going|to lock the trip card|to narrow it down)\b/i.test(text)) {
    return true;
  }

  // Recognize common LLM clarifier phrasings used during trip setup.
  if (/\b(where exactly are we heading|how many days are you staying|what'?s the vibe|who'?s coming|when are you going|where are you starting from|are we keeping it budget|budget, mid-range, or luxury|what kind of trip do you want|what date or month|what date are you going|specific dates|how many days|how many nights|start time|transport mode|base stay|hotel\/base|is this for 1 day|is this a 1[- ]day|do you want only this place|solo trip)\b/i.test(text)) {
    return true;
  }

  // Heuristic: short assistant message ending in "?" inside an active
  // trip-planning thread (any prior user msg matched looksLikeItineraryRequest).
  if (text.length < 320) {
    const recentUsers = [...messages].slice(-12).filter((m) => m?.role === "user");
    if (recentUsers.some((m) => looksLikeItineraryRequest(String(m?.content || "")))) {
      return true;
    }
  }
  return false;
}

// True when the user is mid-form: previous assistant turn was either a
// clarifying question or the blueprint card. Used as the master gate
// for routing short trip-form answers away from place-status logic.
function isInPendingTripSetup(messages = []) {
  return previousAssistantIsClarifyingQuestion(messages) || previousAssistantIsBlueprint(messages);
}

const STRICT_ACTIVITY_LINE_RX =
  /^(\d{2}:\d{2})–(\d{2}:\d{2})\s+-\s+(.+?)\s+-\s+(.+?)\s*$/;

// User-facing rebuild notices. Empty strings = silent rebuild (the user does
// not need to see internal recovery diagnostics — they erode trust and look
// like the bot is uncertain about itself). The constants are kept so the
// prepend functions can no-op cleanly without removing call sites.
const DURATION_REBUILD_NOTICE = "";
const DETAILS_REBUILD_NOTICE = "";

// KNOWN_PLACES array deleted. Previously this was a ~150-city hardcoded list
// used by findKnownPlace for "does this text mention a known place?" checks
// throughout the codebase. The list privileged PH/SEA/E.Asia cities heavily
// and silently refused to recognize Reykjavik, Oslo, Quito, Marrakech,
// Kinshasa, and most of the world. Replaced by the structural
// extractProperNounPhrase helper below (see findKnownPlace).

function looksLikeSelectedPlaceOnlyMessage(text = "") {
  return Boolean(extractParenthesizedPlaceContext(text));
}

function looksLikeClosedStatusReport(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  return /\b(it'?s all close|its all close|they'?re all close|theyre all close|everything is close|all of them are close|all close right now)\b/i.test(t);
}

function looksLikeClosedPlaceReport(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  return /\b(.+?)\s+(?:is|are)\s+(?:permanently\s+)?closed\b/i.test(t) &&
    !/\b(is it|are they|is .+ open|check if|confirm if|tell me if|can you check)\b/i.test(t);
}

// Stopwords that look proper-noun-shaped at sentence start but are not
// place names. Kept short — the test below requires an EXACT full-text
// match against one of these, so we only add entries that are common
// full-message single-word inputs. Things like "Tokyo" or "Paris" must
// not appear here.
const PROPER_NOUN_STOPWORDS = new Set([
  "I", "Im", "I'm", "Me", "My", "We", "Us", "Our",
  "You", "Your", "They", "Them", "Their",
  "He", "She", "It", "This", "That", "These", "Those",
  "The", "A", "An",
  "Yes", "No", "Ok", "Okay", "Sure", "Maybe",
  "Can", "Could", "Would", "Should", "Do", "Does", "Did", "Will",
  "Please", "Plan", "Create", "Make", "Build", "Draft", "Generate",
  "Give", "Show", "Help", "Need", "Want",
  "Hi", "Hello", "Hey", "Thanks",
  "Mr", "Mrs", "Ms", "Dr", "Prof",
  "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday",
  "Today", "Tomorrow", "Tonight", "Yesterday",
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
]);

const DESTINATION_FILLER_DENYLIST = new Set([
  "reply", "yes", "no", "ok", "okay", "sure", "this", "that", "here", "there",
  "please", "thanks", "anything", "something", "somewhere", "anywhere", "hello", "hi",
  "recommend me a place to stay first", "provide me a place to stay", "why is it",
  "the destination should be", "add it", "food and nightlife", "generate the itinerary",
  "trip summary already", "stay first",
]);

function isDeniedDestinationFiller(value = "") {
  const key = String(value || "")
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^\p{L}\p{N}\s]/gu, " ")
    .replace(/\s+/g, " ")
    .trim();
  return !key ||
    DESTINATION_FILLER_DENYLIST.has(key) ||
    /\b(?:recommend|suggest|provide|give|show|list|find)\b.*\b(?:place\s+to\s+stay|stay|hotel|hostel|accommodation|base)\b/i.test(key) ||
    /\b(?:add\s+it|food\s+and\s+nightlife|generate\s+the\s+itinerary|trip\s+summary\s+already|why\s+is\s+it)\b/i.test(key);
}


// Scans a text string for the first capitalized proper-noun-shaped phrase
// (1-4 tokens), in any script. Region-neutral replacement for the old
// findKnownPlace list-based approach. Returns the matched phrase or "".
//
// Matches: Latin with accents ("São Paulo", "Reykjavík"), CJK ("東京"),
// Cyrillic ("Москва"), Arabic, Devanagari, Thai, Hebrew, etc. Also matches
// lowercase ASCII in a non-strict mode (so "tokyo" works when it's clearly
// the whole input — we defer that to callers that know the input is
// user-typed and probably casual).
//
// Does NOT match: English grammar fragments ("The", "I", "Yes"), personal
// titles ("Mr", "Mrs"), weekdays, months. These are in PROPER_NOUN_STOPWORDS.
//
// This is a heuristic, not a database lookup — it will produce false
// positives on single-token capitalized personal names ("Smith", "Jones").
// Callers that need stricter disambiguation should combine this with
// additional structural tests (duration words, travel verbs, etc.).
function extractProperNounPhrase(text = "") {
  const raw = String(text || "").trim();
  if (!raw) return "";

  // Regex matches a sequence of 1-4 proper-noun-shaped tokens separated by
  // spaces. Tokens start with an uppercase Latin letter OR any non-Latin
  // letter (CJK/Cyrillic/Arabic/etc.), followed by letters/marks/apostrophes/
  // periods/hyphens. Uses Unicode property escapes.
  const rx = /[\p{Lu}\p{Lo}][\p{L}\p{M}'’.-]*(?:\s+[\p{Lu}\p{Lo}][\p{L}\p{M}'’.-]*){0,3}/gu;
  const matches = raw.match(rx) || [];

  for (const candidate of matches) {
    const trimmed = candidate.trim();
    if (!trimmed) continue;
    // Reject single-token candidates that are common English grammar words
    // or titles/days/months. Multi-token candidates are assumed to be place
    // names or proper nouns worth returning (the caller decides what to do
    // with a false positive like "New York Times").
    if (PROPER_NOUN_STOPWORDS.has(trimmed)) continue;
    return trimmed;
  }

  return "";
}

function looksLikePossiblePlaceName(text = "") {
  const raw = String(text || "").trim();
  if (!raw) return false;
  if (/\b(yes|no|maybe|thanks|thank you|ok|okay|sure|hey|hello|yo)\b/i.test(raw)) return false;
  if (/\b(monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tomorrow|tonight|now)\b/i.test(raw)) return false;

  // Tech/coding/math/science denylist: reject inputs containing these as
  // possible place names. This function is a weak heuristic (any 1-5 Latin
  // word tokens will match the positive shape test below), so we need an
  // explicit list of common non-travel topics that happen to fit the shape.
  //
  // The list is NOT exhaustive and should be extended as new false positives
  // come up. Prefer specific technical terms over short common words.
  //
  // NOTE on "php": deliberately NOT included here. "php" in travel context
  // is the Philippine Peso currency code (e.g. "show me prices in php"),
  // and rejecting it here would break currency queries. The PHP programming
  // language is usually typed as "php script" / "php code" / "laravel" which
  // match other terms in this list.
  //
  // NOTE on "go": deliberately NOT included. Go (the language) collides with
  // the verb "go" which is heavily travel-relevant ("go to Tokyo", "want to go").
  if (/\b(react|firebase|javascript|typescript|node|express|css|tailwind|api|bug|error|stack trace|console|vite|programming|convert|calculate|math|assignment|homework|code|coding|python|java|html|sql|database|algorithm|function|variable|class|object|array|loop|compile|debug|deploy|server|client|frontend|backend|ruby|rust|swift|kotlin|scala|elixir|haskell|perl|laravel|django|flask|rails|spring|angular|vue|svelte|nextjs|nuxt|webpack|babel|eslint|prettier|npm|yarn|pnpm|docker|kubernetes|terraform|jenkins|github|gitlab|bitbucket|regex|regexp|json|xml|yaml|markdown|compiler|runtime|stacktrace|traceback|exception|throw|catch|async|await|promise|callback|closure|recursion|iteration|matrix|vector|tensor|linear algebra|calculus|derivative|integral|physics|chemistry|biology|equation|formula)\b/i.test(raw)) return false;

  const words = raw.split(/\s+/).filter(Boolean);
  if (!words.length || words.length > 5) return false;

  return words.every((word) => /[A-Za-z][A-Za-z'’.-]{1,}/.test(word));
}

function sanitizeLocationReplyLabel(value = "") {
  const raw = String(value || "").trim();
  if (!raw) return "";

  const firstLine = raw.split(/\r?\n/)[0].trim();
  if (!firstLine) return "";
  if (firstLine.includes("|")) return "";
  if (/^here are\b/i.test(firstLine)) return "";
  if (looksLikeCurrentLocationQuestion(firstLine)) return "";
  if (/^(locate|find|share)\s+my exact location\b/i.test(firstLine)) return "";
  if (/^do you know where i am right now\b/i.test(firstLine)) return "";

  return firstLine.replace(/[.\s]+$/, "").trim();
}

// Short user answers that obviously belong to trip-form intake
// (budget tier, traveler shape, duration, transport mode, theme,
// "no idea" / "you choose" defaults). These never go to a place
// lookup — they merge into the pending trip state instead. Caps the
// length at ~40 chars so we don't accidentally swallow a short
// place-name string like "Bo's Coffee" or "El Nido".
function looksLikeTripFormAnswerFragment(text = "") {
  const t = String(text || "").trim().toLowerCase();
  if (!t || t.length > 40) return false;

  // Budget tiers ("budget", "mid range", "mid-range", "midrange",
  // "low budget", "high-end", "premium", "luxury", "cheap", "affordable").
  if (/^(?:budget|mid[\s-]?range[d]?|low[\s-]?budget|cheap|affordable|luxury|high[\s-]?end|premium)\b\.?\s*$/i.test(t)) return true;

  // Traveler shape ("solo", "with partner", "couple", "family", "friends",
  // "group", "barkada", "just me", "alone", "by myself", "2 of us").
  if (/^(?:solo|alone|by\s+myself|on\s+my\s+own|just\s+me|with\s+(?:partner|gf|bf|girlfriend|boyfriend|wife|husband|spouse)|couple|family|friends|group|barkada|seniors?|elderly)\b\.?\s*$/i.test(t)) return true;
  if (/^\d+\s+(?:adults?|pax|people|travelers?|of\s+us)\b\.?\s*$/i.test(t)) return true;

  // Duration / numeric day answers ("2 days", "3 nights", "one day",
  // "weekend", "3", "5d4n").
  if (/^(?:\d+|one|two|three|four|five|six|seven|eight|nine|ten)\s*[- ]?\s*(?:day|days|night|nights)\b\.?\s*$/i.test(t)) return true;
  if (/^\d+d\d+n\b\.?\s*$/i.test(t)) return true;
  if (/^(?:weekend|today|tomorrow|tonight)\b\.?\s*$/i.test(t)) return true;

  // Transport mode ("ferry", "fast ferry", "bus", "van", "private car",
  // "commute", "public transport", "habal-habal", "scooter", "rented
  // motorcycle", "flight", "plane", "train").
  if (/^(?:fast\s+)?(?:ferry|boat|bus|coach|van|train|flight|plane|car|taxi|rideshare)\b\.?\s*$/i.test(t)) return true;
  if (/^(?:private\s+car|own\s+car|drive|driving|commute|commuting|public\s+transport|public\s+transit)\b\.?\s*$/i.test(t)) return true;
  if (/^(?:rented\s+)?(?:motorcycle|motorbike|scooter|moped|habal[-\s]?habal)\b\.?\s*$/i.test(t)) return true;

  // Theme / vibe words ("food", "nature", "beach", "shopping", "history",
  // "culture", "mixed", "all of it", "everything", "famous highlights",
  // "highlights", "relaxed", "adventurous").
  if (/^(?:food|history|nature|adventure(?:ous)?|culture|cultural|shopping|beach|nightlife|museum(?:s)?|cafe(?:s)?|photography|relax(?:ed|ing)?|wellness|hiking|family|romantic|temples?|diving|snorkeling|surf(?:ing)?|mixed|all\s+of\s+it|everything|famous\s+highlights|highlights)\b\.?\s*$/i.test(t)) return true;

  // "No idea" / "you choose" / "no preference" defaults.
  if (looksLikeTripUnknownAnswer(t)) return true;

  return false;
}

function looksLikeStandaloneSpecificPlaceName(text = "") {
  const raw = String(text || "").trim();
  if (!raw) return false;

  // Reject obvious trip-form answer fragments before any place-name
  // shape test runs. Without this, "mid range", "mid-range", "luxury",
  // "solo", "with partner", "fast ferry", "2 days", "no idea", and
  // similar short answers slip through because they are 1–3 token
  // strings that happen to look like a place name shape — and then get
  // sent to lookupSpecificPlaceStatus, which is what produced the
  // "I found mid range … Address: Philippines" response in the
  // production log.
  if (looksLikeTripFormAnswerFragment(raw)) return false;

  // Reject plain affirmative/negative one-liners ("please do", "go
  // ahead", "yes please", "do it", "make it so", "no thanks", "skip it"
  // …). These are confirmations, not place names, and the full
  // vocabulary is already centralised in
  // looksLikeAffirmativeFollowUp / looksLikeNegativeFollowUp. Without
  // this guard, "please do" got routed to lookupSpecificPlaceStatus
  // and returned UK/US ranger-sign matches.
  if (looksLikeAffirmativeFollowUp(raw) || looksLikeNegativeFollowUp(raw)) return false;

  if (
    looksLikeSavedPreferenceQuestion(raw) ||
    looksLikeUsedProfileDetailsQuestion(raw) ||
    looksLikePlacesQuery(raw) ||
    looksLikeExplicitRouteQuery(raw) ||
    looksLikeItineraryRequest(raw) ||
    looksLikeLocationDiscussionMessage(raw) ||
    looksLikeCurrentLocationQuestion(raw) ||
    looksLikeCurrentTimeQuestion(raw) ||
    looksLikeShortContextualFollowUp(raw) ||
    looksLikePlaceListSizeFollowUp(raw) ||
    looksLikePlacesRefinementFollowUp(raw) ||
    looksLikeAreaOnlyPlacesRefinement(raw)
  ) {
    return false;
  }

  const cleaned = raw
    .replace(/^(?:how about|what about|maybe|try|check|look up)\s+/i, "")
    .replace(/[?.!]+$/, "")
    .trim();

  if (!cleaned || !looksLikePossiblePlaceName(cleaned) || looksLikeCategoryTerm(cleaned)) {
    return false;
  }

  if (/^(?:in|near|around|at|outside|inside|within|from)\b/i.test(cleaned)) {
    return false;
  }

  if (/\b(city|province|country|district|barangay|village|town|poblacion)\b/i.test(cleaned)) {
    return false;
  }

  if (looksLikeBrandOrBranchName(cleaned)) {
    return true;
  }

  return (
    /\b(cafe|coffee|mercado|market|mall|museum|temple|basilica|church|cathedral|resort|hotel|inn|hostel|terminal|station|airport|restaurant|grill|bakery|bar|house|center|centre)\b/i.test(cleaned) ||
    cleaned.split(/\s+/).filter(Boolean).length >= 2
  );
}

function extractAssistantSpecificPlaceContextFromReply(content = "") {
  const raw = String(content || "").trim();
  if (!raw) return { placeName: "", address: "" };

  const firstLine = raw.split(/\r?\n/)[0].trim();
  if (!firstLine) return { placeName: "", address: "" };

  const addressMatch = raw.match(/(?:^|\n)\s*Address\s*:\s*([^\n]+)/i);
  const address = String(addressMatch?.[1] || "").trim();

  const structuredNames = extractDisplayedPlaceNamesFromReplyText(raw);
  if (structuredNames.length === 1) {
    return {
      placeName: String(structuredNames[0] || "").trim(),
      address,
    };
  }

  if (
    firstLine.includes("|") ||
    /^here are\b/i.test(firstLine) ||
    /^i couldn['’]?t\b/i.test(firstLine) ||
    /^tell me\b/i.test(firstLine) ||
    /^it(?:['’]s| is)\s+currently\b/i.test(firstLine)
  ) {
    return { placeName: "", address: "" };
  }

  const match = firstLine.match(
    /^([\p{L}\p{N}][\p{L}\p{N}&'’./() -]{1,100}?)\s+(?:is\s+listed\s+as|appears\s+to\s+be|typically\s+operates|typically\s+opens|typically\s+closes|operates|opens|closes|is\s+open|is\s+closed|is\b)/iu
  );
  const placeName = String(match?.[1] || "").trim();

  if (
    !placeName ||
    /^(?:it|this|that|the place|there)\b/i.test(placeName) ||
    looksLikeCategoryTerm(placeName)
  ) {
    return { placeName: "", address: "" };
  }

  return { placeName, address };
}

function extractLatestAssistantSpecificPlaceContext(messages = [], startUserIndex = 0) {
  let userIndex = -1;
  let latest = { placeName: "", address: "" };

  for (const message of Array.isArray(messages) ? messages : []) {
    if (message?.role === "user") {
      userIndex += 1;
      continue;
    }

    if (message?.role !== "assistant") continue;
    if (userIndex < startUserIndex) continue;

    const parsed = extractAssistantSpecificPlaceContextFromReply(message?.content || "");
    if (parsed.placeName) {
      latest = parsed;
    }
  }

  return latest;
}

function looksTravel(text = "") {
  const t = String(text || "").trim();
  if (!t) return true;

  if (looksLikePlacesQuery(t)) return true;
  if (looksLikeStrictNearbyPlaceSearch(t)) return true;
  if (looksLikeGenericLivePlacesSearch(t)) return true;
  if (looksLikeTravelCapabilityFollowUp(t)) return true;
  if (looksLikeSelectedPlaceOnlyMessage(t)) return true;
  if (looksLikeNamedPlaceLookupQuery(t)) return true;
  if (looksLikePossiblePlaceName(t)) return true;
  if (looksLikeStandaloneAddress(t)) return true;
  if (looksLikeCurrentLocationQuestion(t)) return true;
  if (looksLikeCurrentTimeQuestion(t)) return true;
  if (/\b(access|use|allow)\s+my\s+location\b/i.test(t)) return true;

  // Correction / clarification prefixes — these are continuations of the
  // previous travel turn, not standalone non-travel messages. The caller
  // should already have travel context loaded. Region-neutral.
  if (/^(i said|i mean|i meant|no,?\s|not |actually,?\s|to clarify|let me clarify|i'm saying|im saying)/i.test(t)) {
    return true;
  }

  // Structural place-name fallback: a short message that is just 1–3
  // capitalized proper-noun words in any script (Latin with accents, CJK,
  // Cyrillic, Arabic, etc.) is almost certainly a place name being mentioned
  // without other travel keywords. Region-neutral, no hardcoded city list.
  // Uses Unicode property escapes so "São Paulo", "東京", "Москва" all match.
  const trimmedOriginal = String(text || "").trim();
  const isShortProperNounPhrase =
    /^[\p{Lu}\p{Lo}][\p{L}\p{M}'’.-]*(?:\s+[\p{Lu}\p{Lo}][\p{L}\p{M}'’.-]*){0,2}$/u.test(trimmedOriginal) &&
    !/^(yes|no|ok|okay|hi|hello|hey|thanks|thank you|sure|please|stop|cancel|continue)$/i.test(trimmedOriginal);

  if (isShortProperNounPhrase) {
    return true;
  }

  if (/\b(conflict|date conflict|why.*conflict|how come.*conflict|save.*itinerary|replace it|change dates|save as draft)\b/i.test(t)) return true;
  if (/\b(visit|see|do|go to|explore)\b.*\bnear\b.*\bfor\s+\d+\s*(hour|hours|hr|hrs)\b/i.test(t)) return true;
  if (/\b(half[- ]day|full[- ]day)\b.*\b(itinerary|plan|trip|schedule)\b/i.test(t)) return true;
  if (/\bmake me\b.*\b(itinerary|plan|trip|schedule)\b/i.test(t)) return true;
  if (/\b(?:i want to go to|i wanna go to|i plan to go to|im going to|i'm going to|travel to|head to|heading to)\b.+\b(how do i get there|how can i get there|how to get there|best way to get there|cheapest way to get there|fastest way to get there)\b/i.test(t)) return true;

  // Currency codes and currency-conversion phrasing are in-scope for travel
  // (trip cost, budget conversion, "total in USD"). These are travel-safe
  // follow-ups and must NEVER trigger the non-travel refusal.
  if (/\b(usd|php|eur|gbp|jpy|sgd|thb|myr|idr|hkd|aud|cad|nzd|krw|cny|rmb|inr|vnd|twd|chf)\b/i.test(t)) {
    return true;
  }
  if (/\b(in dollars|in pesos|in euros|in yen|in baht|in ringgit|in rupiah|in won|in rupees|in pounds|in francs|convert to|exchange to)\b/i.test(t)) {
    return true;
  }
  // Budget / total / breakdown follow-ups for a trip cost estimate.
  if (/\b(total|totals|grand total|sum|subtotal|how much (?:is|does|will|would)|how expensive|price tag|ballpark)\b/i.test(t)) {
    return true;
  }
  if (/\b(break\s*down|breakdown|per day|per person|daily spend|split (?:the )?budget|category|categories|category[- ]wise|by category)\b/i.test(t)) {
    return true;
  }

  if (
    /\b(travel|trip|itinerary|destination|visa|visa requirements|passport|immigration|airport|flight|hotel|hotels|hostel|hostels|accommodation|accommodations|accomodation|accomodations|lodging|stay|place to stay|room|rooms|guesthouse|guesthouses|inn|inns|resort|resorts|beach|beaches|tour|tours|route|routes|map|maps|train|trains|bus|buses|subway|metro|taxi|taxis|grab|ferry|ferries|food|restaurant|restaurants|cafe|cafes|coffee|coffee shop|coffee shops|budget|pack|packing|weather|things to do|attraction|attractions|where to go|commute|transport|transportation|transit|transfer|transfers|shuttle|shuttles|van|vans|jeepney|jeepneys|tricycle|tricycles|customs|culture|etiquette|manners|tipping|currency|exchange rate|sim card|pocket wifi|luggage|safety|day plan|best time|where to stay|surf|surfing|diving|island|islands|terminal|terminals|port|ports|open now|currently open|current hours|hours today|near me|nearby|where am i|where am i right now|what is my current location|what's my current location|my current location|my exact location|share my exact location|how to get to|how to go to|how to reach|how do i get to|how can i get to|cheapest way|fastest way|best way|travel preferences|saved preferences|travel style|budget style|interests|personal travel notes|profile|step by step|high rating|high ratings|highest rated|top rated|best rated|good reviews|well reviewed|well-reviewed|must try|must-try|authentic|affordable|budget friendly|budget-friendly|cheap|cheaper|quiet|cozy|cosy|family friendly|family-friendly|rent a car|car rental|rental car|worth visiting|safe to|safe in|in june|in july|in august|in december)\b/i.test(
      t
    )
  ) {
    return true;
  }

  // Bare city/country names are already handled region-neutrally by the
  // Unicode proper-noun check above (lines ~273-280), which matches
  // "São Paulo", "東京", "Москва", "Reykjavik", "Lyon", etc. without any
  // hardcoded list. Deleted the SEA-only alternation that used to live
  // here — it privileged ~70 PH/SEA/E.Asia cities while silently refusing
  // every other destination on Earth as non-travel.

  // "X to Y" — require a travel verb nearby OR at least one side is a known place.
  // Exclude common non-travel false positives: "how to", "want to", "need to", "learn to", etc.
  if (/\b(how|want|need|learn|try|going|trying|have|used|able|ought)\s+to\b/i.test(t)) {
    // Skip — this is almost certainly not a route query.
  } else if (/\b(get|travel|fly|drive|go|commute|ride|sail|take a bus|take a ferry|take a train)\s+from\b.+\bto\b/i.test(t)) {
    return true;
  } else if (/\bfrom\s+([A-Z][A-Za-z\s]{1,30})\s+to\s+([A-Z][A-Za-z\s]{1,30})\b/.test(t)) {
    // Capitalized on both sides — likely place names.
    return true;
  }

  if (/\b(by ferry|by boat|by bus|by train|by plane|by flight|by car)\b/i.test(t)) {
    return true;
  }

  if (
    /\b(how about|what about)\s+([A-Za-z][A-Za-z\s]{1,40})\s+to\s+([A-Za-z][A-Za-z\s]{1,40})\b/i.test(
      t
    )
  ) {
    return true;
  }

  if (/\b(\d+)\s*[- ]?\s*(day|days|night|nights|week|weeks)\b/i.test(t)) return true;
  if (/\b(weekend plan|3\s*day|day\s*plan|plan\s*for|best time to go)\b/i.test(t)) return true;

  // Travel preparation: what to bring/pack/need when going somewhere
  if (/\b(what\s+(?:to|should\s+i)\s+(?:bring|pack|prepare|need)|what\s+(?:things|items|stuff)\s+(?:are\s+needed|do\s+i\s+need|should\s+i\s+(?:bring|pack))|what\s+(?:should|do)\s+i\s+bring)\b/i.test(t)) return true;
  if (/\b(stops?\s+recommendation|recommend\s+stops?|must[- ]?(?:try|visit|see|eat|do))\b/i.test(t)) return true;

  // "X to Y" where both sides look like capitalized place-like words (even without "from").
  // Previously this also required findKnownPlace(t) as a belt-and-suspenders
  // check against non-travel "X to Y" phrases — but the anchored regex is
  // already very specific ("SomethingCapitalized to SomethingCapitalized" as
  // the ENTIRE input, nothing else), and the earlier how|want|need|learn|try
  // guard at the top of this function filters out common English false
  // positives like "want to go" or "need to buy". The extra list-based
  // check was redundant and silently rejected bare "Reykjavik to Oslo" type
  // queries.
  if (/^[\p{Lu}\p{Lo}][\p{L}\p{N}\s]{1,30}\s+to\s+[\p{Lu}\p{Lo}][\p{L}\p{N}\s]{1,30}$/iu.test(t)) return true;

  return false;
}

function looksLikeAccommodationRecommendation(text = "") {
  const t = String(text || "").trim();
  if (!t) return false;

  const hasRecommendVerb =
    /\b(recommend|recommendation|recommendations|recomendation|recomendations|suggest|suggestion|list|show|find|give me|compare|rank)\b/i.test(t);
  const hasAccommodationType =
    /\b(accommodation|accommodations|accomodation|accomodations|hotel|hotels|hostel|hostels|place to stay|places to stay|lodging|guesthouse|guesthouses|inn|inns|resort|resorts|where to stay|room|rooms)\b/i.test(t);
  const asksBudgetStay =
    /\b(?:cozy|cosy|cheap|cheapest|budget|affordable|low[-\s]?cost)\b[\s\S]{0,50}\b(?:stay|stays|hotel|hotels|hostel|hostels|room|rooms|place\s+to\s+stay|places\s+to\s+stay|accommodation|lodging)\b/i.test(t) ||
    /\b(?:stay|stays|hotel|hotels|hostel|hostels|room|rooms|place\s+to\s+stay|places\s+to\s+stay|accommodation|lodging)\b[\s\S]{0,50}\b(?:cozy|cosy|cheap|cheapest|budget|affordable|low[-\s]?cost)\b/i.test(t);
  const asksPlaceWithNightlyCap =
    /\b(?:how about\s+)?(?:a\s+)?place\b[\s\S]{0,40}\b(?:under|below|less\s+than|max(?:imum)?|up\s+to)\s*(?:₱|php|p)?\s*\d+(?:[,.]\d+)?\s*(?:k|thousand)?\b/i.test(t) ||
    /\b(?:under|below|less\s+than|max(?:imum)?|up\s+to)\s*(?:₱|php|p)?\s*\d+(?:[,.]\d+)?\s*(?:k|thousand)?\b[\s\S]{0,40}\b(?:place|room|stay)\b/i.test(t);
  const hasItineraryWord =
    /\b(itinerary|day[- ]by[- ]day|travel plan|trip plan|schedule|day plan)\b/i.test(t);
  const hasBuildVerb =
    /\b(build|create|make|draft|generate|plan)\b/i.test(t) &&
    /\b(itinerary|plan|schedule|trip plan)\b/i.test(t);

  return ((hasRecommendVerb && hasAccommodationType) || (asksBudgetStay && hasAccommodationType) || asksPlaceWithNightlyCap) && !hasItineraryWord && !hasBuildVerb;
}

function looksLikeComparisonAdviceQuery(text = "") {
  const t = String(text || "").trim();
  if (!t) return false;

  // "should I ... X or Y" — classic advice/disjunction pattern.
  const isShouldIWithDisjunction =
    /\bshould\s+i\b/i.test(t) && /\bor\b/i.test(t);

  // "is it better to X or Y", "which is better X or Y", "which should I pick"
  const isBetterComparison =
    /\b(is it better|which is better|which one is better|which should i|better to|worth it or)\b/i.test(t) &&
    /\bor\b/i.test(t);

  // "X vs Y" / "X versus Y"
  const isVersus = /\b(vs\.?|versus)\b/i.test(t);

  // "pros and cons of X", "advantages of X over Y", "trade-offs"
  const isProsCons =
    /\b(pros and cons|advantages? of .* (?:over|vs|versus)|trade[- ]?offs?|pick between)\b/i.test(t);

  // "is X worth it" — evaluative yes/no on a single thing, also NOT a places list.
  const isWorthItQuestion = /\bis\s+(?:it|this|that|the)\b.*\bworth\b/i.test(t);

  return isShouldIWithDisjunction || isBetterComparison || isVersus || isProsCons || isWorthItQuestion;
}

function looksLikeItineraryRequest(text = "") {
  const t = String(text || "").trim();
  if (!t) return false;

  // Guard: explicit negations like "not asking for an itinerary",
  // "no itinerary", "don't want an itinerary", "stop the itinerary",
  // "i was just asking" — the user is rejecting itinerary mode, not requesting it.
  if (
    /\b(not asking (for )?(an? )?itinerary|no itinerary|don'?t want (an? )?itinerary|do not want (an? )?itinerary|stop (the )?itinerary|cancel (the )?itinerary|skip (the )?itinerary|without (an? )?itinerary|just (asking|wanted to ask|wondering)|i was (just )?(asking|wondering))\b/i.test(t)
  ) {
    return false;
  }

  // Guard: accommodation/hotel recommendation requests are NOT itinerary requests
  if (
    /\b(recommend|suggest|list|show|find|give me)\b/i.test(t) &&
    /\b(accommodation|accommodations|hotel|hotels|hostel|hostels|place to stay|places to stay|lodging|guesthouse|inn|resort|where to stay)\b/i.test(t) &&
    !/\b(itinerary|day[- ]by[- ]day|travel plan|trip plan|schedule|day plan)\b/i.test(t)
  ) {
    return false;
  }

  // Guard: budget / cost breakdown requests are not itinerary-creation requests
  if (
    /\b(budget|cost|price|expense|expenses|total|breakdown|estimate|estimated|how much)\b/i.test(t) &&
    /\b(break it down|breakdown|total estimated budget|estimated total budget|total budget|total cost|whole trip|all in)\b/i.test(t)
  ) {
    return false;
  }

  if (/^(is it|is the|is a|are the|should i|do i need|can i use|worth it|how much is|how much does|what is the cost|does the)\b/i.test(t)) {
    return /(itinerary|day[- ]by[- ]day|travel plan|trip plan|schedule|weekend plan|day plan|day trip|one-day trip|1-day trip|2d1n|3d2n|4d3n|half[- ]day|full[- ]day)/i.test(t);
  }

  // Yes/no question framing anywhere in the message — "is that enough",
  // "is it worth it", "can i afford", "will it be enough" — the user is
  // asking for an evaluation, not asking us to build an itinerary.
  // Only treat as itinerary if they also explicitly use itinerary words.
  if (/\b(is (that|it|this|5000|\d+) enough|is .* enough|enough\?|will (that|it|this) (be )?enough|can i afford|will it cover|is it worth|worth it\?|is .* worth|too (little|much|expensive|cheap))\b/i.test(t)) {
    if (!/\b(itinerary|day[- ]by[- ]day|travel plan|trip plan|day plan|day trip|2d1n|3d2n|4d3n|build|create|make|plan)\s+(an?|me|my|the)?\s*(itinerary|trip|plan|schedule)?\b/i.test(t)) {
      return false;
    }
  }

  // Core itinerary keywords
  if (/(itinerary|day[- ]by[- ]day|travel plan|trip plan|schedule|weekend plan|day plan|day trip|one-day trip|1-day trip|\b\d+\s*[- ]?\s*(day|days|night|nights)\b|2d1n|3d2n|4d3n|half[- ]day|full[- ]day|starting from\b)/i.test(t)) {
    return true;
  }

  // "plan my tokyo trip" / "create me an itinerary" / "build a 3 day trip"
  if (/\b(plan|create|make|build|draft|generate)\b.*\b(my|me|a|an)\b.*\b(trip|itinerary|travel plan|schedule|tour)\b/i.test(t)) {
    return true;
  }

  // "3 day cebu trip" / "cebu 4 days trip" / "tokyo trip for 3 days"
  if (/\b\d+\s*[- ]?\s*(?:day|days|night|nights)\b/i.test(t) && /\b(trip|tour)\b/i.test(t)) {
    return true;
  }

  // Anchor-place / theme prompts that are casual but actionable.
  // Examples that should be treated as itinerary intent (so we ask 1-3
  // clarifying questions instead of letting the LLM invent a 3-day plan):
  //   "I want to go to Cebu, go shopping at SM Seaside"
  //   "I want to shop at SM Seaside"
  //   "religious spots in Cebu"
  //   "food trip in IT Park"
  if (
    /\b(shop(?:ping)?\s+at|eat\s+at|dine\s+at|food\s+trip\s+(?:at|in)|food\s+tour\s+(?:at|in)|food\s+crawl\s+(?:at|in)|visit\s+(?:the\s+)?[A-Z])\b/i.test(t)
  ) {
    return true;
  }
  if (
    /\b(?:i\s+(?:want|wanna|would like|need|plan)\s+to\s+)?(?:visit|see|explore|tour)\s+(?:malls?|shopping|shops?|restaurants?|cafes?|food spots?|museums?|churches?|temples?|beaches?|parks?|attractions?|highlights?)\s+(?:in|at|around|near)\s+[\p{L}]/iu.test(t)
  ) {
    return true;
  }
  if (
    /\b(religious|church(?:es)?|temple(?:s)?|shrine(?:s)?|pilgrimage|mall(?:s)?|shopping|food)\s+(?:spot|spots|sites|places|stops|trip|tour|crawl)\s+(?:in|at|around|near)\b/i.test(t)
  ) {
    return true;
  }
  // "go to <City> [, <action>]" with no other itinerary words — still treat
  // as itinerary intent so we route through the intake clarifier instead of
  // free-form LLM. Without this, casual users get a generic 3-day city tour.
  if (
    /^\s*(?:i\s+(?:want|wanna|would like|need|plan)\s+to\s+go\s+to|i'?m\s+going\s+to|going\s+to)\s+[\p{L}]/iu.test(t)
  ) {
    return true;
  }

  return false;
}

function arr(value) {
  return Array.isArray(value)
    ? value.map((item) => String(item || "").trim()).filter(Boolean)
    : [];
}

function getProfileFields(profileDoc = {}) {
  const travelProfile = profileDoc?.travelProfile || {};

  return {
    displayName: String(profileDoc?.displayName || "").trim(),
    travelPreferences: arr(travelProfile.travelPreferences || profileDoc?.travelPreferences),
    interests: arr(travelProfile.interests || profileDoc?.interests),
    travelStyle: String(travelProfile.travelStyle || profileDoc?.travelStyle || "").trim(),
    budgetStyle: String(travelProfile.budgetStyle || profileDoc?.budgetStyle || "").trim(),
    personalTravelNotes: String(
      travelProfile.personalTravelNotes || profileDoc?.personalTravelNotes || ""
    ).trim(),
    aiProfileContext: String(profileDoc?.aiProfileContext || travelProfile?.summary || "").trim(),
  };
}

function looksLikeSavedPreferenceQuestion(text = "") {
  const t = String(text || "").trim().toLowerCase();
  if (!t) return false;

  const profileKeywords = /\b(travel preferences|preferences|interests|travel style|budget style|personal travel notes|profile|travel profile|my style|my budget|my interests)\b/;

  // Direct "what is my X" patterns
  if (
    /\bwhat(?:'s| is| are)?\s+my\b/.test(t) &&
    profileKeywords.test(t)
  ) return true;

  // "show/tell me/summarize my X"
  if (
    (/\bshow\b.*\b(my|saved)\b/.test(t) ||
     /\btell me\b.*\b(my|saved)\b/.test(t) ||
     /\bsummarize\b.*\b(my|saved)\b/.test(t)) &&
    profileKeywords.test(t)
  ) return true;

  // "what do you know about my travel ..."
  if (/\bwhat\s+do\s+you\s+know\s+(?:about\s+)?my\b/.test(t) && /\b(travel|style|preferences|budget|profile|interests)\b/.test(t)) return true;

  // "do you have my travel preferences"
  if (/\b(?:do you have|have you saved|did you save|do you remember)\b/.test(t) && /\b(travel|preferences|profile|style|budget|interests)\b/.test(t)) return true;

  // "what saved profile details" (without "use/used" — that goes to UsedProfileDetails)
  if (/\bwhat\b.*\bsaved\b.*\b(profile|details|preferences)\b/.test(t) && !/\b(use|used|apply|applied)\b/.test(t) && !/\b(itinerary|trip|plan)\b/.test(t)) return true;

  // "my travel preferences" as a standalone query
  if (/^(?:my\s+)?(?:saved\s+)?(?:travel\s+)?(?:preferences|profile|interests|style|budget style)\s*\??$/.test(t)) return true;

  return false;
}

function looksLikeUsedProfileDetailsQuestion(text = "") {
  const t = String(text || "").trim().toLowerCase();
  if (!t) return false;

  const refersToTripContext = /\b(itinerary|trip|plan|this|that|the)\b/.test(t);

  // Original patterns
  const asksWhatWasUsed =
    /\bwhat\b.*\b(saved|profile)\b.*\b(detail|details|preference|preferences|interest|interests|travel style|budget style|note|notes)\b.*\b(use|used)\b/.test(t) ||
    /\bwhich\b.*\b(saved|profile)\b.*\b(detail|details|preference|preferences|interest|interests|travel style|budget style|note|notes)\b.*\b(use|used)\b/.test(t) ||
    /\bwhat\b.*\b(use|used)\b.*\b(saved|profile)\b/.test(t) ||
    /\bwhich\b.*\b(use|used)\b.*\b(saved|profile)\b/.test(t);

  if (asksWhatWasUsed && refersToTripContext) return true;

  // "what saved profile details did you use" (without needing trip word)
  if (/\bwhat\s+saved\s+profile\s+details?\b/.test(t) && /\b(use|used|apply|applied)\b/.test(t)) return true;

  // "which preferences did you use for this/the itinerary"
  if (/\bwhich\s+(?:travel\s+)?(?:preferences?|profile|details?)\b/.test(t) && /\b(use|used|apply|applied)\b/.test(t) && refersToTripContext) return true;

  // "did you use my profile/preferences for this"
  if (/\b(?:did you|have you)\s+(?:use|used|apply|applied)\s+(?:my|the|saved)\b/.test(t) && /\b(profile|preferences?|details?|interests?|style)\b/.test(t)) return true;

  return false;
}

function buildSavedPreferenceReply(profileDoc) {
  const profile = getProfileFields(profileDoc);

  const lines = [
    profile.travelPreferences.length
      ? `Travel preferences: ${profile.travelPreferences.join(", ")}`
      : null,
    profile.interests.length
      ? `Interests: ${profile.interests.join(", ")}`
      : null,
    profile.travelStyle
      ? `Travel style: ${profile.travelStyle}`
      : null,
    profile.budgetStyle
      ? `Budget style: ${profile.budgetStyle}`
      : null,
    profile.personalTravelNotes
      ? `Personal travel notes: ${profile.personalTravelNotes}`
      : null,
    profile.aiProfileContext
      ? `Profile summary: ${profile.aiProfileContext}`
      : null,
  ].filter(Boolean);

  if (!lines.length) {
    const rawTravelProfile =
      profileDoc?.travelProfile && typeof profileDoc.travelProfile === "object"
        ? JSON.stringify(profileDoc.travelProfile)
        : "";

    const rawAiProfile = String(profileDoc?.aiProfileContext || "").trim();

    if (rawTravelProfile || rawAiProfile) {
      return `I found saved travel profile data, but it is not in the expected display fields yet.\n\n${
        rawAiProfile ? `Profile summary: ${rawAiProfile}` : `Raw travel profile: ${rawTravelProfile}`
      }`;
    }

    return "I don’t see any saved travel preferences yet. Add them in Settings and I’ll use them in your travel answers.";
  }

  return `Here are your saved travel preferences:\n\n${lines.join("\n")}`;
}

function buildUsedProfileDetailsReply(profileDoc) {
  const profile = getProfileFields(profileDoc);

  const lines = [
    profile.travelPreferences.length
      ? `Travel preferences: ${profile.travelPreferences.join(", ")}`
      : null,
    profile.interests.length
      ? `Interests: ${profile.interests.join(", ")}`
      : null,
    profile.travelStyle
      ? `Travel style: ${profile.travelStyle}`
      : null,
    profile.budgetStyle
      ? `Budget style: ${profile.budgetStyle}`
      : null,
    profile.personalTravelNotes
      ? `Personal travel notes: ${profile.personalTravelNotes}`
      : null,
    profile.aiProfileContext
      ? `Profile summary: ${profile.aiProfileContext}`
      : null,
  ].filter(Boolean);

  if (!lines.length) {
    return "I didn’t find saved traveler profile details to apply to this itinerary. If you add them in Settings, I’ll use them as planning defaults.";
  }

  return `For this itinerary, I used these saved profile details as planning defaults unless your latest request overrode them:\n\n${lines.join("\n")}`;
}

function buildItineraryProfilePlanningContext(profileDoc) {
  const profile = getProfileFields(profileDoc);

  const lines = [
    profile.travelStyle ? `Preferred travel style: ${profile.travelStyle}` : null,
    profile.budgetStyle ? `Preferred budget style: ${profile.budgetStyle}` : null,
    profile.interests.length ? `Saved interests: ${profile.interests.join(", ")}` : null,
    profile.travelPreferences.length
      ? `Saved travel preferences: ${profile.travelPreferences.join(", ")}`
      : null,
    profile.personalTravelNotes
      ? `Saved personal travel notes: ${profile.personalTravelNotes}`
      : null,
    profile.aiProfileContext ? `Saved profile summary: ${profile.aiProfileContext}` : null,
    "When building an itinerary, apply these saved profile details as planning defaults unless the user's latest message explicitly overrides them.",
    "Use them to shape pace, attraction mix, food stops, timing style, budget framing, and recommendation tone.",
  ].filter(Boolean);

  if (!lines.length) return "";

  return `SAVED TRAVELER ITINERARY DEFAULTS\n${lines.join("\n")}`;
}

function normalizeIntentText(text = "") {
  return String(text || "")
    .replace(/[\u2018\u2019\u201A\u201B]/g, "'")
    .replace(/[\u201C\u201D\u201E\u201F]/g, '"')
    .replace(/[\u2013\u2014]/g, "-")
    .replace(/\bmroe\b/gi, "more")
    .replace(/\breccomend\b/gi, "recommend")
    .replace(/\brecomend\b/gi, "recommend")
    .replace(/\brecommened\b/gi, "recommend")
    .replace(/\bacc?omodati?on\b/gi, "accommodation")
    .replace(/\baccomodations?\b/gi, "accommodation")
    .replace(/\bcoffe\b/gi, "coffee")
    .replace(/\bcofee\b/gi, "coffee")
    .replace(/\bcoffe shops?\b/gi, "coffee shops")
    .replace(/\brestarant\b/gi, "restaurant")
    .replace(/\brestaraunt\b/gi, "restaurant")
    .replace(/\bresturant\b/gi, "restaurant")
    .replace(/\bitineray\b/gi, "itinerary")
    .replace(/\biternary\b/gi, "itinerary")
    .replace(/\bitenary\b/gi, "itinerary")
    .replace(/\bitinarary\b/gi, "itinerary")
    .replace(/\bprefernces?\b/gi, "preferences")
    .replace(/\bprefrences?\b/gi, "preferences")
    .replace(/\bpreferances?\b/gi, "preferences")
    .replace(/\bbudgest\b/gi, "budget")
    .replace(/\bbaget\b/gi, "budget")
    .replace(/\bdestiantion\b/gi, "destination")
    .replace(/\bdestianation\b/gi, "destination")
    .replace(/\bhotles?\b/gi, "hotel")
    .replace(/\bhotells?\b/gi, "hotel")
    .replace(/\bflght\b/gi, "flight")
    .replace(/\btravle\b/gi, "travel")
    .replace(/\btravell\b/gi, "travel")
    .replace(/\bschedlue\b/gi, "schedule")
    .replace(/\bschedual\b/gi, "schedule")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function messageHasExplicitPlaceType(text = "") {
  return /\b(coffee shop|coffee shops|coffee|cafe|cafes|restaurant|restaurants|bakery|bakeries|bar|bars|convenience store|convenience stores|pharmacy|pharmacies|hotel|hotels|hostel|hostels|food|foods|fast food|chinese|italian|mexican|indian|thai|french|japanese|vietnamese|mediterranean|american|fusion|soul food)\b/i.test(
    normalizeIntentText(text)
  );
}

function looksLikeLocationDiscussionMessage(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  return (
    /\bwhy\s+not\s+ask\s+my\s+location\b/.test(t) ||
    /\bwhy\s+are\s+you\s+in\s+[a-z]/.test(t) ||
    /\bthen\s+why\s+recommend\b.*\b(other country|wrong country|singapore)\b/.test(t) ||
    /\byou\s+know\s+my\s+exact\s+location\s+right\b/.test(t) ||
    /\b(?:do you know|you know)\s+where\s+i\s+am(?:\s+right(?:\s+now)?)?\b/.test(t) ||
    /\b(do you|can you|are you able to|are you allowed to)\s+(?:know|see|use|access)\s+my\s+(?:exact\s+)?location\b/.test(t) ||
    /\b(didn'?t|did not)\s+even\s+ask\b.*\b(allow location|location access|my location|exact location)\b/.test(t) ||
    (
      /\b(why|how come)\b/.test(t) &&
      /\b(my location|exact location|location access|allow location|location permission|wrong country|other country|singapore)\b/.test(t)
    )
  );
}

function looksLikeTravelCapabilityFollowUp(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  if (looksLikeLocationDiscussionMessage(t)) {
    return true;
  }

  const asksProviderCapability =
    /\b(why|how come|cant|can't|cannot|couldnt|couldn't|unable|won't|wont)\b/.test(t) &&
    /\b(map search|map provider|place api|places api|place details|provider data|live data|place data|open status|current hours|hours today|information)\b/.test(
      t
    );

  const asksPlaceFlowDebug =
    /\b(why|how come|what triggered|what triggers|what made|why did you|why you)\b/.test(t) &&
    /\b(change|changed|switch|switched|jump|jumped|drift|drifted|move|moved|went|go to|ended up|picked)\b/.test(t) &&
    (
      /\b(location|area|city|country|place|branch|result|results|search)\b/.test(t) ||
      Boolean(findKnownPlace(text))
    );

  const asksSpecificPlaceCorrection =
    (
      /\b(you are wrong|you're wrong|the response is wrong|that response is wrong|wrong answer|wrong response)\b/.test(t) ||
      /\b(it should|you should|use the exact time|exact time|actual hours|correct hours|real hours)\b/.test(t)
    ) &&
    !/\b(code|coding|programming|javascript|typescript|node|react|firebase|api|bug|error|deploy)\b/.test(t);

  return asksProviderCapability || asksPlaceFlowDebug || asksSpecificPlaceCorrection;
}

function looksLikeBookingTransactionRequest(text = "") {

  const t = normalizeIntentText(text);
  if (!t) return false;

  return /\b(book(?:ing)?\s+(?:it|this|that|me|my|for me)|reserve\s+(?:it|this|that|me|my|for me)|make\s+(?:a\s+)?booking|make\s+(?:a\s+)?reservation|pay\b|payment\b|checkout\b|purchase\b|buy\b|credit\s*card\b|confirm\s+(?:my|the)\s+(?:booking|reservation)|booking\s+links?)\b/.test(t);
}

function looksLikeAffirmativeFollowUp(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  // Exact-match list of confirmation phrases real users type, including
  // PH/Tagalog short forms and explicit "looks right / that is correct"
  // confirmations that follow a blueprint card. Anchored ^...$ so it only
  // fires on standalone confirmations, never on confirmations embedded in
  // longer instructions.
  return /^(yes|yeah|yep|yup|sure|ok|okay|okay na|okey|oks|sige|sige na|ge|gee|please do|please proceed|proceed|go ahead|go|do it|do that|make that|make it|make it so|lets go|let's go|continue|continue please|sounds good|that works|that one|that will do|that'll do|thats fine|that's fine|alright|all right|fine|fine by me|good|good with me|deal|approved|confirmed|correct|that is correct|that's correct|thats correct|that is right|that's right|thats right|looks right|looks good|sounds right|exactly|exactly right|exactly that|right|generate|generate it|build|build it|yes build it|yes generate it|yes please|yes provide me|yes use it|yes allow it|yes use my location|yes access my location|yes allow location access)$/i.test(t);
}

// Permissive confirmation matcher used ONLY by the trip-blueprint gate.
// Recognizes natural variations of "yes, generate this for me" that the
// strict looksLikeAffirmativeFollowUp regex above misses because it is
// anchored ^...$. Without this, "Generate the itinerary now",
// "yes please build the itinerary", "go ahead and make it", or "1"
// (when the assistant offered a numbered choice) all loop back to the
// blueprint card instead of triggering generation.
//
// Kept SEPARATE from looksLikeAffirmativeFollowUp on purpose — many
// other code paths use the strict matcher as a guard, and loosening it
// globally would over-fire on places lookups, route follow-ups, etc.
// This helper should only be called at the blueprint generation gate.
function looksLikeBlueprintGenerateRequest(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  if (latestUserExplicitlyRequestsItineraryGeneration(t)) return true;
  // Strict short forms first (covers "yes", "go", "1", "generate", etc.).
  if (looksLikeAffirmativeFollowUp(t)) return true;
  if (/^[1-9]$/.test(t)) return true;
  if (/\b(?:yes|generate|genrate|geneate|generte|henerate|go\s+ahead|do\s+it|please|now|proceed|sure|ok(?:ay)?|yep)\b/i.test(t)) return true;

  // Natural sentence variations. Require an action verb + (optional)
  // object that refers to the trip/itinerary/plan, OR an unambiguous
  // "now"/"please"/"for me" hint, so "generate ideas" / "build a script"
  // outside the trip context cannot accidentally match. Length-capped
  // at ~80 chars so a long instruction like "generate it but change the
  // base to Alona" doesn't get treated as plain confirmation.
  if (t.length > 80) return false;

  return /\b(?:yes|sure|ok(?:ay)?|please|go(?:\s+ahead)?|let'?s|now)\b[\s\S]{0,30}\b(?:generate|genrate|geneate|generte|henerate|build|make|create|produce|proceed|do)\b/i.test(t)
    || /\b(?:generate|genrate|geneate|generte|henerate|build|make|create|produce|proceed)\b[\s\S]{0,40}\b(?:it|this|that|the\s+itinerary|the\s+trip|the\s+plan|now|for\s+me|please)\b/i.test(t)
    || /^(?:please\s+)?(?:generate|genrate|geneate|generte|henerate|build|make|create|produce|proceed)\b/i.test(t);
}

function previousAssistantRequestedGenerationRetry(messages = []) {
  const lastAssistant = [...messages].reverse().find((m) => m && m.role === "assistant");
  const text = String(lastAssistant?.content || "").trim();
  if (!text) return false;
  return (
    /\bplease\s+send\s+["']?(?:generate|yes)["']?\b/i.test(text) ||
    /\bsend\s+["']?(?:generate|yes)["']?\s+(?:and|to)\b/i.test(text) ||
    /\bretry\s+generation\b/i.test(text) ||
    /\brebuild(?:ing)?\s+(?:it|the itinerary)\s+from\s+(?:your\s+)?saved\s+trip\s+details\b/i.test(text) ||
    /\bcouldn'?t\s+safely\s+finish\s+the\s+itinerary\b/i.test(text) ||
    /\bcouldn'?t\s+safely\s+return\s+the\s+generated\s+itinerary\b/i.test(text) ||
    /\bdid\s+not\s+match\s+your\s+selected\s+destination\b/i.test(text)
  );
}

function looksLikeGenerationRetryConfirmation(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;
  if (looksLikeBlueprintGenerateRequest(t)) return true;
  return /^(?:yes|yeah|yep|yup|ok|okay|sure|go(?:\s+ahead)?|proceed|continue|retry|try\s+again|generate|genrate|geneate|generte|henerate|generate\s+it|genrate\s+it|geneate\s+it|generte\s+it|henerate\s+it|just\s+(?:generate|genrate|geneate|generte|henerate)(?:\s+the\s+itinerary)?|build\s+it|make\s+it|do\s+it)(?:\s+please)?$/i.test(t);
}

function stripLeadingBlueprintConfirmation(text = "") {
  let s = String(text || "").trim();
  if (!s) return "";

  const confirmationPart =
    "(?:yes|yeah|yep|yup|sure|ok(?:ay)?|sige|go ahead|please|proceed|generate|build|make|create|produce|do it)";
  const generatePart =
    "(?:generate|build|make|create|produce|proceed)(?:\\s+(?:it|this|that|the\\s+itinerary|the\\s+trip|the\\s+plan))?";

  for (let i = 0; i < 4; i += 1) {
    const before = s;
    s = s
      .replace(new RegExp(`^\\s*${confirmationPart}\\b[\\s,.;:!-]*`, "i"), "")
      .replace(new RegExp(`^\\s*${generatePart}\\b[\\s,.;:!-]*`, "i"), "")
      .replace(/^\s*(?:and|but|also|then)\b[\s,.;:!-]*/i, "")
      .trim();
    if (s === before) break;
  }

  return s.replace(/\s+/g, " ").replace(/[.?!]+$/g, "").trim();
}

function extractBlueprintInstructionAfterConfirmation(text = "") {
  const remainder = stripLeadingBlueprintConfirmation(text);
  if (!remainder) return "";

  const appendixOnly =
    /\b(?:cost|costs|budget|price|estimated|estimate|expense|hotel|hostel|accommodation|place to stay|places to stay|transport notes?|fare breakdown)\b/i.test(remainder) &&
    !/\b(?:garden|gardens|church|churches|cathedral|basilica|shrine|religious|nightlife|food|must[- ]?try|camp\s+sawi|avoid|remove|skip|not too many|last stop|beach|lagoon|museum|mall|market|park|waterfall|temple|include [a-z ]{0,30}(?:garden|church|food|nightlife|beach|lagoon|museum|mall|market|park))\b/i.test(remainder);
  if (appendixOnly) return "";

  const looksLikeTripConstraint =
    /\b(?:make sure|include|add|avoid|remove|skip|keep|not too many|don't include|do not include|last stop|every day|every night|nightlife|must[- ]?try|camp\s+sawi|gardens?|church(?:es)?|cathedral|basilica|shrine|religious|food|beach|lagoon|museum|mall|market|park|waterfall|temple)\b/i.test(remainder);

  return looksLikeTripConstraint
    ? remainder.slice(0, 180).trim()
    : "";
}

function userConfirmedBlueprintWithExtraTripInstruction(text = "") {
  return looksLikeBlueprintGenerateRequest(text) && Boolean(extractBlueprintInstructionAfterConfirmation(text));
}

function extractStandaloneBlueprintInstruction(text = "") {
  const raw = String(text || "").trim();
  if (!raw) return "";
  if (looksLikeBlueprintCorrectionOrReset(raw)) return "";
  if (looksLikeBlueprintGenerateRequest(raw)) return extractBlueprintInstructionAfterConfirmation(raw);
  const looksLikeTripConstraint =
    /\b(?:before\s+you\s+generate|before\s+generating|make sure|include|add|avoid|remove|skip|keep|not too many|don't include|do not include|last stop|every day|every night|nightlife|must[- ]?try|camp\s+sawi|gardens?|church(?:es)?|cathedral|basilica|shrine|religious|food|beach|lagoon|museum|mall|market|park|waterfall|temple)\b/i.test(raw);
  return looksLikeTripConstraint ? raw.slice(0, 180).trim() : "";
}

function looksLikeBlueprintCorrectionOrReset(text = "") {
  const raw = String(text || "");
  if (!raw.trim()) return false;
  return /\b(?:clear everything|start over|start fresh|forget (?:the )?(?:previous|old|earlier) conversation|forget (?:the )?(?:previous|old|earlier) trip|let me try again|messed up|wrong|incorrect|not listening|fix it|regenerate the summary|i already said|i said|i didn['’]?t say|i did not say|i meant|no,?\s+i meant|replace|instead)\b/i.test(raw) ||
    /\b(?:destination|origin|travelers?|style|theme|budget|duration|date|start(?:\s*time)?|transport|hotel\/base|base)\s+(?:is|are|should be|=)\b/i.test(raw);
}

function userGavePendingBlueprintInstruction(text = "") {
  return Boolean(extractStandaloneBlueprintInstruction(text));
}

function normalizeBlueprintSpecialRequest(text = "") {
  let raw = String(text || "")
    .replace(/\s+(?:please\s+)?(?:add|include|put)\s+(?:it|them|this|that|those|these)?\s*(?:to|on|in|into)?\s*(?:the\s+)?(?:itinerary|trip|plan|summary)?\s*$/i, "")
    .replace(/\s+(?:on|in|to)\s+(?:the\s+)?(?:itinerary|trip|plan|summary)\s*$/i, "")
    .replace(/\s+(?:to\s+(?:visit|see|try|stop\s+by)|during\s+the\s+trip|on\s+the\s+trip)\s*$/i, "")
    .replace(/^(?:please\s+)?(?:can\s+you\s+|could\s+you\s+)?(?:also\s+)?(?:visit|include|add|put)\s+/i, "")
    .replace(/\s+/g, " ")
    .trim();
  if (/\b(?:i\s+said|i\s+didn['’]?t\s+say|i\s+did\s+not\s+say|no,?\s+i\s+meant|replace\s+.+\s+with|remove\s+.+|not\s+.+\s+(?:but|instead))\b/i.test(raw)) return "";
  if (/^(?:yes|yep|yeah|ok|okay|sure|generate|genrate|generate it|genrate it)$/i.test(raw)) return "";
  if (/\b(?:provide|show|display|give|send|see|view|review)\b[\s\S]{0,50}\b(?:trip\s+summary|summary|trip\s+card|details)\b/i.test(raw)) return "";
  if (/\b(?:recommend|suggest|find|show|list|where)\b[\s\S]{0,50}\b(?:base|hotel|hostel|accommodation|accomodation|accomadation|place\s+to\s+stay|places\s+to\s+stay|stay|lodging|room)\b/i.test(raw)) return "";
  if (/\b(?:show|provide|give|send)\b[\s\S]{0,40}\b(?:itinerary|trip\s+summary|summary)\b/i.test(raw)) return "";
  if (/\b(?:cozy|cosy|cheap|cheapest|budget)\b[\s\S]{0,40}\b(?:stay|hotel|hostel|room|place\s+to\s+stay|accommodation|lodging)\b/i.test(raw)) return "";
  if (/\b(?:motorbike|motorcycle|scooter|habal[-\s]?habal)\s+rental\b/i.test(raw)) return "";
  if (/\b(?:under|below|less\s+than|max(?:imum)?|up\s+to)\s*(?:₱|php|p)?\s*\d+(?:[,.]\d+)?\s*(?:k|thousand)?\s*(?:per\s*night|pernight|\/night|nightly|a\s+night)?\b/i.test(raw) &&
    /\b(?:hotel|hostel|accommodation|accomodation|accomadation|place\s+to\s+stay|places\s+to\s+stay|stay|lodging|room|base)\b/i.test(raw)) {
    return "";
  }
  if (/\b(?:strawberry\s+(?:garden|farm|picking)|la\s+trinidad)\b/i.test(raw)) {
    return "La Trinidad Strawberry Farm";
  }
  if (/\b(?:breakfast|brunch|morning meal)\b/i.test(raw)) {
    return "";
  }
  if (/\bgardens?\b.*\bchurch(?:es)?\b|\bchurch(?:es)?\b.*\bgardens?\b/i.test(raw)) {
    return "gardens and churches";
  }
  const FOOD_RX = /\b(?:food|foods|local\s+food|famous\s+food|must[-\s]?try|eat|dining)\b/i;
  const CHURCH_RX = /\bchurch(?:es)?|cathedral|basilica|parish|shrine\b/i;
  const NIGHTLIFE_RX = /\b(?:nightlife|bars?|drinks?|evening)\b/i;
  if (FOOD_RX.test(raw) && CHURCH_RX.test(raw) && NIGHTLIFE_RX.test(raw)) {
    return "famous local food, churches, nightlife";
  }
  if (FOOD_RX.test(raw) && CHURCH_RX.test(raw)) {
    return "famous local food, churches";
  }
  if (FOOD_RX.test(raw) && NIGHTLIFE_RX.test(raw)) {
    return "famous local food, nightlife";
  }
  if (CHURCH_RX.test(raw) && NIGHTLIFE_RX.test(raw)) {
    return "churches, nightlife";
  }
  if (FOOD_RX.test(raw)) {
    return "famous local food";
  }
  if (NIGHTLIFE_RX.test(raw)) {
    return "nightlife";
  }
  if (/\bchurch(?:es)?|cathedral|basilica|parish|shrine\b/i.test(raw)) {
    return "churches";
  }
  if (/\bfood\b.*\bhistory\b|\bhistory\b.*\bfood\b/i.test(raw)) {
    return "food and history";
  }
  let cleaned = String(text || "")
    .replace(/^\s*(?:and|but|also|then)\b[\s,.;:!-]*/i, "")
    .replace(/^\s*(?:make sure(?: to)?|please|can you|could you)\b[\s,.;:!-]*/i, "")
    .replace(/^\s*(?:to\s+)?/i, "")
    .replace(/^\s*(?:include|add|visit|see|go to|try)\s+/i, "")
    .replace(/^\s*(?:i\s+want\s+to\s+visit|i\s+want|we\s+like|we\s+want|i\s+like)\s+/i, "")
    .replace(/\bcan\s+you\s+add\s+that\b/ig, "")
    .replace(/\s+/g, " ")
    .replace(/[.?!]+$/g, "")
    .trim();
  if (!cleaned) return "";
  // Reject sentence-shape phrases (>9 words with planning verbs) — those
  // are wholesale user messages dumped into specialRequests by mistake.
  const wordCount = cleaned.split(/\s+/).filter(Boolean).length;
  if (wordCount > 9 && /\b(plan me|i want|i'?d like|i would|can you|please plan|please make)\b/i.test(cleaned)) {
    return "";
  }
  // Normalize common Bohol/Cebu phrasings.
  cleaned = cleaned
    .replace(/^churches and famous foods? in bohol$/i, "churches and famous Bohol food stops")
    .replace(/^famous food stops and churches$/i, "Famous Bohol food stops and churches")
    .replace(/\bin bohol\b/i, "Bohol")
    .replace(/^famous foods?$/i, "famous Bohol food stops")
    // Preserve thousands separator: PHP 3,000 must stay "3,000" not "3, 000".
    .replace(/(\d),\s+(\d{3})\b/g, "$1,$2")
    .replace(/(?:₱|php|PHP)\s*(\d{1,3})\s*,\s*(\d{3})/g, (m, a, b) => {
      const prefix = /^php/i.test(m) ? "PHP " : "₱";
      return `${prefix}${a},${b}`;
    })
    .replace(/\b(Famous Bohol food stops|famous Bohol food stops|food stops)\s+stops\b/gi, "$1")
    .replace(/^Churches$/i, "churches")
    .replace(/\bUnder\s+₱\s*(\d{1,3}(?:,\d{3})*)\s+per\s+night\b/i, (_, n) => `Under ₱${n}/night`)
    .replace(/\bUnder\s+PHP\s*(\d{1,3}(?:,\d{3})*)\s+per\s+night\b/i, (_, n) => `Under PHP ${n}/night`);
  // Title-case the first letter for readability while preserving inner casing.
  if (cleaned && /^[a-z]/.test(cleaned)) {
    cleaned = cleaned.charAt(0).toUpperCase() + cleaned.slice(1);
  }
  if (/^(?:avoid|remove|skip|keep|not too many|don't include|do not include)\b/i.test(cleaned)) {
    return cleaned;
  }
  return cleaned;
}

function extractBlueprintBreakfastNote(text = "") {
  const raw = String(text || "").trim();
  if (!raw) return "";
  if (/\b(?:no breakfast|skip breakfast|without breakfast|do not include breakfast|don't include breakfast)\b/i.test(raw)) {
    return "not included unless requested";
  }
  if (!/\b(?:breakfast|brunch|morning meal)\b/i.test(raw)) return "";
  if (
    /\b(?:arriv(?:e|ed|es|ing|al)|when i arrive|when we arrive|after arrival|upon arrival|once i arrive|once we arrive)\b/i.test(raw)
  ) {
    return "arrival breakfast/brunch included";
  }
  return "included";
}

function getLastAssistantBlueprintText(messages = []) {
  const lastAssistant = [...messages].reverse().find((m) => m && m.role === "assistant");
  const text = String(lastAssistant?.content || "").trim();
  return previousAssistantIsBlueprint(messages) ? text : "";
}

function extractBlueprintFieldsForRevision(messages = []) {
  const text = getLastAssistantBlueprintText(messages);
  if (!text) return {};

  const fields = {};
  const lines = text.split("\n").map((line) => String(line || "").trim()).filter(Boolean);

  for (const line of lines) {
    const cleaned = line
      .replace(/^\s*[-*]\s*/, "")
      .replace(/\*\*/g, "")
      .trim();
    const match = cleaned.match(/^([A-Za-z/ ]{3,30}):\s*(.+)$/);
    if (!match) continue;
    const label = String(match[1] || "").trim().toLowerCase();
    const value = String(match[2] || "").trim();
    if (!value) continue;
    fields[label] = value;
  }

  return fields;
}

function appendBlueprintSpecialRequest(existing = "", request = "") {
  const cleanRequestPhrase = (value = "") =>
    String(value || "")
      .replace(/\b(?:i|we)\s+(?:want|wanna|would like)\s+to\s+/gi, "")
      .replace(/\b(?:try|eat|taste)\s+(?=\w)/gi, "")
      .replace(/\b(?:visit|see|go to)\s+(?=(?:historical|historic|heritage|cultural)\b)/gi, "")
      .replace(/\b(?:yes\s+we\s+are|we\s+are|we're|i\s+am|i'm)\s+(?:flying|travelling|traveling)\s+(?:to|for)\s+\S+\b/gi, "")
      .replace(/\b(?:add|include|put)\s+(?:it|them|this|that)?\s*(?:on|in|to)?\s*(?:the\s+)?(?:itinerary|trip|plan)?\b/gi, "")
      .replace(/\b(?:on|in)\s+(?:the\s+)?last\s+day(?:\s+trip)?\b/gi, "on Day 3")
      .replace(/\b(?:on|in)\s+(?:the\s+)?final\s+day(?:\s+trip)?\b/gi, "on Day 3")
      .replace(/\s+/g, " ")
      .trim();

  const normalizeRequestPart = (value = "") => {
    const cleaned = cleanRequestPhrase(value);

    if (
      !cleaned ||
      looksLikeAccommodationRecommendation(cleaned) ||
      /\b(?:recommend|suggest|find|show|list|where)\b[\s\S]{0,80}\b(?:hotel|hostel|accommodation|place\s+to\s+stay|places\s+to\s+stay|stay|lodging|room|guesthouse|inn|resort|villa|cabin|rental)\b/i.test(cleaned)
    ) {
      return "";
    }

    const normalized = normalizeBlueprintSpecialRequest(cleaned);
    if (!normalized) return "";

    return String(normalized || "")
      .replace(/\bHistorical\b/gi, "historical places")
      .replace(/\bHistoric\b/gi, "historical places")
      .replace(/\bHistory\b/gi, "historical places")
      .replace(/\bCultural\b/gi, "cultural places")
      .replace(/\bKawasan\s*,?\s*Falls\b/gi, "Kawasan Falls")
      .replace(/\s+/g, " ")
      .trim();
  };

  const splitRequestParts = (value = "") =>
    String(value || "")
      .replace(/(\d),\s*(\d{3})/g, "$1 $2")
      .replace(/\s+\band\b\s+(?=(?:try|eat|taste|visit|see|go to|historical|historic|heritage|cultural|nightlife|surfing|shopping|food|local|famous)\b)/gi, ", ")
      .split(/\s*,\s*/)
      .map((part) => part.replace(/(\d)\s+(\d{3})/g, "$1,$2").trim())
      .filter(Boolean)
      .map((part) => normalizeRequestPart(part))
      .filter(Boolean);

  const parts = [];
  const seen = new Set();

  for (const part of [...splitRequestParts(existing), ...splitRequestParts(request)]) {
    const cleaned = String(part || "")
      .replace(/\b(?:i want to|we want to|want to|visit|try|eat)\b/gi, " ")
      .replace(/\b(?:^|\s)(?:in|on|to|for|the|a|an|trip|itinerary|plan)(?:\s|$)\b/gi, " ")
      .replace(/\s+/g, " ")
      .trim();

    if (!cleaned) continue;

    const key = cleaned.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
    if (!key || seen.has(key)) continue;

    const alreadyCovered = [...seen].some((existingKey) =>
      existingKey === key ||
      existingKey.includes(key) ||
      key.includes(existingKey)
    );

    if (alreadyCovered) continue;

    seen.add(key);
    parts.push(cleaned);
  }

  return parts.join(", ");
}

function buildUpdatedBlueprintAfterConfirmationInstruction(messages = [], latestUser = "") {
  const fields = extractBlueprintFieldsForRevision(messages);
  const instruction = extractStandaloneBlueprintInstruction(latestUser);
  const breakfastNote = extractBlueprintBreakfastNote(instruction);
  const specialRequest = breakfastNote ? "" : cleanTripSummaryValue(normalizeBlueprintSpecialRequest(instruction));
  if (!Object.keys(fields).length || (!specialRequest && !breakfastNote)) return "";

  const valueFor = (...labels) => {
    for (const label of labels) {
      const value = fields[String(label || "").toLowerCase()];
      if (value) return value;
    }
    return "";
  };

  let destination = cleanTripSummaryValue(valueFor("destination")) || "your destination";
  if (/^santa\s+fe,\s*philippines$/i.test(destination) && /\bbantayan\b/i.test(JSON.stringify(messages || []))) {
    destination = "Santa Fe, Bantayan Island, Philippines";
  }
  const base = cleanTripSummaryValue(valueFor("hotel/base", "base", "recommended base"));
  const accommodation = cleanTripSummaryValue(valueFor("accommodation"));
  const priorStyle = cleanTripSummaryValue(valueFor("style")) || "General travel";
  const priorSpecialRequests = cleanTripSummaryValue(valueFor("special requests", "special request"));
  const rawSpecialRequests = specialRequest
    ? appendBlueprintSpecialRequest(priorSpecialRequests, specialRequest)
    : priorSpecialRequests;

  // Re-derive the style label from the combined signals so a new
  // special request like "churches and famous foods" actually shows up
  // in the Style field instead of being silently dropped. We keep the
  // family/couple/etc. prefix from the prior style when possible.
  const styleValue = (() => {
    const travelers = String(valueFor("travelers") || "").toLowerCase();
    const allText = `${priorStyle} ${rawSpecialRequests} ${valueFor("destination")} ${valueFor("travelers")} ${specialRequest}`.toLowerCase();
    const couplelike = /\bcouple|partner|honeymoon|spouse|girlfriend|boyfriend\b/.test(travelers);
    const budgetish = /\bbudget|cheap|affordable|tipid\b/.test(`${allText} ${valueFor("budget")}`.toLowerCase());
    const romantic = /\bromantic|romance|date\s+trip|anniversary|honeymoon\b/.test(allText);
    if (romantic && couplelike) {
      return budgetish ? "romantic budget couple trip" : "romantic couple trip";
    }
    const explicitlyReligious = /\b(religious\s+(?:trip|focus|tour|places)|pilgrim|faith\s+trip|religious-only|all\s+religious)\b/.test(allText);
    const mentionsChurches = /\b(church(?:es)?|cathedral|basilica|shrine)\b/.test(allText);
    const signals = [];
    if (explicitlyReligious) signals.push("religious places focus");
    else if (mentionsChurches) signals.push("churches");
    if (/\b(food|kainan|cuisine|restaurants?|eat|dishes?|silog|street food|famous foods?)\b/.test(allText)) signals.push("food");
    if (/\b(history|historic|heritage|museum|fort|ruins?|colonial)\b/.test(allText) && !mentionsChurches) signals.push("history");
    if (/\b(nature|hike|hiking|trek|trail|waterfall|river|mountain|jungle|forest|park|landmark|viewpoint)\b/.test(allText)) signals.push("nature");
    if (/\b(beach|island|snorkel|dive|diving|lagoon|swim|seaside)\b/.test(allText)) signals.push("beach");
    if (/\b(shopping|mall|malls|market|night market|souvenir|pasalubong)\b/.test(allText)) signals.push("shopping");
    if (/\b(nightlife|bar|bars|club|clubs|rooftop|drinks)\b/.test(allText)) signals.push("nightlife");
    const familyish = /\bfamily|parents|kids|children|seniors?\b/.test(travelers);
    const friendsish = /\bfriends|barkada\b/.test(travelers);
    const soloish = /\bsolo|alone|just me\b/.test(travelers);
    const prefix = familyish
      ? "Family-friendly"
      : couplelike
      ? "Couple-friendly"
      : friendsish
      ? "Friends-trip"
      : soloish
      ? "Solo-traveler"
      : "";
    const unique = Array.from(new Set(signals));
    if (!unique.length) return prefix ? `${prefix} highlights` : (priorStyle || "General travel");
    if (prefix) {
      if (unique.length === 1) return `${prefix} ${unique[0]}`;
      return `${prefix} mixed trip — ${unique.join(", ")}`;
    }
    if (unique.length === 1) return unique[0].charAt(0).toUpperCase() + unique[0].slice(1);
    return `Mixed — ${unique.join(", ")}`;
  })();
  const specialRequests = rawSpecialRequests
    .split(/\s*,\s*/)
    .map((p) => p.trim())
    .filter(Boolean)
    .filter((p) => !isUnsafeTripSummaryValue(p))
    .filter((p, index, arr) => {
      const key = p.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
      return key && arr.findIndex((item) => item.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim() === key) === index;
    })
    .join(", ");
  const mealsValue = breakfastNote ? `Breakfast ${breakfastNote}` : "";
  const displayRequest = breakfastNote || specialRequest.replace(/^(?:include|add)\s+/i, "").trim() || specialRequest;
  const orderedLines = [
    ["Destination", destination],
    ["Origin", cleanTripSummaryValue(valueFor("origin"))],
    ["Dates", cleanTripSummaryValue(valueFor("dates", "date"))],
    ["Duration", cleanTripSummaryValue(valueFor("duration"))],
    ["Travelers", cleanTripSummaryValue(valueFor("travelers"))],
    ["Style", styleValue],
    ["Start", cleanTripSummaryValue(valueFor("start", "start time", "departure"))],
    ["Budget", cleanTripSummaryValue(valueFor("budget"))],
    ["Accommodation", accommodation],
    ["Hotel/base", accommodation ? "" : base],
    ["Transport", cleanTripSummaryValue(valueFor("transport"))],
    ["Meals", mealsValue],
    ["Special requests", specialRequests],
  ].filter(([, value]) => String(value || "").trim());

  const cleanRequestLabel = (() => {
    let raw = String(displayRequest || "")
      .replace(/\s+(?:please\s+)?(?:add|include|put)\s+(?:it|them|this|that|those|these)?\s*(?:to|on|in|into)?\s*(?:the\s+)?(?:itinerary|trip|plan|summary)?\s*$/i, "")
      .replace(/\s+(?:on|in|to)\s+(?:the\s+)?(?:itinerary|trip|plan|summary)\s*$/i, "")
      .replace(/\s+(?:to\s+(?:visit|see|try|stop\s+by)|during\s+the\s+trip|on\s+the\s+trip)\s*$/i, "")
      .replace(/^(?:please\s+)?(?:can\s+you\s+|could\s+you\s+)?(?:also\s+)?(?:visit|include|add|put)\s+/i, "")
      .trim();
    if (!raw) return displayRequest;

    const FOOD_RX = /\b(?:food|foods|local\s+food|famous\s+food|must[-\s]?try|eat|dining)\b/i;
    const CHURCH_RX = /\bchurch(?:es)?|cathedral|basilica|parish|shrine\b/i;
    const NIGHTLIFE_RX = /\b(?:nightlife|bars?|drinks?|evening)\b/i;
    const requestTags = [];
    if (FOOD_RX.test(raw)) requestTags.push("famous local food");
    if (CHURCH_RX.test(raw)) requestTags.push(requestTags.length ? "churches" : "church stops");
    if (NIGHTLIFE_RX.test(raw)) requestTags.push("nightlife");
    if (requestTags.length) {
      return [...new Set(requestTags)].join(", ");
    }

    // Generic normalization only — destination-specific rewrites would
    // hallucinate the wrong region into other trips (the "famous food stops
    // in bantayan" → "famous Bohol food stops" bug came from a hardcoded
    // Bohol injector here).
    const destKey = String(destination || "").toLowerCase();
    const isBoholTrip = /\bbohol\b|\bpanglao\b|\btagbilaran\b|\balona\b|\bloboc\b|\banda\b/.test(destKey);

    if (isBoholTrip) {
      raw = raw
        .replace(/\bin\s+bohol\b/i, "Bohol")
        .replace(/\bfamous foods?\b/i, "famous Bohol food stops")
        .replace(/\bchurches\s+and\s+famous\s+Bohol\s+food\s+stops\s+Bohol\b/i, "churches and famous Bohol food stops")
        .replace(/\bfamous\s+Bohol\s+food\s+stops\s+stops\b/i, "famous Bohol food stops")
        .replace(/\bfamous\s+Bohol\s+food\s+stops\s+and\s+churches\b/i, "famous Bohol food stops and churches");
    } else {
      // Non-Bohol trip: keep the user's region word intact.
      raw = raw
        .replace(/\bfamous foods?\b/i, "famous food stops");
    }

    raw = raw
      .replace(/(\d),\s+(\d{3})\b/g, "$1,$2")
      .replace(/\s{2,}/g, " ")
      .trim();
    return raw || displayRequest;
  })();

  const lines = [
    `I’ll fold in ${cleanRequestLabel} and use this updated trip summary:`,
    "",
    "**Updated trip summary:**",
    ...orderedLines.map(([label, value]) => `- **${label}:** ${value}`),
  ];

  if (base && !accommodation) {
    // Destination-aware recommended-base reason. Mirrors
    // intake.controller's buildRecommendedBaseReason so the second-time
    // blueprint render doesn't revert to a bland generic line.
    const baseKey = String(base || "").toLowerCase();
    const destKey = String(destination || "").toLowerCase();
    const travelers = String(valueFor("travelers") || "").toLowerCase();
    const audience = /family|parents|kids|children/.test(travelers)
      ? "your family"
      : /couple|partner|honeymoon|spouse|girlfriend|boyfriend/.test(travelers)
      ? "you both"
      : /friends|barkada/.test(travelers)
      ? "your group"
      : "you";
    const mustVisit = String(specialRequests || "")
      .split(/\s*,\s*/)
      .find((p) => /\b(?:landmark|museum|temple|church|cathedral|shrine|river|cave|falls?|forest|sanctuary|lagoon|beach|island|view(?:point)?|park|tower|monument)\b/i.test(p));
    const mustVisitClause = mustVisit ? `, while still making ${mustVisit} doable as a day trip` : "";
    let baseReason = `This keeps ${audience} close to food, transfers, and the main route${mustVisitClause}.`;
    if (/panglao|alona|bohol/.test(baseKey) || /panglao|bohol/.test(destKey)) {
      baseReason = `This keeps ${audience} close to beach areas, restaurants, and tour pickup points${mustVisitClause}.`;
    } else if (/tagbilaran/.test(baseKey)) {
      baseReason = `Tagbilaran City is the most practical launch point with the easiest ferry access and onward transfers to Panglao, Loboc, and the Chocolate Hills route${mustVisitClause}.`;
    } else if (/el nido|palawan|coron/.test(baseKey)) {
      baseReason = `This keeps ${audience} near the port and town for easy island-hopping access${mustVisitClause}.`;
    } else if (/intramuros|ermita|malate|makati|bgc|manila/.test(baseKey)) {
      baseReason = `This keeps ${audience} near the heritage and food stops with easy transit access${mustVisitClause}.`;
    } else if (/session road|burnham|baguio/.test(baseKey)) {
      baseReason = `This keeps ${audience} walkable to Session Road, food spots, and the main viewpoints${mustVisitClause}.`;
    }
    const safeBaseReason = cleanTripSummaryValue(baseReason);
    if (safeBaseReason) {
      lines.push(
        "",
        `**Recommended base:** ${base}`,
        "",
        safeBaseReason
      );
    }
  }

  lines.push("", buildGenerateItineraryQuestion(`${destination}|${styleValue}|${specialRequests}`));
  return lines.join("\n");
}

function looksLikeNegativeFollowUp(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  // Anchored to the START of the message (not exact-match as before), so
  // "no thank you", "no thanks that's fine", "not right now", "skip that",
  // "skip that please", "stop showing me those", "pass on that", and
  // "don't want to" all match. The old regex required the entire
  // normalized input to BE one of the exact tokens, which missed all of
  // the above and silently routed them into other classifiers.
  //
  // Start-of-message anchoring is deliberate: "please stop" doesn't match
  // (the classifier shouldn't fire on mid-sentence occurrences), but
  // "stop please" does. A user's intent is almost always carried by the
  // first word of a short response.
  return /^(no\b|nope\b|nah\b|not\s|skip\b|dont\b|don'?t\b|pass\b|stop\b)/i.test(t);
}

function looksLikeRouteCostFollowUp(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  return /\b(what is the total|what's the total|so what is the total|total cost|total fare|how much all in|how much in total|rough total|estimated total)\b/.test(t);
}

function looksLikeItineraryCostFollowUp(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  return /\b(what is the total price|what's the total price|estimate the total budget|estimated total budget|what is the total budget|what's the total budget|how much is the total cost|how much is the whole trip|budget estimate for this itinerary|cost estimate for this itinerary|price estimate for this itinerary|estimate the trip cost|estimate the itinerary cost|how much all in for this itinerary|how much in total for this itinerary|total trip cost|total itinerary cost|estimated total budget for|total budget for that|total budget for the|how much .+ trip|budget .+ broken into|budget .+ breakdown|cost .+ breakdown|expense .+ breakdown|budget for that .+ trip|budget for the .+ trip|how much will .+ trip cost|how much .+ itinerary cost|how much for the .+ trip|how much for that .+ trip)\b/.test(
    t
  );
}

function extractAreaRefinementHint(text = "") {
  const raw = String(text || "").trim();
  if (!raw) return "";

  const outsideMatch = raw.match(/^(?:how about\s+|what about\s+)?outside\s+(.+?)$/i);
  if (outsideMatch) {
    return String(outsideMatch[1] || "")
      .trim()
      .replace(/\s+(only|please)$/i, "")
      .replace(/[?.!]+$/, "");
  }

  const m = raw.match(/\(([^()]{2,80})\)/);
  if (!m) return "";

  if (!/\b(area|inside|actually in|within|near|around|in|outside)\b/i.test(raw)) {
    return "";
  }

  return String(m[1] || "").trim();
}

function looksLikePlacesCapacityQuestion(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  return /^(how many can you add|how many more can you add|how many more|how many can you show|how many can you list|how many more can you show|how many additional options|how many additional places)$/.test(t);
}

function looksLikeBrandOrBranchName(text = "") {
  const raw = String(text || "").trim();
  if (!raw) return false;
  // "Brand - Location" pattern (e.g., "Dunkin' - Insular Square", "Starbucks - Ayala Center")
  if (/^[\p{L}][\p{L}\p{N}&''.\s]{1,40}\s*[-\u2013\u2014]\s*[\p{L}][\p{L}\p{N}&''.\s]{1,60}$/u.test(raw)) return true;
  // Full input starts with a known brand name (bare or with "the").
  // Uses the shared BRAND_ALTERNATION_SRC so all brand checks stay in sync.
  if (new RegExp(`^(?:the\\s+)?(?:${BRAND_ALTERNATION_SRC})\\b`, "i").test(raw)) return true;
  return false;
}


function isBareAreaCandidate(text = "") {
  const raw = String(text || "").trim();
  const t = normalizeIntentText(text);
  if (!raw || !t) return false;

  if (looksLikeAffirmativeFollowUp(raw) || looksLikeNegativeFollowUp(raw) || looksLikePlacesCapacityQuestion(raw)) {
    return false;
  }

  // Brand/branch names should not be treated as area candidates
  if (looksLikeBrandOrBranchName(raw)) {
    return false;
  }

  if (/\d/.test(t) && !/\b(?:bgc|it park|terminal 3|terminal 2|terminal 1)\b/i.test(raw)) {
    return false;
  }

  if (
    looksLikeShortContextualFollowUp(t) ||
    looksLikePlaceListSizeFollowUp(t) ||
    /\b(closest|nearest|open now|currently open|open late|late|inside the area only|inside this area only|from here|cheapest|lowest price|best value|how do i get there|how can i get there|how to get there|route there|directions there|how many can you add|how many more)\b/i.test(t)
  ) {
    return false;
  }

  if (/\b(show|give|list|recommend|find|suggest|route|directions|add)\b/i.test(t)) {
    return false;
  }

  if (!extractAreaHint(raw)) {
    return false;
  }

  const wordCount = t.split(/\s+/).filter(Boolean).length;
  return wordCount >= 1 && wordCount <= 6;
}

function looksLikeAreaOnlyPlacesRefinement(text = "") {
  const raw = String(text || "").trim();
  const t = normalizeIntentText(text);
  if (!raw || !t) return false;

  if (
    looksLikeAffirmativeFollowUp(raw) ||
    looksLikeNegativeFollowUp(raw) ||
    looksLikePlacesCapacityQuestion(raw)
  ) {
    return false;
  }

 if (looksLikePlacesQuery(raw) || looksLikeExplicitRouteQuery(raw) || looksLikeItineraryRequest(raw)) {
    return false;
  }

  // Brand/branch names (e.g., "Dunkin' - Insular Square") should not be treated as area refinements
  if (looksLikeBrandOrBranchName(raw)) {
    return false;
  }
  // "how about the dunkin" — strip prefix and check; brand follow-ups are not area refinements
  const strippedHowAbout = raw.replace(/^(?:how about|what about)\s+/i, "").replace(/[?.!]+$/, "").trim();
  if (strippedHowAbout && looksLikeBrandOrBranchName(strippedHowAbout)) {
    return false;
  }

  if (/^(?:how about|what about)\s+outside\s+[a-z0-9].+/i.test(raw)) {
    return true;
  }

  if (/^outside\s+[a-z0-9].+/i.test(raw)) {
    return true;
  }

  if (/^(?:how about|what about)\s+(?:near|in|around|at)\s+[a-z0-9].+/i.test(raw) && extractAreaHint(raw)) {
    return true;
  }

  if (/^(?:in|near|around|at)\s+[a-z0-9].+/i.test(raw) && extractAreaHint(raw)) {
    return true;
  }

  // Guard: "inside the mall" / "include inside the mall" / "inside a mall" are
  // filter constraints, not area names. Do not treat them as area refinements.
  if (/\b(inside|within)\s+(the|a|any)\s+(mall|malls|shopping center|shopping centre|market)\b/i.test(raw)) {
    return false;
  }
  if (/\b(include|only)\s+(inside|within|in)\s+(the|a|any)?\s*(mall|malls|shopping center|shopping centre|market)\b/i.test(raw)) {
    return false;
  }

  if (/\b(i mean|only|instead|inside|actually in|within|outside)\b/i.test(raw) && extractAreaHint(raw)) {
    return true;
  }

  return isBareAreaCandidate(raw);
}

function looksLikeCategoryTerm(text = "") {
  const t = String(text || "")
    .trim()
    .toLowerCase()
    .replace(/\bconvenient store\b/g, "convenience store")
    .replace(/\b7\s*\/\s*11\b/g, "7-eleven")
    .replace(/\b7\s+11\b/g, "7-eleven");

  if (!t) return false;

  // Generic place-type words and common category phrases that are NOT specific named places.
  return /^(coffee shops?|cafes?|restaurants?|bakery|bakeries|bars?|pharmacy|pharmacies|convenience stores?|convenience store|convenient store|hotels?|hostels?|pizza|burger|ramen|sushi|breakfast|groceries|grocery|places?|food|foods|shops?|stores?|accomodations?|accommodations?|lodging|fast food|chinese(?: foods?)?|italian(?: foods?)?|mexican(?: foods?)?|indian(?: foods?)?|thai(?: foods?)?|french(?: foods?)?|japanese(?: foods?)?|vietnamese(?: foods?)?|mediterranean(?: foods?)?|american(?: foods?)?|fusion(?: foods?)?|soul food|7[- ]?eleven|ministop)(\s+(that|which|near|in|at|around|open|24|with|having|me|there)\b.*)?$/i.test(t);
}

function looksLikeRefinementPhrase(text = "") {
  const t = String(text || "").trim().toLowerCase();
  if (!t) return false;
  return /^(which one|which ones|show me|show more|show me more|show \d+|show \d+ more|show me \d+ more|give me|\d+ more|another|more|closest|nearest|cheapest|best value|how do i get there|how can i get there|how to get there|route there|directions there)\b/i.test(t);
}

function looksLikeGenericLivePlacesSearch(text = "") {
  const raw = String(text || "").trim();
  const normalized = normalizeIntentText(text);
  if (!raw) return false;

  const hasGenericPlaceWords =
    /\b(coffee shop|coffee shops|coffee|cafe|cafes|restaurant|restaurants|food|foods|fast food|bakery|bakeries|bar|bars|pharmacy|pharmacies|hotel|hotels|hostel|hostels|convenience store|convenience stores|grocery|groceries|chinese|italian|mexican|indian|thai|french|japanese|vietnamese|mediterranean|american|fusion|soul food)\b/i.test(
      normalized
    );

  const hasLiveOrNearbyWords =
    /\b(near me|nearby|from here|closest|nearest|open now|currently open|24\s*hours?|24-hour|24hr|24 hrs?|open 24 hours?|open 24\/7|24\/7)\b/i.test(
      normalized
    );

  const hasAreaOrQualityWords =
    /\b(in|at|near)\s+[a-z0-9][a-z0-9&'’./ -]{1,80}\b/i.test(normalized) ||
    /\b(high rating|high ratings|highest rated|top rated|best rated|good rating|good ratings|good reviews|well reviewed|well-reviewed|most reviewed|top reviews|best reviews|popular|best|top|must try|must-try|authentic|affordable|budget friendly|budget-friendly|cheap|cheaper|quiet|cozy|cosy|family friendly|family-friendly)\b/i.test(
      normalized
    );

  const isBareGenericCategorySearch =
    /^(?:best\s+|top\s+|cheap\s+|affordable\s+|authentic\s+|high[- ]?rating\s+|highest[- ]?rated\s+|top[- ]?rated\s+|well[- ]?reviewed\s+|good\s+reviews\s+)?(?:coffee shops?|coffee|cafes?|restaurants?|hotels?|hostels?|baker(?:y|ies)|bars?|pharmacies?|convenience stores?|foods?|fast food|chinese(?: foods?)?|italian(?: foods?)?|mexican(?: foods?)?|indian(?: foods?)?|thai(?: foods?)?|french(?: foods?)?|japanese(?: foods?)?|vietnamese(?: foods?)?|mediterranean(?: foods?)?|american(?: foods?)?|fusion(?: foods?)?|soul food)(?:\s+that\s+(?:has|have)\s+(?:high\s+rating|good\s+reviews))?$/i.test(
      normalized
    );

  return (
    looksLikePlacesQuery(normalized) ||
    (hasGenericPlaceWords && (hasLiveOrNearbyWords || hasAreaOrQualityWords)) ||
    isBareGenericCategorySearch
  );
}

function looksLikeStrictNearbyPlaceSearch(text = "") {
  const raw = String(text || "").trim();
  const t = normalizeIntentText(raw);
  if (!t) return false;

  if (/\b(?:itinerary|trip\s+summary|full\s+itinerary|travel\s+plan|day\s*\d+)\b/i.test(t)) {
    return false;
  }

  const placeType =
    /\b(?:coffee\s+shops?|cafes?|café|restaurants?|food\s+spots?|places?\s+to\s+eat|eateries|bars?|steakhouse|branches?|locations?)\b/i.test(t);
  const anchor =
    /\b(?:near|around|close\s+to|nearest(?:\s+to)?|closest(?:\s+to)?|from|in|inside|at)\s+[\p{L}\p{N}][\p{L}\p{M}\p{N}&'’./() -]{1,90}\b/iu.test(raw);
  const branchOrNearest =
    /\b(?:location|locations|branch|branches|all)\b[\s\S]{0,80}\b(?:in|near|around|from)\b/i.test(t) ||
    /\b(?:nearest|closest)\b[\s\S]{0,80}\bfrom\b/i.test(t);

  return Boolean((placeType && anchor) || branchOrNearest);
}

// Lightweight, context-free detector for "is X open now?" / "what time
// does X close?" / "X opening hours" style questions. Intentionally does
// NOT consult placesContext or the active itinerary — callers use this to
// route a status query to the live place-status branch even when an
// itinerary is on the table and the message is unrelated to it.
function looksLikeSpecificPlaceStatusQuestion(text = "") {
  const raw = String(text || "").trim();
  if (!raw) return false;
  return (
    /^is\s+(?!it\b|that\b|this\b|this place\b|the place\b)([\p{L}\p{N}][\p{L}\p{N}&'’./() -]{1,100})\s+(?:still\s+)?(?:open|open now|open right now|currently open|closed|permanently closed)\??$/iu.test(raw) ||
    /^(?:what\s+time(?:\s+does)?|when(?:\s+does)?)\s+([\p{L}\p{N}][\p{L}\p{N}&'’./() -]{1,100})\s+(?:open|close)\b/i.test(raw) ||
    /^([\p{L}\p{N}][\p{L}\p{N}&'’./() -]{1,100})\s+(?:hours today|current hours|opening hours|closing time)\b/i.test(raw)
  );
}

function looksLikeSpecificPlaceOpenStatusQuery(text = "", placesContext = null) {
  const raw = String(text || "").trim();
  if (!raw) return false;

  if (looksLikeSavedPreferenceQuestion(raw) || looksLikeUsedProfileDetailsQuestion(raw)) {
    return false;
  }

  const normalizedRaw = normalizeIntentText(raw);

  const hasActiveSpecificPlaceContext = Boolean(
    String(
      placesContext?.userConfirmedPlaceName ||
      placesContext?.selectedPlaceName ||
      placesContext?.lastSpecificPlaceName ||
      (Array.isArray(placesContext?.latestDisplayedPlaceNames) && placesContext.latestDisplayedPlaceNames.length === 1
        ? placesContext.latestDisplayedPlaceNames[0]
        : "")
    ).trim()
  );

  const hasExplicitNamedStatusPattern =
    /^is\s+(?!it\b|that\b|this\b|this place\b|the place\b)([\p{L}\p{N}][\p{L}\p{N}&'’./() -]{1,100})\s+(?:still\s+)?(?:open|open now|open right now|currently open|closed|permanently closed)\??$/iu.test(raw) ||
    /^(?!open\b|closed\b|currently\b|hours\b|what\b|can\b|go\b)([\p{L}\p{N}][\p{L}\p{N}&'’./() -]{1,100})\s+(?:still\s+)?(?:open|open now|open right now|currently open|closed|permanently closed)\??$/iu.test(raw);

  const isExplicitNamedHoursQuestion =
    /^(?:what\s+time(?:\s+does)?|when(?:\s+does)?)\s+([\p{L}\p{N}][\p{L}\p{N}&'’./() -]{1,100})\s+(?:open|close)\b/i.test(raw) ||
    /^([\p{L}\p{N}][\p{L}\p{N}&'’./() -]{1,100})\s+(?:hours today|current hours|opening hours|closing time)\b/i.test(raw);

  const isActiveSpecificPlaceContextualFollowUp =
    hasActiveSpecificPlaceContext &&
    (
      /^(?:how about|what about)\s+(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\??$/i.test(raw) ||
      /^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\??$/i.test(normalizedRaw) ||
      /\bcan\s+i\s+(?:still\s+)?go\s+there\b/i.test(raw) ||
      /^can\s+go\s+there\s+(?:in|on)?\s*(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
      /^go\s+there\s+(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
      /^open\s+(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
      /^is\s+(?:it|this place|that place|the place)\s+(?:open|closed)\s+(?:on\s+)?(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
      /^what\s+time(?:\s+does)?\s+(?:it|this place|that place|the place)\s+(?:open|close)\b/i.test(raw) ||
      /^when(?:\s+does)?\s+(?:it|this place|that place|the place)\s+(?:open|close)\b/i.test(raw)
    );

  if (
    !isActiveSpecificPlaceContextualFollowUp &&
    !hasExplicitNamedStatusPattern &&
    !isExplicitNamedHoursQuestion &&
    (
      looksLikeRefinementPhrase(raw) ||
      looksLikeShortContextualFollowUp(raw) ||
      looksLikePlaceListSizeFollowUp(raw) ||
      looksLikePlacesRefinementFollowUp(raw) ||
      looksLikeAreaOnlyPlacesRefinement(raw) ||
      looksLikeLocationDiscussionMessage(raw) ||
      looksLikeCurrentTimeQuestion(raw)
    )
  ) {
    return false;
  }

  if (
    !hasExplicitNamedStatusPattern &&
    !isExplicitNamedHoursQuestion &&
    (
      looksLikeGenericLivePlacesSearch(raw) ||
      looksLikeCategoryTerm(raw) ||
      /^(?:best\s+|top\s+|cheap\s+|affordable\s+|authentic\s+|high[- ]?rating\s+|highest[- ]?rated\s+|top[- ]?rated\s+|well[- ]?reviewed\s+|good\s+reviews\s+)?(?:coffee shops?|cafes?|restaurants?|hotels?|hostels?|baker(?:y|ies)|bars?|pharmacies?|convenience stores?|food|chinese|italian|mexican|indian|thai|french|japanese|vietnamese|mediterranean|american|fusion|soul food)(?:\s+that\s+(?:has|have)\s+(?:high\s+rating|good\s+reviews))?$/i.test(
        raw
      )
    )
  ) {
    return false;
  }

  if (
    /^is\s+(?:it|that|this(?: place)?)\s+(?:still\s+)?(?:open|open now|open right now|currently open|closed|permanently closed)\??$/i.test(raw) ||
    hasExplicitNamedStatusPattern ||
    isExplicitNamedHoursQuestion ||
    /\bcan\s+i\s+(?:still\s+)?go\s+there\b/i.test(raw) ||
    /^can\s+go\s+there\s+(?:in|on)?\s*(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
    /^go\s+there\s+(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
    /^open\s+(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
    /^(?:how about|what about)\s+(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
    /^is\s+(?:it|this place|that place|the place)\s+(?:open|closed)\s+(?:on\s+)?(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
    /^what\s+time(?:\s+does)?\s+(?:it|this place|that place|the place)\s+(?:open|close)\b/i.test(raw) ||
    /^when(?:\s+does)?\s+(?:it|this place|that place|the place)\s+(?:open|close)\b/i.test(raw)
  ) {
    return true;
  }

  const target = extractNamedPlaceLookupTarget(raw, placesContext);
  if (looksLikeCategoryTerm(target.placeName)) return false;
  return Boolean(target.placeName) && target.asksStatus;
}

function stripPlaceLookupWrapperPhrases(value = "") {
  let out = String(value || "").trim();
  let previous = "";

  while (out && out !== previous) {
    previous = out;
    out = out
      .replace(/^(?:please\s+)?(?:could|can|would)\s+you\s+(?:please\s+)?(?:check|confirm|tell\s+me|look\s+up)\s+(?:if|whether)\s+/i, "")
      .replace(/^(?:please\s+)?(?:check|confirm|tell\s+me|look\s+up)\s+(?:if|whether)\s+/i, "")
      .replace(/^(?:please\s+)?(?:could|can|would)\s+you\s+(?:please\s+)?(?:check|confirm|tell\s+me|look\s+up)\s+/i, "")
      .replace(/^(?:please\s+)?(?:tell\s+me\s+about|look\s+up|check\s+this\s+place|check\s+this|this\s+place\s*:\s*)\s*/i, "")
      .replace(/^(?:what(?:'s| is| are)\s+(?:the\s+)?(?:opening\s+hours?|current\s+hours|hours|closing\s+time)\s+(?:of|for)\s+)/i, "")
      .replace(/^(?:what(?:'s| is)\s+the\s+place\s+for|what(?:'s| is)\s+the\s+place\s+of|show\s+me\s+the\s+place\s+for|show\s+me\s+the\s+place\s+of|show\s+me\s+the\s+places\s+for|show\s+me\s+the\s+places\s+of|give\s+me\s+the\s+place\s+for|give\s+me\s+the\s+place\s+of|give\s+me\s+the\s+places\s+for|give\s+me\s+the\s+places\s+of|provide\s+me\s+the\s+place\s+for|provide\s+me\s+the\s+place\s+of|provide\s+me\s+the\s+places\s+for|provide\s+me\s+the\s+places\s+of)\s+/i, "")
      .replace(/^(?:which\s+branch(?:es)?(?:\s+of)?|what\s+branch(?:es)?(?:\s+of)?)\s+/i, "")
      .replace(/^(?:show|give|provide|tell)\s+me\s+(?:the\s+)?(?:place|places|branch|branches|location|locations)\s+(?:of|for)\s+/i, "")
      .replace(/^(?:which|what)\s+(?:branch|branches|location|locations|place|places)(?:\s+of)?\s+/i, "")
      .replace(/^(?:where\s+is|where\s+are)\s+/i, "")
      .replace(/^is\s+there\s+only\s+\d+\s+/i, "")
      .replace(/^how\s+many\s+/i, "")
      .replace(/^(?:is|are)\s+/i, "")
      .trim();
  }

  return out;
}

function extractNamedPlaceLookupTarget(text = "", placesContext = null) {
  const raw = String(text || "").trim();
  if (!raw) {
    return {
      placeName: "",
      areaHint: "",
      asksStatus: false,
      asksBranch: false,
      asksList: false,
      asksCount: false,
      expectedCount: null,
      searchText: "",
      asksHoursFollowUp: false,
      hoursFollowUpTimeRef: "",
    };
  }

  const normalizedRaw = normalizeIntentText(raw);
  const isStandaloneGarbageLookup =
    /^(hi|hello|hey|yo|ok|okay|now)$/.test(normalizedRaw) ||
    /^(monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tomorrow|tonight)$/.test(normalizedRaw) ||
    /^(?:how about\s+)?now\??$/.test(normalizedRaw);

  let areaHint =
    extractAreaHint(raw) ||
    String(placesContext?.userConfirmedPlaceAddress || "").trim() ||
    String(placesContext?.areaHint || "").trim();
  areaHint = areaHint
    .replace(/\s*,?\s*(?:is|are)\s+(?:it|they|that|this)\b.*$/i, "")
    .replace(/[?.!]+$/, "")
    .trim();

  const contextName =
    String(
      placesContext?.userConfirmedPlaceName ||
      placesContext?.selectedPlaceName ||
      placesContext?.lastSpecificPlaceName ||
      (Array.isArray(placesContext?.latestDisplayedPlaceNames) && placesContext.latestDisplayedPlaceNames.length === 1
        ? placesContext.latestDisplayedPlaceNames[0]
        : "")
    ).trim();

  const contextAreaHint =
    String(placesContext?.userConfirmedPlaceAddress || "").trim() ||
    String(placesContext?.lastSpecificPlaceAddress || "").trim() ||
    areaHint;

  const hasActiveSpecificPlaceContext = Boolean(contextName);

  const isActiveSpecificPlaceContextualFollowUp =
    hasActiveSpecificPlaceContext &&
    (
      /^(?:how about|what about)\s+(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\??$/i.test(raw) ||
      /^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\??$/i.test(normalizedRaw) ||
      /^(?:is\s+)?(?:it|that|this(?: place)?|the place)\b/i.test(raw) ||
      /\bthere\b/i.test(raw) ||
      /\bcan\s+i\s+(?:still\s+)?go\s+there\b/i.test(raw) ||
      /\bgo\s+there\b/i.test(raw) ||
      /^open\s+(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
      /^go\s+there\s+(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
      /^can\s+go\s+there\s+(?:in|on)?\s*(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
      /^is\s+it\s+(?:open|closed)\s+(?:on\s+)?(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
      /^what\s+time(?:\s+does)?\s+(?:it|that|this(?: place)?|the place)\s+(?:open|close)\b/i.test(raw) ||
      /^when(?:\s+does)?\s+(?:it|that|this(?: place)?|the place)\s+(?:open|close)\b/i.test(raw)
    );

  if (
    !isActiveSpecificPlaceContextualFollowUp &&
    (
      looksLikeRefinementPhrase(raw) ||
      looksLikeShortContextualFollowUp(raw) ||
      looksLikePlaceListSizeFollowUp(raw) ||
      looksLikePlacesRefinementFollowUp(raw) ||
      looksLikeAreaOnlyPlacesRefinement(raw) ||
      looksLikeLocationDiscussionMessage(raw) ||
      looksLikeCurrentTimeQuestion(raw) ||
      isStandaloneGarbageLookup
    )
  ) {
    return {
      placeName: "",
      areaHint: "",
      asksStatus: false,
      asksBranch: false,
      asksList: false,
      asksCount: false,
      expectedCount: null,
      searchText: "",
      asksHoursFollowUp: false,
      hoursFollowUpTimeRef: "",
    };
  }

  const explicitCountMatch = raw.match(/\bis\s+there\s+only\s+(\d+)\b/i);
  const expectedCount = explicitCountMatch ? Number(explicitCountMatch[1]) : null;

  const weekdayOrRelativeHoursPattern =
    /\b(monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i;

  const asksStatus =
    /\b(open(?:\s+right\s+now|\s+now)?|currently open|closed|permanently closed|hours today|current hours|opening hours?|closing time)\b/i.test(raw) ||
    /\bwhat\s+time(?:\s+does)?\b/i.test(raw) ||
    /\bwhen(?:\s+does)?\b.*\b(open|close)\b/i.test(raw) ||
    /\bcan\s+i\s+(?:still\s+)?go\s+there\b/i.test(raw) ||
    /\bgo\s+there\b/i.test(raw) ||
    /\bis\s+(?:it|this place|that place|the place)\s+(?:open|closed)\b/i.test(raw) ||
    /\b(?:open|closed)\s+(?:on|this)?\s*(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
    /\b(?:how about|what about)\s+(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw);

  const asksBranch = /\bbranch(?:es)?\b/i.test(raw);
  const asksList =
    asksBranch ||
    /\b(place|places|location|locations|address|addresses)\b/i.test(raw) ||
    /\bwhere\s+(?:is|are)\b/i.test(raw);
  const asksCount = expectedCount != null || /\bhow\s+many\b/i.test(raw);

  const hoursFollowUpTimeRefMatch = raw.match(
    /\b(monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i
  );
  const hoursFollowUpTimeRef = String(hoursFollowUpTimeRefMatch?.[1] || "").trim().toLowerCase();

  let hoursQuestionType = "";
  if (
    /\b(?:open\s+right\s+now|open\s+now|currently\s+open)\b/i.test(raw) ||
    /\bwhat\s+time(?:\s+does)?\s+(?:it|that|this(?: place)?|the place)?\s*open\b/i.test(raw) ||
    /\bwhen(?:\s+does)?\s+(?:it|that|this(?: place)?|the place)?\s*open\b/i.test(raw)
  ) {
    hoursQuestionType = "open";
  } else if (
    /\bwhat\s+time(?:\s+does)?\s+(?:it|that|this(?: place)?|the place)?\s*close\b/i.test(raw) ||
    /\bwhen(?:\s+does)?\s+(?:it|that|this(?: place)?|the place)?\s*close\b/i.test(raw)
  ) {
    hoursQuestionType = "close";
  } else if (
    /\b(?:opening\s+hours?|current\s+hours|hours\s+today)\b/i.test(raw) ||
    /\bwhat\s+(?:are|is)\s+the\s+(?:opening\s+hours?|current\s+hours|hours)\s+(?:of|for)\b/i.test(raw)
  ) {
    hoursQuestionType = "hours";
  }

  const directNamedStatusMatch = raw.match(
    /^is\s+(?!it\b|that\b|this\b|this place\b|the place\b)([\p{L}\p{N}][\p{L}\p{N}&''./() -]{1,100}?)\s+(?:still\s+)?(?:open(?:\s+right\s+now|\s+now)?|currently open|closed|permanently closed)\??$/iu
  );

  const bareNamedStatusMatch = raw.match(
    /^(?!open\b|closed\b|currently\b|hours\b|what\b|can\b|go\b)([\p{L}\p{N}][\p{L}\p{N}&''./() -]{1,100}?)\s+(?:still\s+)?(?:open(?:\s+right\s+now|\s+now)?|currently open|closed|permanently closed)\??$/iu
  );

  const directNamedHoursMatch = raw.match(
    /^(?:can\s+(?:i\s+)?go\s+there\s+(?:in|on)?\s*|is\s+it\s+(?:open|closed)\s+(?:on\s+)?|(?:how about|what about)\s+)?(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\s+(?:in\s+)?([\p{L}\p{N}][\p{L}\p{N}&''./() -]{1,100})$/iu
  );

  const contextualNamedHoursMatch = raw.match(
    /^(?:can\s+(?:i\s+)?go\s+there\s+(?:in|on)?\s*|is\s+it\s+(?:open|closed)\s+(?:on\s+)?|(?:how about|what about)\s+)(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\s+(?:in\s+)?([\p{L}\p{N}][\p{L}\p{N}&''./() -]{1,100})$/iu
  );

  const isContextualHoursFollowUp =
    (
      /^(?:is\s+)?(?:it|that|this(?: place)?|the place)\b/i.test(raw) ||
      /\bthere\b/i.test(raw) ||
      /\bcan\s+i\s+(?:still\s+)?go\s+there\b/i.test(raw) ||
      /\bgo\s+there\b/i.test(raw) ||
      /^(?:how about|what about)\s+(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\??$/i.test(raw) ||
      /^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\??$/i.test(normalizedRaw) ||
      /^open\s+(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
      /^go\s+there\s+(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
      /^can\s+go\s+there\s+(?:in|on)?\s*(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
      /^is\s+it\s+(?:open|closed)\s+(?:on\s+)?(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
      /^what\s+time(?:\s+does)?\s+(?:it|that|this(?: place)?|the place)\s+(?:open|close)\b/i.test(raw) ||
      /^when(?:\s+does)?\s+(?:it|that|this(?: place)?|the place)\s+(?:open|close)\b/i.test(raw)
    ) &&
    (weekdayOrRelativeHoursPattern.test(raw) || /\b(open|close|closed|hours)\b/i.test(raw));

  if (
    !contextName &&
    (
      /^can\s+go\s+there\s+(?:in|on)?\s*(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
      /^is\s+it\s+(?:open|closed)\s+(?:on\s+)?(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
      /^(?:how about|what about)\s+(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b/i.test(raw) ||
      /^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\??$/i.test(normalizedRaw) ||
      /^what\s+time(?:\s+does)?\s+(?:it|that|this(?: place)?|the place)\s+(?:open|close)\b/i.test(raw) ||
      /^when(?:\s+does)?\s+(?:it|that|this(?: place)?|the place)\s+(?:open|close)\b/i.test(raw)
    )
  ) {
    return {
      placeName: "",
      areaHint: "",
      asksStatus: false,
      asksBranch: false,
      asksList: false,
      asksCount: false,
      expectedCount: null,
      searchText: "",
      asksHoursFollowUp: Boolean(hoursFollowUpTimeRef) || Boolean(hoursQuestionType),
      hoursFollowUpTimeRef,
    };
  }

  const parenthesized = extractParenthesizedPlaceContext(raw);
  if (parenthesized?.label) {
    return {
      placeName: parenthesized.label,
      areaHint: parenthesized.address || areaHint,
      asksStatus,
      asksBranch,
      asksList,
      asksCount,
      expectedCount,
      searchText: parenthesized.anchorText,
      asksHoursFollowUp: Boolean(hoursFollowUpTimeRef) || Boolean(hoursQuestionType),
      hoursFollowUpTimeRef,
      hoursQuestionType,
    };
  }

  if (directNamedStatusMatch || bareNamedStatusMatch || directNamedHoursMatch || contextualNamedHoursMatch) {
    const directPlaceName = String(
      (
        directNamedStatusMatch?.[1] ||
        bareNamedStatusMatch?.[1] ||
        directNamedHoursMatch?.[1] ||
        contextualNamedHoursMatch?.[1] ||
        ""
      )
    ).trim().replace(/[?.!]+$/, "");

    return {
      placeName: directPlaceName,
      areaHint,
      asksStatus: true,
      asksBranch: false,
      asksList: false,
      asksCount: false,
      expectedCount: null,
      searchText: [directPlaceName, areaHint].filter(Boolean).join(", "),
      asksHoursFollowUp: Boolean(hoursFollowUpTimeRef) || Boolean(hoursQuestionType),
      hoursFollowUpTimeRef,
      hoursQuestionType,
    };
  }

  if (
    /^is\s+(?:it|that|this(?: place)?)\s+(?:still\s+)?(?:open|open now|open right now|currently open|closed|permanently closed)\??$/i.test(raw) ||
    (isContextualHoursFollowUp && contextName)
  ) {
    return {
      placeName: contextName,
      areaHint: contextAreaHint,
      asksStatus: true,
      asksBranch: false,
      asksList: false,
      asksCount: false,
      expectedCount: null,
      searchText: [contextName, contextAreaHint].filter(Boolean).join(", "),
      asksHoursFollowUp: isContextualHoursFollowUp,
      hoursFollowUpTimeRef,
      hoursQuestionType,
    };
  }

  const cleaned = stripPlaceLookupWrapperPhrases(raw.replace(/[?.!]+$/, "").trim());

  let closestToLandmark = "";
  const thenParts = cleaned.split(/\s*,\s*then\s+/i);
  const primaryCleaned = thenParts[0] || cleaned;
  if (thenParts.length >= 2) {
    const afterThen = thenParts.slice(1).join(", then ");
    const closestMatch = afterThen.match(
      /(?:which\s+(?:one|branch|location)\s+is\s+)?closest\s+to\s+([\p{L}][\p{L}\p{N}&'’./ -]{2,80})/iu
    );
    if (closestMatch) {
      closestToLandmark = String(closestMatch[1] || "").trim().replace(/[?.!]+$/, "");
    }
  }

  const inlineAreaMatch = primaryCleaned.match(/\b(?:in|at|near)\s+([A-Za-z][A-Za-z0-9&''./ -]{1,80})$/i);
  if (inlineAreaMatch && !areaHint) {
    areaHint = String(inlineAreaMatch[1] || "").trim().replace(/[?.!]+$/, "");
  }

  let placeName = primaryCleaned
    .replace(/\s*,\s*(?:is\s+it|is\s+that|is\s+this(?: place)?)\s+(?:still\s+)?(?:open(?:\s+right\s+now|\s+now)?|currently open|closed|permanently closed|hours today|current hours)\b.*$/i, "")
    .replace(/\s*,?\s*(?:what\s+time(?:\s+does)?|when(?:\s+does)?)\s+(?:it|this place|that place)\s+(?:open|close)\b.*$/i, "")
    .replace(/\s*,?\s*can\s+i\s+(?:still\s+)?go\s+there\b.*$/i, "")
    .replace(/\s*,?\s*go\s+there\b.*$/i, "")
    .replace(/\s*,?\s*is\s+it\s+(?:open|closed)\s+(?:on\s+)?(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b.*$/i, "")
    .replace(/\s*,?\s*(?:how\s+about|what\s+about)\s+(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tonight|tomorrow)\b.*$/i, "")
    .replace(/\s+(?:is\s+)?(?:open(?:\s+right\s+now|\s+now)?|currently open|closed|permanently closed|hours today|current hours|opening hours?|closing time)\b.*$/i, "")
    .replace(/[?.!]+$/, "")
    .trim();

  placeName = placeName
    .replace(/^(?:i mean\s+)/i, "")
    .replace(/\b(?:is\s+a\s+place)\b/i, "")
    .replace(/\b(?:in|at|near)\s+[A-Za-z][A-Za-z0-9&'’./ -]{1,80}$/i, "")
    .replace(/[?.!]+$/, "")
    .trim();

  const searchText = [placeName, areaHint].filter(Boolean).join(", ");

  return {
    placeName,
    areaHint,
    asksStatus,
    asksBranch,
    asksList,
    asksCount,
    expectedCount,
    searchText,
    closestToLandmark,
    asksHoursFollowUp: false,
    hoursFollowUpTimeRef,
    hoursQuestionType,
  };
}

function looksLikeNamedPlaceLookupQuery(text = "", placesContext = null) {
  const raw = String(text || "").trim();
  if (!raw) return false;
  if (looksLikeSavedPreferenceQuestion(raw) || looksLikeUsedProfileDetailsQuestion(raw)) return false;
  if (looksLikeRefinementPhrase(raw)) return false;
  if (looksLikeExplicitRouteQuery(raw) || looksLikeItineraryRequest(raw)) return false;

  const target = extractNamedPlaceLookupTarget(raw, placesContext);
  const targetPlaceName = String(target.placeName || "").trim();

  if (
    looksLikePlacesQuery(raw) &&
    (
      /\b(near me|nearby|near|around|closest|nearest|find|show|recommend|list|provide|coffee shop|coffee shops|cafe|cafes|restaurant|restaurants|food|fast food|hotel|hotels|hostel|hostels|bakery|bakeries|bar|bars|pharmacy|pharmacies|24\s*hours?|24-hour|24hr|24 hrs?|open 24 hours?|open 24\/7|24\/7|open now|currently open)\b/i.test(raw) ||
      looksLikeCategoryTerm(targetPlaceName || raw)
    )
  ) {
    return false;
  }

  if (looksLikeSpecificPlaceOpenStatusQuery(raw, placesContext)) return true;

  if (!targetPlaceName) {
    return looksLikeStandaloneSpecificPlaceName(raw);
  }
  if (looksLikeCategoryTerm(targetPlaceName)) return false;

  return (
    target.asksStatus ||
    target.asksBranch ||
    target.asksList ||
    target.asksCount ||
    target.asksHoursFollowUp ||
    looksLikeStandaloneSpecificPlaceName(raw) ||
    /\b(tell me about|look up|check this place|where is|where are)\b/i.test(raw)
  );
}

function extractSpecificPlaceStatusTarget(text = "", placesContext = null) {
  const raw = String(text || "").trim();
  const target = extractNamedPlaceLookupTarget(raw, placesContext);
  const normalized = normalizeIntentText(raw);

  let placeName = String(target.placeName || "").trim();
  const areaHint = String(target.areaHint || "").trim();

  if (!placeName) {
    const explicitOpenCloseMatch =
      raw.match(
        /^is\s+(?!it\b|that\b|this\b|this place\b|the place\b)([\p{L}\p{N}][\p{L}\p{N}&'’./() -]{1,100}?)\s+(?:still\s+)?(?:open(?:\s+right\s+now|\s+now)?|currently open|closed|permanently closed)\??$/iu
      ) ||
      raw.match(
        /^(?!open\b|closed\b|currently\b|hours\b|what\b|can\b|go\b)([\p{L}\p{N}][\p{L}\p{N}&'’./() -]{1,100}?)\s+(?:still\s+)?(?:open(?:\s+right\s+now|\s+now)?|currently open|closed|permanently closed)\??$/iu
      ) ||
      raw.match(
        /^(?:what\s+time(?:\s+does)?|when(?:\s+does)?)\s+([\p{L}\p{N}][\p{L}\p{N}&'’./() -]{1,100}?)\s+(open|close)\b/i
      ) ||
      raw.match(
        /^([\p{L}\p{N}][\p{L}\p{N}&'’./() -]{1,100}?)\s+(?:hours today|current hours|opening hours|closing time)\b/i
      );

    placeName = String(explicitOpenCloseMatch?.[1] || "").trim();
  }

  let hoursQuestionType = "";
  if (
    /\b(?:open\s+right\s+now|open\s+now|currently\s+open)\b/i.test(raw) ||
    (
      (
        /\bwhat\s+time\b/i.test(raw) ||
        /\bwhen\b/i.test(raw)
      ) &&
      /\bopen\b/i.test(raw)
    )
  ) {
    hoursQuestionType = "open";
  } else if (
    (
      /\bwhat\s+time\b/i.test(raw) ||
      /\bwhen\b/i.test(raw)
    ) &&
    /\bclose\b/i.test(raw)
  ) {
    hoursQuestionType = "close";
  } else {
    hoursQuestionType = String(target.hoursQuestionType || "").trim().toLowerCase();
  }

  return {
    placeName,
    areaHint,
    asksHoursFollowUp: Boolean(target.asksHoursFollowUp) || Boolean(hoursQuestionType),
    hoursFollowUpTimeRef: String(target.hoursFollowUpTimeRef || "").trim().toLowerCase(),
    hoursQuestionType,
    asksOpenTimeOnly:
      hoursQuestionType === "open" ||
      (/\bwhat\s+time\b/.test(normalized) && /\bopen\b/.test(normalized)),
    asksCloseTimeOnly:
      hoursQuestionType === "close" ||
      (/\bwhat\s+time\b/.test(normalized) && /\bclose\b/.test(normalized)),
  };
}

function extractPlaceLikeFollowUpCandidate(text = "") {
  const raw = String(text || "").trim();
  if (!raw) return "";

  if (
    looksLikeShortContextualFollowUp(raw) ||
    looksLikePlaceListSizeFollowUp(raw) ||
    looksLikePlacesRefinementFollowUp(raw) ||
    looksLikeAreaOnlyPlacesRefinement(raw) ||
    looksLikePlacesQuery(raw) ||
    looksLikeExplicitRouteQuery(raw) ||
    looksLikeItineraryRequest(raw) ||
    looksLikeCurrentLocationQuestion(raw) ||
    looksLikeSpecificPlaceOpenStatusQuery(raw) ||
    looksLikeNamedPlaceLookupQuery(raw)
  ) {
    return "";
  }

  if (/^(?:in|near|around|at|outside|inside|within)\b/i.test(raw)) {
    return "";
  }

  const cleaned = raw
    .replace(/^(?:how about|what about|maybe|try|now)\s+/i, "")
    .replace(/[?.!]+$/, "")
    .trim();

  if (!cleaned || !looksLikePossiblePlaceName(cleaned)) {
    return "";
  }

  // Category terms like "food", "food near me" are not specific place candidates
  if (looksLikeCategoryTerm(cleaned)) {
    return "";
  }

  // Brand/branch names are always place candidates, even with "how about" prefix.
  // Checked BEFORE the bare-city reject below so brand names like "Jollibee"
  // or "Starbucks Reserve" (which would otherwise shape-match as plain city
  // names) take the accept path.
  if (looksLikeBrandOrBranchName(cleaned)) {
    return cleaned;
  }

  // Geographic-type words: "Central Park", "JFK Airport", "Manila Bay" etc.
  // These are area references, not specific place lookups.
  if (/\b(?:city|district|province|country|park|beach|island|airport|terminal|station|road|street|avenue|ave|boulevard|blvd|plaza|center|centre|port|harbor|harbour|bay|hill|heights|village|town|poblacion|mall|circle|campus|fort)\b/i.test(cleaned)) {
    return "";
  }

  // Bare city-shape reject: if the cleaned text is a 1-2 token capitalized
  // phrase with no business-word modifier, treat it as a city name rather
  // than a specific place. Previously this used findKnownPlace(cleaned)
  // which only caught ~150 listed cities — now it's a structural check
  // that works for any Latin-script city name (Tokyo, Paris, Reykjavik,
  // New York, Los Angeles). Multi-token non-Latin names ("東京", "São Paulo")
  // also match the shape test via Unicode property escapes.
  //
  // NOTE: Brand names already took the accept path above, so this check
  // won't incorrectly reject "Jollibee" or "Starbucks Reserve". Business
  // phrases like "Joe's Coffee" or "Senso-ji Temple" contain non-letter
  // characters or business modifiers handled by the lines below.
  const bareCityShape = /^[\p{Lu}\p{Lo}][\p{L}\p{M}]+(?:\s+[\p{Lu}\p{Lo}][\p{L}\p{M}]+){0,1}$/u;
  if (bareCityShape.test(cleaned) && !/[''&.-]/.test(cleaned)) {
    return "";
  }

  const startsAsAreaSuggestion = /^(?:how about|what about)\b/i.test(raw);
  if (
    startsAsAreaSuggestion &&
    !/^(?:the\s+)/i.test(cleaned) &&
    !/[''&.]/.test(cleaned) &&
    !/\b(?:of|coffee|cafe|donut|donuts|burger|pizza|ramen|sushi|bakery|bar|grill|house|hotel|hostel|inn|resort|pharmacy)\b/i.test(cleaned)
  ) {
    return "";
  }

  return cleaned;
}

const DURATION_WORD_TO_NUM = {
  one: 1,
  two: 2,
  three: 3,
  four: 4,
  five: 5,
  six: 6,
  seven: 7,
  eight: 8,
  nine: 9,
  ten: 10,
};

function parseDayNumberToken(value = "") {
  const token = String(value || "").trim().toLowerCase();
  if (!token) return null;
  if (/^\d+$/.test(token)) {
    const n = Number(token);
    return n >= 1 && n <= 60 ? n : null;
  }
  return DURATION_WORD_TO_NUM[token] || null;
}

function extractRequestedDurationCorrectionDays(text = "") {
  const raw = String(text || "");
  const lower = raw.toLowerCase();
  const num = "(\\d{1,2}|one|two|three|four|five|six|seven|eight|nine|ten)";

  const dayMissing =
    lower.match(/\bday\s*(\d{1,2}|one|two|three|four|five|six|seven|eight|nine|ten)\b.*\b(?:missing|forgot|forgotten|left out|not included|absent|gone)\b/i) ||
    lower.match(/\b(?:missing|forgot|forgotten|left out|not included|where(?:'s| is))\b.*\bday\s*(\d{1,2}|one|two|three|four|five|six|seven|eight|nine|ten)\b/i);
  if (dayMissing) return parseDayNumberToken(dayMissing[1]);

  const requested =
    lower.match(new RegExp(`\\binstead\\s+of\\s+${num}\\s*(?:day|days|night|nights)?[\\s\\S]{0,90}?\\b(?:can\\s+you\\s+)?(?:make|change|update|set|turn)\\s+(?:it|this|the\\s+trip|the\\s+duration)?\\s*(?:to|into)?\\s*${num}\\s*(?:day|days|night|nights)?\\b`, "i")) ||
    lower.match(/\b(?:actually\s+)?(?:make it|change it to|update it to|update to|set it to|turn it into|extend it to|can you make it)\s+(\d{1,2}|one|two|three|four|five|six|seven|eight|nine|ten)\s*[- ]?\s*(?:days?|nights?)\b/i) ||
    lower.match(new RegExp(`\\b(?:can\\s+you\\s+)?(?:make|change|update|set|turn)\\s+(?:it|this|the\\s+trip|the\\s+duration)?\\s*(?:to|into)?\\s*${num}\\s*(?:day|days|night|nights)?\\b`, "i")) ||
    lower.match(/\b(?:for|to)\s+(\d{1,2}|one|two|three|four|five|six|seven|eight|nine|ten)\s*[- ]?\s*(?:days?|nights?)\b/i) ||
    lower.match(new RegExp(`\\b(?:duration|trip\\s+duration|days?)\\s+(?:should\\s+be|is|are|=|to)\\s*${num}\\s*(?:day|days|night|nights)?\\b`, "i")) ||
    lower.match(new RegExp(`\\bactually\\s+${num}\\s*(?:day|days|night|nights)?\\b`, "i")) ||
    lower.match(new RegExp(`\\bshorter\\s+(?:to|into)\\s+${num}\\s*(?:day|days|night|nights)?\\b`, "i"));
  if (requested && !/\bstill\s+\d+\s*[- ]?\s*days?\b/i.test(lower)) {
    return parseDayNumberToken(requested[requested.length - 1]);
  }

  return null;
}

function looksLikeItineraryDurationMismatchCorrection(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;
  return (
    /\bstill\s+\d+\s*[- ]?\s*days?\b/.test(t) ||
    /\bday\s*(?:\d{1,2}|one|two|three|four|five|six|seven|eight|nine|ten)\b.*\b(?:missing|forgot|forgotten|left out|not included|absent|gone)\b/.test(t) ||
    /\b(?:missing|forgot|forgotten|left out|not included|where(?:'s| is))\b.*\bday\s*(?:\d{1,2}|one|two|three|four|five|six|seven|eight|nine|ten)\b/.test(t) ||
    /\b(?:does not|doesn't|did not|didn't|still does not|still doesn't)\s+match\s+(?:the\s+)?summary\b/.test(t) ||
    /\brequested\s+duration\b/.test(t)
  );
}


function looksLikeItineraryEditRequest(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  if (looksLikeItineraryDurationMismatchCorrection(t) || extractRequestedDurationCorrectionDays(t)) {
    return true;
  }

  if (
    /\b(edit|change|update|modify|revise|adjust|rework|swap|replace|move|shift|remove|delete|add|insert|shorten|extend|relax|relaxed|slower|faster|more food|more history|less walking|regenerate|regen|rebuild|recreate|redo|repair|fix|resolve|honor|honour|respect|enforce|align|reschedule|exclude|drop|skip|omit|leave\s+out|take\s+out)\b/.test(
      t
    ) &&
    /\b(itinerary|trip|plan|schedule|stops?|day\s*\d+|day one|day two|day three|day four|day five)\b/.test(t)
  ) {
    return true;
  }

  // Natural context edits after an itinerary/blueprint is already in chat:
  // "replace larsian with sugbo mercado", "swap X for Y", "add breakfast",
  // "change the origin I will be in Bohol", "start at 7am".
  if (
    /\b(?:replace|swap|change)\s+.{2,80}?\s+(?:with|for|to)\s+.{2,80}\b/.test(t)
  ) {
    return true;
  }

  if (
    /\b(?:change|update|set)\s+(?:the\s+)?(?:origin|starting point|start point|base|starting area)\b/.test(t)
  ) {
    return true;
  }

  if (
    /\b(?:my|our|the)\s+(?:hotel|base|origin|starting point|start point|starting area)\s+(?:is|=|at|in)\s+[\p{L}\p{N}]/iu.test(t) ||
    /\b(?:i'?m|i\s+am|im|we'?re|we\s+are|staying|based)\s+(?:at|in|near)\s+[\p{L}\p{N}].*\b(?:hotel|inn|resort|hostel|base)\b/iu.test(t)
  ) {
    return true;
  }

  if (
    /\b(?:we|i|we'?ll|i'?ll|we\s+will|i\s+will)\s+(?:have|use|take|bring|drive)\s+(?:a\s+|our\s+|my\s+)?car\b/i.test(t) ||
    /\b(?:private car|own car|driving|drive ourselves|transport mode|use local transport|local transport)\b/i.test(t)
  ) {
    return true;
  }

  if (
    /\b(?:add|insert|include|put|start with|begin with)\b.*\b(?:breakfast|lunch|dinner|snack|merienda|coffee|meal)\b/.test(t)
  ) {
    return true;
  }

  if (
    /\b(?:start|leave|depart|arrive|arrival)\s+(?:at|around|by)?\s*\d{1,2}(?::\d{2})?\s*(?:am|pm)?\b/.test(t) ||
    /\b(?:the\s+time\s*,?\s*)?(?:at|around|by)\s+\d{1,2}(?::\d{2})?\s*(?:am|pm)?\b/.test(t)
  ) {
    return true;
  }

  if (
    /\b(?:make it|change to|set to|update to|make the trip|change the trip)\b.*\b(?:budget|cheap|affordable|mid[\s-]?range|luxury|premium|\d+\s*days?|one\s*day|two\s*days?|three\s*days?)\b/.test(t)
  ) {
    return true;
  }

  if (/\bday\s*\d+\b.*\b(?:must|should)\s+not\b.*\b(?:free|rest|open)\s+(?:city\s+)?day\b/.test(t)) {
    return true;
  }

  if (
    /\b(?:add|include|remove|drop|skip|avoid)\b.*\b(?:food|history|nature|shopping|beach|religious|churches|nightlife|museums?|culture|scenic)\b/.test(t)
  ) {
    return true;
  }

  // Catch follow-ups that reference provider/opening/operating hours or

  // schedule conflicts even when they don't carry the word "itinerary"/"plan".
  // Example: "regenerate around provider-supported opening hours",
  // "no time conflict", "fix the closing hours conflict".
  if (
    /\b(?:provider[- ]?supported|provider[- ]?backed|provider\s+hours|opening\s+hours|operating\s+hours|business\s+hours|closing\s+hours|closing\s+time)\b/.test(t) ||
    /\b(?:no\s+(?:more\s+)?(?:time|schedule|schedul(?:e|ing)|hours|opening)\s*conflicts?|without\s+conflicts?|conflict[- ]?free)\b/.test(t) ||
    /\baround\s+(?:the\s+)?(?:provider|opening|operating|business|supported)(?:[- ]?supported)?\s*(?:opening\s+)?hours\b/.test(t)
  ) {
    return true;
  }

  // Catch "(don't|do not|just dont) include X (in/from) the itinerary"
  if (
    /\b(?:do\s*n[o']?t|dont|don['']?t)\s+include\b/.test(t) &&
    /\b(itinerary|plan|trip|schedule|stops?|day\s*\d+)\b/.test(t)
  ) {
    return true;
  }

  if (
    /\b(make|turn)\b.*\b(day\s*\d+)\b.*\b(relaxed|slower|faster|cheaper|more food|more history|more cultural|more adventurous)\b/.test(
      t
    )
  ) {
    return true;
  }

  if (
    /\b(move|shift|swap|replace|remove|delete|add|insert|reorder|put|make)\b/.test(t) &&
    /\b(earlier|later|first|last|before|after|start|end|stop|day\s*\d+|day one|day two|day three|day four|day five)\b/.test(t)
  ) {
    return true;
  }

  if (
    /^(?:okay\s+|ok\s+)?(?:move|shift|swap|replace|remove|delete|put)\s+(?:that|this|it)\b/.test(t)
  ) {
    return true;
  }

  if (
    /\b(?:put|move|shift)\s+(?:it|that|this)\s+(?:on\s+)?(?:an?\s+)?(earlier|later)\s+time\b/.test(t)
  ) {
    return true;
  }

  if (
    /\breplace\s+that\s+place\b/.test(t)
  ) {
    return true;
  }

  // Catch "change the plan" / "revise it" with specific edit actions
  if (
    /\b(change|revise|update|modify|rework|redo)\s+(the\s+)?(plan|itinerary|trip|schedule)\b/.test(t) &&
    /\b(add|remove|delete|swap|replace|move|keep|insert|less backtracking|more logical|better flow|better route)\b/.test(t)
  ) {
    return true;
  }

  // Catch "using the ... itinerary you just created ... revise it"
  if (
    /\b(using the|based on the|from the|with the)\b/.test(t) &&
    /\b(itinerary|plan|trip)\b/.test(t) &&
    /\b(revise|change|edit|update|modify|add|remove|swap|replace)\b/.test(t)
  ) {
    return true;
  }

  // Catch "a full itinerary, X dinner and Y last stop" as an edit when
  // the phrase includes specific stop instructions
  if (
    /\b(full|complete|entire)\s+(itinerary|plan|schedule)\b/.test(t) &&
    /\b(last stop|first stop|include|start with|end with|dine|dinner|lunch|breakfast)\b/.test(t)
  ) {
    return true;
  }

  return false;
}

function looksLikeEditSummaryQuestion(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  return (
    /\bwhat(?:'s| is)?\s+different\b/.test(t) ||
    /\bwhat(?:'s| is)?\s+different\s+now\b/.test(t) ||
    /\bdifferent\s+now\b/.test(t) ||
    /\bwhat(?:'s| is)?\s+changed\b/.test(t) ||
    /\bwhat\s+did\s+you\s+(?:change|edit|modify|update)\b/.test(t) ||
    /\bwhat\s+was\s+updated\b/.test(t) ||
    /\bsummarize\s+(?:the\s+)?edits\b/.test(t) ||
    /\bsummary\s+of\s+(?:the\s+)?edits\b/.test(t) ||
    /\bwhich\s+(?:part|parts|day|days)\s+did\s+you\s+(?:change|edit|modify)\b/.test(t) ||
    /\bwhich\s+changes\s+did\s+you\s+make\b/.test(t) ||
    /\bcan\s+you\s+tell\s+me\s+what\s+you\s+changed\b/.test(t) ||
    /\bdid\s+you\s+remove\s+anything\b/.test(t) ||
    /\bwhat\s+did\s+you\s+remove\b/.test(t) ||
    /\bhow\s+is\s+this\s+different\s+from\s+before\b/.test(t)
  );
}

function looksLikeMapDayFollowUp(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  return (
    /\bwhat(?:'s| is)\s+on\s+day\s*\d+\b/.test(t) ||
    /\bwhat(?:'s| is)\s+on\s+day\s*\d+\s+now\b/.test(t) ||
    /\bday\s*\d+\s+now\b/.test(t) ||
    /\bshow\b.*\bday\s*\d+\b/.test(t) ||
    /\bshow\s+only\s+day\s*\d+\b/.test(t) ||
    /\bonly\s+day\s*\d+\b/.test(t) ||
    /\bjust\s+day\s*\d+\b/.test(t) ||
    /\bmap\b.*\bday\s*\d+\b/.test(t) ||
    /\bstops?\b.*\bday\s*\d+\b/.test(t) ||
    /\bwhich\s+stops?\b/.test(t) ||
    /\bwhich\s+day\b.*\b(on|for)\b/.test(t)
  );
}

function looksLikeSaveFollowUp(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  return /\b(save|saved|save this|save itinerary|save trip|edit this saved itinerary)\b/.test(t);
}

function looksLikeUnexpectedSaveQuestion(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  return (
    /\bwhy\b.*\bsav(?:e|ed|ing)\b/.test(t) ||
    /\bdid\s+(?:you|it)\s+sav(?:e|ed)\b/.test(t) ||
    /\bi\s+(?:didn'?t|didnt)\s+(?:ask|tell)\s+you\s+to\s+save\b/.test(t)
  );
}

function looksLikeShortContextualFollowUp(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  // Exact short continuations
  if (/^(another|another one|more|more please|show more|other options?|more options|give me more|show me more|more like this|any other options?|what else|anything else|next|the next one|next one|others|show others|similar|like that|same|same area|same place|near there|that area|around there)$/.test(t)) {
    return true;
  }

  // "show more" / "more results" / "give me alternatives" patterns
  if (/^(?:show|give|list|find)\s+(?:me\s+)?(?:more|others|alternatives|similar)\s*(?:options?|places?|results?)?$/.test(t)) {
    return true;
  }

  return false;
}

function looksLikePlaceListSizeFollowUp(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  return (
    /^(?:give me|show me|show|list|recommend|add)?\s*\d+\s*(?:more)?\s*(?:options?|places?)?$/.test(t) ||
    /^(?:give me|show me|show|list|recommend|add)\s+\d+\s+/.test(t) ||
    /^\d+\s+more\b/.test(t) ||
    /^add\s+\d+\s+more\b/.test(t) ||
    /^\d+\s+(?:more\s+)?(?:coffee shop|coffee shops|cafe|cafes|restaurant|restaurants|bakery|bakeries|bar|bars|convenience store|convenience stores|pharmacy|pharmacies|hotel|hotels|hostel|hostels|places)\b/.test(t)
  );
}

function looksLikePlacesCountRelaxationFollowUp(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  return (
    /\b(it does not|it doesn't|it doesnt|doesn't|doesnt|not)\s+have\s+to\s+be\s+\d+\b/.test(t) ||
    /\bnot\s+\d+\s+(?:places|options|results)\b/.test(t) ||
    /\bjust\s+\d+\s+(?:places|options|results)\b/.test(t) ||
    /\bonly\s+\d+\s+(?:places|options|results)\b/.test(t)
  );
}

function extractRequestedPlacesCount(text = "", fallback = 5) {
  const t = normalizeIntentText(text);
  const m = t.match(/\b(\d{1,2})\b/);
  const n = m ? Number(m[1]) : Number(fallback || 5);

  if (!Number.isFinite(n) || n <= 0) return 5;
  return Math.min(n, 10);
}

function looksLikePlacesRefinementFollowUp(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  return (
    looksLikeShortContextualFollowUp(t) ||
    looksLikePlaceListSizeFollowUp(t) ||
    looksLikePlacesCountRelaxationFollowUp(t) ||
    /\b(what'?s nearby|what is nearby|anything nearby|nearby places|closest|nearest|which one is closest|which one is nearest|closest walk|closest walk from here|walk from here|from here|open late|late|open now|currently open|24 hours|24 hour|24\/7|which ones are actually in|actually in|inside the area only|closest to|cheapest|cheaper|lowest price|best value|for 2 person only|for 2 people only|good for 2 people|good for 2 person|for two people only|for two person only|show \d+|show me \d+|now .* instead|how do i get there|how can i get there|how to get there|route there|directions there)\b/i.test(
      t
    ) ||
    // Tight refinement additions: only obvious filter/constraint forms
    /^(?:only\s+)?(?:the\s+)?(?:open|cheap|budget|nearest|closest)\s+ones?\s*\??$/.test(t) ||
    /^make\s+it\s+(?:cheaper|budget|affordable|closer|nearer)\s*$/.test(t) ||
    // Mall/venue type filter constraints
    /\b(?:inside|within|in|include)\s+(?:the|a|any)?\s*(?:mall|malls|shopping center|shopping centre|market)\b/i.test(t) ||
    /\b(?:only|include)\s+(?:inside|within|in)\b/i.test(t)
  );
}

function looksLikeExplicitRouteQuery(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  const raw = String(text || "").trim();
  const barePointToPoint =
    /^[\p{L}\p{N}][\p{L}\p{N}&'’.,()\/ -]{1,80}\s+to\s+[\p{L}\p{N}][\p{L}\p{N}&'’.,()\/ -]{1,80}$/u.test(raw) &&
    !/\b(how to|want to|need to|used to|going to|trying to)\b/i.test(t);

  // Worldwide-safe: a route question contains BOTH endpoints regardless of
  // order — "from A to B" or "to A from B" — and uses a movement verb
  // (get/go/walk/drive/reach/travel/commute/head). Without the reversed
  // "to A from B" arm, "How can I go to Cebu from Bohol" was falling
  // through to itinerary_planning because the existing arm only matched
  // "from .+ to .+" order.
  const movementVerbRx =
    /\bhow\s+(?:do|can|should|would|could|will)?\s*(?:i|we|you|one)\s+(?:walk|get|go|drive|reach|travel|commute|head|ride|bike|cycle)\s+(?:from|to)\b/i;
  const howToVerbRx =
    /\bhow\s+to\s+(?:walk|get|go|drive|reach|travel|commute|head|ride|bike|cycle)\s+(?:from|to)\b/i;
  const reverseEndpointsRx =
    /\bto\s+\p{L}[\p{L}\p{N}&'’.\- ]{1,60}\s+from\s+\p{L}[\p{L}\p{N}&'’.\- ]{1,60}\b/iu;
  const forwardEndpointsRx =
    /\bfrom\s+\p{L}[\p{L}\p{N}&'’.\- ]{1,60}\s+to\s+\p{L}[\p{L}\p{N}&'’.\- ]{1,60}\b/iu;
  const movementContext =
    movementVerbRx.test(t) ||
    howToVerbRx.test(t) ||
    /\b(?:how do i get there|how can i get there|how to get there|best way to (?:get|go|reach)|fastest way to (?:get|go|reach)|cheapest way to (?:get|go|reach)|route to|directions to)\b/i.test(t);

  return (
    /\b(how do i get to|how can i get to|how to get to|how to go to|how can i go to|how should i go to|how to reach|how can i reach|how do i reach|route to|directions to|go from .+ to .+|from .+ to .+|fastest way to|get from .+ to .+)\b/i.test(t) ||
    /\b(how do i get there from|how can i get there from|how to get there from)\b/i.test(t) ||
    /\b(i am|i'm|im)\s+at\s+.+\b(how do i get to|how can i get to|how to get to|how to go to|how can i go to|how to reach|fastest way to|cheapest way to)\b/i.test(t) ||
    /\b(?:i want to go to|i wanna go to|i plan to go to|im going to|i'm going to|travel to|head to|heading to)\s+.+\b(how do i get there|how can i get there|how to get there|best way to get there|cheapest way to get there|fastest way to get there)\b/i.test(t) ||
    (/\b(to|from)\b/i.test(t) && /\b(train|bus|subway|metro|taxi|grab|walk|walking|transit|route|directions|cheapest way|fastest way|best way|ferry|flight|plane|van|tricycle|jeepney|habal-?habal)\b/i.test(t)) ||
    // Walking / driving question with an explicit "from <Landmark>"
    // origin must be treated as a route question with a KNOWN origin
    // — do not demand device location. Example: "How do I walk from
    // Ayala Center Cebu to the nearest coffee shop?" — the origin is
    // "Ayala Center Cebu". We test against the RAW input (not the
    // lowercased intent text) because the landmark detector here
    // previously required an uppercase letter, which never matches
    // once normalizeIntentText has lowercased everything.
    (/\bfrom\s+\p{L}[\p{L}\p{N}&'’.\- ]{1,60}\s+to\b/iu.test(raw) &&
      /\b(walk|walking|walk to|walking to|drive|driving|drive to|driving to)\b/i.test(t)) ||
    // "How do I walk to X" / "how do I get to X" / "How can I go to X
    // from Y" / "How should I travel from Y to X" — route intent
    // regardless of verb (do/can/should/would) or endpoint order
    // (from→to vs to→from). The origin defaults to the user's carried
    // area when not stated explicitly.
    movementVerbRx.test(t) ||
    howToVerbRx.test(t) ||
    // Both endpoints present in EITHER order, paired with any movement
    // / transport / route signal, count as a route query — covers
    // "How can I go to Cebu from Bohol", "Bohol to Cebu fastest way",
    // "from Manila to Boracay via ferry", etc.
    ((forwardEndpointsRx.test(raw) || reverseEndpointsRx.test(raw)) && movementContext) ||
    barePointToPoint
  );
}

function looksLikeRouteFollowUp(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  return looksLikeRouteCostFollowUp(t) || /\b(how long|how long will it take|how long does it take|can i walk instead|walk instead|is walking okay|walking okay|best if i have luggage|better for luggage|with luggage|less walking|less stairs|fewer stairs|start from|leave at night|at night|easiest for first-time tourists|first-time tourists|easier for tourists|step by step|step-by-step|fastest|cheapest|best route|best way|which is easiest)\b/i.test(t);
}

function extractRouteEndpoints(text = "") {
  const raw = String(text || "").trim();
  if (!raw) return null;

  let m =
    raw.match(/\bfrom\s+(.+?)\s+to\s+(.+?)$/i) ||
    raw.match(/\bgo\s+from\s+(.+?)\s+to\s+(.+?)$/i) ||
    raw.match(/\bget\s+from\s+(.+?)\s+to\s+(.+?)$/i);

  if (m) {
    return {
      origin: String(m[1] || "").trim().replace(/[?.!]+$/, ""),
      destination: String(m[2] || "").trim().replace(/[?.!]+$/, ""),
    };
  }

  m = raw.match(/\b(?:i want to go to|i wanna go to|i plan to go to|im going to|i'm going to|travel to|head to|heading to)\s+(.+?)(?:\s*,?\s*(?:how do i get there|how can i get there|how to get there|best way to get there|cheapest way to get there|fastest way to get there)\b.*)?$/i);
  if (m) {
    return {
      origin: "",
      destination: String(m[1] || "")
        .trim()
        .replace(/[?.!]+$/, "")
        .replace(/\s+(instead|please)$/i, ""),
    };
  }

  m = raw.match(/\b(?:route to|directions to|how do i get to|how can i get to|how to get to|how to go to|how to reach)\s+(.+)$/i);
  if (m) {
    return {
      origin: "",
      destination: String(m[1] || "")
        .trim()
        .replace(/[?.!]+$/, "")
        .replace(/\s+(instead|please)$/i, ""),
    };
  }

  return null;
}

function extractLatestRouteContext(messages = []) {
  const userMessages = [...messages]
    .filter((m) => m?.role === "user")
    .map((m) => String(m?.content || "").trim())
    .filter(Boolean);

  for (let i = userMessages.length - 1; i >= 0; i--) {
    const content = userMessages[i];
    if (!looksLikeExplicitRouteQuery(content)) continue;

    const endpoints = extractRouteEndpoints(content) || {};
    return {
      query: content,
      origin: endpoints.origin || "",
      destination: endpoints.destination || "",
    };
  }

  return null;
}

function buildActiveRouteContext(lastUser = "", messages = []) {
  const current = String(lastUser || "").trim();
  const routeContext = extractLatestRouteContext(messages);

  if (!routeContext) return null;
  if (!looksLikeRouteFollowUp(current) && !looksLikeExplicitRouteQuery(current)) return null;

  const updated = { ...routeContext };
  const startOverride = current.match(/\bstart from\s+(.+?)(?:\s+instead)?(?:[?.!]|$)/i);
  if (startOverride) {
    updated.origin = String(startOverride[1] || "").trim().replace(/[?.!]+$/, "");
  }

  return updated;
}

function extractParenthesizedPlaceContext(text = "") {
  const raw = String(text || "").trim();
  if (!raw) return null;

  const m = raw.match(/^([^()]+?)\s*\(([^()]+)\)/);
  if (!m) return null;

  const label = String(m[1] || "").trim();
  const address = String(m[2] || "").trim();

  if (!label && !address) return null;

  return {
    label,
    address,
    anchorText: [label, address].filter(Boolean).join(", "),
  };
}

function normalizePlaceNameKey(value = "") {
  return String(value || "")
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function providerNameStronglyMatchesRequestedStop(place = {}, requestedLabel = "") {
  const requestedKey = normalizePlaceNameKey(requestedLabel);
  const providerKey = normalizePlaceNameKey([place?.name, place?.address].filter(Boolean).join(" "));
  const providerNameKey = normalizePlaceNameKey(place?.name || "");

  if (!requestedKey || !providerKey || !providerNameKey) return false;
  if (providerNameKey === requestedKey || providerNameKey.includes(requestedKey) || requestedKey.includes(providerNameKey)) {
    return true;
  }

  const requestedTokens = requestedKey.split(/\s+/).filter((token) => token.length >= 3);
  const providerTokens = new Set(providerKey.split(/\s+/).filter((token) => token.length >= 3));
  const matchedCount = requestedTokens.filter((token) => providerTokens.has(token)).length;

  if (BRAND_CONTAINS_RE.test(requestedLabel)) {
    return matchedCount >= Math.min(2, requestedTokens.length);
  }

  return matchedCount >= Math.max(2, Math.min(3, requestedTokens.length));
}

function extractClosedPlaceReportName(value = "") {
  const raw = String(value || "").trim();
  if (!raw) return "";

  const match =
    raw.match(/^(.+?)\s+(?:is|are|was|were)\s+(?:still\s+)?(?:permanently\s+)?closed\b/i) ||
    raw.match(/^(.+?)\s+(?:is|are|was|were)\s+closed\b/i);

  return match ? String(match[1] || "").trim().replace(/[?.!]+$/, "") : "";
}

function looksLikePlaceCorrectionMessage(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  return (
    /\b(this was the nearest|this is the nearest|the nearest is|this one is the nearest|this branch is the nearest)\b/i.test(t) ||
    /\b(no[, ]+i was informing you|no[, ]+im informing you|no[, ]+i am informing you|i was informing you|i meant|use this branch|this is the correct one|this was the correct one)\b/i.test(t)
  );
}

function looksLikeStandaloneAddress(text = "") {
  const raw = String(text || "").trim();
  if (!raw) return false;

  return (
    /\d{1,6}\s+[A-Za-z0-9 .'-]+(?:\s+(?:Rd|Road|St|Street|Ave|Avenue|Blvd|Boulevard|Dr|Drive|Hi-Way|Highway|N Rd|S Rd|E Rd|W Rd))\b/i.test(raw) ||
    /,\s*[A-Za-z .'-]+,\s*[A-Za-z .'-]+,\s*\d{4,6}\b/i.test(raw)
  );
}

function extractUserConfirmedPlaceCorrection(text = "", placesContext = null) {
  const raw = String(text || "").trim();
  if (!raw) return null;

  const selectedPlaceName = String(
    placesContext?.userConfirmedPlaceName ||
    placesContext?.selectedPlaceName ||
    (Array.isArray(placesContext?.latestDisplayedPlaceNames) && placesContext.latestDisplayedPlaceNames.length
      ? placesContext.latestDisplayedPlaceNames[0]
      : "") ||
    placesContext?.pendingSpecificPlaceName ||
    ""
  ).trim();

  if (looksLikeStandaloneAddress(raw)) {
    return {
      placeName: selectedPlaceName,
      address: raw.replace(/[?.!]+$/, "").trim(),
    };
  }

  const correctionWithAddress =
    raw.match(/\b(?:nearest|correct one|correct branch)\s*(?::|-)?\s*(.+)$/i) ||
    raw.match(/\buse this branch\s*(?::|-)?\s*(.+)$/i);

  if (correctionWithAddress && looksLikeStandaloneAddress(correctionWithAddress[1] || "")) {
    return {
      placeName: selectedPlaceName,
      address: String(correctionWithAddress[1] || "").trim().replace(/[?.!]+$/, ""),
    };
  }

  return null;
}

function buildDisputedPlaceKeySet(messages = [], appContext = {}) {
  const keys = new Set();
  const addName = (value = "") => {
    const key = normalizePlaceNameKey(value);
    if (key) keys.add(key);
  };

  for (const name of Array.isArray(appContext?.closedPlaceReports) ? appContext.closedPlaceReports : []) {
    addName(name);
  }

  for (const message of Array.isArray(messages) ? messages : []) {
    const content = String(message?.content || "").trim();
    if (!content) continue;

    if (message?.role === "user") {
      addName(extractClosedPlaceReportName(content));
      continue;
    }

    if (message?.role === "system") {
      const noteMatch = content.match(/previously reported these places as permanently closed:\s*(.+?)\.\s*Treat them as disputed/i);
      if (noteMatch) {
        String(noteMatch[1] || "")
          .split(/\s*,\s*/)
          .map((name) => String(name || "").trim())
          .filter(Boolean)
          .forEach(addName);
      }
    }
  }

  return keys;
}

function filterPlacesAgainstDisputedSet(places = [], disputedPlaceKeys = new Set()) {
  const source = Array.isArray(places) ? places : [];
  if (!disputedPlaceKeys || !disputedPlaceKeys.size) return source;

  return source.filter((place) => {
    const key = normalizePlaceNameKey(place?.name || "");
    return !key || !disputedPlaceKeys.has(key);
  });
}

function sanitizeUiLeakageReply(text = "") {
  const raw = String(text || "");
  if (!raw.trim()) return "";
  if (isProviderValidationFailureSentinel(raw)) return providerValidationFailureUserMessage();

  return raw
    .replace(/\bSwap in this nearby stop to keep the route varied;?\s*/gi, "")
    .replace(/\bSwap in this nearby stop to keep the day varied and practical\.?\s*/gi, "")
    .replace(/\bUse this provider-backed alternate stop to avoid repeating the same place\.?\s*/gi, "")
    .replace(/\bUse this provider-backed alternate stop\.?\s*/gi, "")
    .replace(/\bUse this as a nearby mappable stop(?:\s+with\s+a\s+short\s+visit)?[^.\n]*\.?\s*/gi, "")
    .replace(/\bnearby mappable stop\b/gi, "nearby stop")
    .replace(/\bmappable stops?\b/gi, "stops")
    .replace(/\bprovider-backed (?:alternate|replacement|filler|nearby)\s+stop\b/gi, "nearby stop")
    .replace(/\bprovider-backed alternate stop\b/gi, "nearby stop")
    .replace(/\b(?:alternate|replacement|filler)\s+stop\b/gi, "nearby stop")
    .replace(/\bduplicate repair\b/gi, "schedule adjustment")
    .replace(/\brepeated filler stops?\b/gi, "repeated stops")
    .replace(/\bkeep (?:the\s+)?route varied\b/gi, "keep the route fresh")
    .replace(/(?:^|\n)\s*Use\s+\*?\*?Save\s*\/\s*Edit\s*\/\s*Not now\*?\*?\s+(?:below|above)\s*(?=\n|$)/gi, "\n")
    .replace(/(?:^|\n)\s*\*?\*?Save\s*\/\s*Edit\s*\/\s*Not now\*?\*?\s*(?=\n|$)/gi, "\n")
    // Inline CTA leakage: "Use Save / Edit / Not now to..." or "Tap Save / Edit / Not now"
    .replace(/\bUse\s+\*?\*?Save\s*\/\s*Edit\s*\/\s*Not now\*?\*?\b[^.\n]*/gi, "")
    .replace(/\bTap\s+\*?\*?Save\s*\/\s*Edit\s*\/\s*Not now\*?\*?\b[^.\n]*/gi, "")
    .replace(/\*?\*?Save\s*\/\s*Edit\s*\/\s*Not now\*?\*?/gi, "")
    .replace(/(?:^|\n)\s*Save\s*(?=\n|$)/gm, "\n")
    .replace(/(?:^|\n)\s*Edit\s*(?=\n|$)/gm, "\n")
    .replace(/(?:^|\n)\s*Not now\s*(?=\n|$)/gm, "\n")
    .replace(/(?:^|\n)\s*(?:Coordinates?|Lat\/Lng|Latitude\/Longitude)\s*:\s*-?\d{1,3}\.\d+\s*,\s*-?\d{1,3}\.\d+\s*(?=\n|$)/gi, "\n")
    .replace(/(?:^|\n)\s*Latitude\s*:\s*-?\d{1,3}\.\d+\s*,?\s*Longitude\s*:\s*-?\d{1,3}\.\d+\s*(?=\n|$)/gi, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function parseDisplayedPlaceLine(line = "", options = {}) {
  const allowDashCandidate = Boolean(options.allowDashCandidate);
  const cleaned = String(line || "")
    .trim()
    .replace(/^(?:[-*]\s*|\d+[.)]\s*)/, "")
    .trim();

  if (!cleaned) return null;

  if (cleaned.includes("|")) {
    const parts = cleaned.split("|").map((part) => String(part || "").trim());
    if (!parts.length || !parts[0]) return null;

    const hasAddressColumn = parts.length >= 5;

    return {
      id: "",
      name: parts[0] || "",
      address: hasAddressColumn ? (parts[1] || "") : "",
      ratingText: hasAddressColumn ? (parts[2] || "") : (parts[1] || ""),
      priceRange: hasAddressColumn ? (parts[3] || "") : (parts[2] || ""),
      status: hasAddressColumn ? (parts[4] || "") : (parts[3] || ""),
      key: normalizePlaceNameKey(parts[0] || ""),
    };
  }

  if (allowDashCandidate) {
    const dashMatch = cleaned.match(/^(.+?)\s+—\s+(.+)$/);
    if (dashMatch) {
      const name = String(dashMatch[1] || "").trim();
      const address = String(dashMatch[2] || "").trim();
      if (!name) return null;

      return {
        id: "",
        name,
        address,
        ratingText: "",
        priceRange: "",
        status: "",
        key: normalizePlaceNameKey(name),
      };
    }
  }

  return null;
}

function extractDisplayedPlaceNamesFromReplyText(content = "") {
  const text = String(content || "");
  const allowDashCandidate = /\bI found multiple matches for\b/i.test(text);

  return text
    .split("\n")
    .map((line) => parseDisplayedPlaceLine(line, { allowDashCandidate }))
    .filter(Boolean)
    .map((item) => item.name)
    .filter(Boolean);
}

function collectDisplayedPlaceDataWithinFlow(messages = [], startUserIndex = 0) {
  const names = [];
  const nameMap = {};
  let userIndex = -1;

  for (const message of Array.isArray(messages) ? messages : []) {
    if (message?.role === "user") {
      userIndex += 1;
      continue;
    }

    if (message?.role !== "assistant") continue;
    if (userIndex < startUserIndex) continue;

    const displayedNames = extractDisplayedPlaceNamesFromReplyText(message?.content || "");
    for (const name of displayedNames) {
      const key = normalizePlaceNameKey(name);
      if (!key || nameMap[key]) continue;
      nameMap[key] = name;
      names.push(name);
    }
  }

  return { names, nameMap };
}

function extractLatestDisplayedPlaceNames(messages = []) {

  const assistantMessages = [...messages]
    .filter((m) => m?.role === "assistant")
    .map((m) => String(m?.content || ""))
    .filter(Boolean);

  for (let i = assistantMessages.length - 1; i >= 0; i--) {
    const lines = assistantMessages[i]
      .split("\n")
      .map((line) => String(line || "").trim())
      .filter(Boolean);

    const names = lines
      .filter((line) => line.includes("|"))
      .map((line) => line.split("|")[0]?.trim())
      .filter(Boolean);

    if (names.length) {
      return [...new Set(names.map(normalizePlaceNameKey).filter(Boolean))];
    }
  }

  return [];
}

function extractLatestDisplayedPlaceNameMap(messages = []) {
  const assistantMessages = [...messages]
    .filter((m) => m?.role === "assistant")
    .map((m) => String(m?.content || ""))
    .filter(Boolean);

  for (let i = assistantMessages.length - 1; i >= 0; i--) {
    const lines = assistantMessages[i]
      .split("\n")
      .map((line) => String(line || "").trim())
      .filter(Boolean);

    const names = lines
      .filter((line) => line.includes("|"))
      .map((line) => line.split("|")[0]?.trim())
      .filter(Boolean);

    if (names.length) {
      return names.reduce((acc, name) => {
        const key = normalizePlaceNameKey(name);
        if (key && !acc[key]) acc[key] = name;
        return acc;
      }, {});
    }
  }

  return {};
}

function extractLatestSelectedPlace(messages = []) {
  const assistantMessages = [...messages]
    .filter((m) => m?.role === "assistant")
    .map((m) => String(m?.content || "").trim())
    .filter(Boolean);

  for (let i = assistantMessages.length - 1; i >= 0; i--) {
    const content = assistantMessages[i];
    const lines = content.split("\n").map((line) => String(line || "").trim()).filter(Boolean);

    const tableNames = lines
      .filter((line) => line.includes("|"))
      .map((line) => line.split("|")[0]?.trim())
      .filter(Boolean);

    if (
      /\b(closest matching option|the closest|closest option|nearest option|best match|top pick|best option)\b/i.test(content) &&
      tableNames.length
    ) {
      return tableNames[0];
    }
  }

  return "";
}

async function hydratePlacesForDisplay(places = []) {
  return Array.isArray(places) ? places : [];
}

function extractLatestStructuredPlacesResults(messages = [], startUserIndex = 0) {
  let userIndex = -1;

  for (let i = (Array.isArray(messages) ? messages.length : 0) - 1; i >= 0; i--) {
    const message = messages[i];

    if (message?.role === "assistant") {
      if (userIndex < startUserIndex) continue;

      const content = String(message?.content || "");
      const allowDashCandidate = /\bI found multiple matches for\b/i.test(content);

      const lines = content
        .trim()
        .split("\n")
        .map((line) => String(line || "").trim())
        .filter(Boolean);

      if (!lines.length) continue;

      const parsed = lines
        .map((line) => parseDisplayedPlaceLine(line, { allowDashCandidate }))
        .filter(Boolean);

      if (parsed.length) {
        return parsed;
      }

      continue;
    }

    if (message?.role === "user") {
      userIndex -= 1;
    }
  }

  return [];
}

function buildPlacesQueryFromContext({ placeType = null, areaHint = "", anchorText = "", mode = "" } = {}) {
  const type = placeType?.type || "";
  const keyword = placeType?.keyword || "";
  const normalizedKeyword = String(keyword || "").trim().toLowerCase();

  const isCuisineRestaurantKeyword = [
    "chinese",
    "italian",
    "mexican",
    "indian",
    "thai",
    "french",
    "japanese",
    "vietnamese",
    "mediterranean",
    "american",
    "fusion",
    "soul food",
  ].includes(normalizedKeyword);

  const cuisineLabel = isCuisineRestaurantKeyword
    ? (
        normalizedKeyword === "soul food"
          ? "Soul food restaurants"
          : `${normalizedKeyword.charAt(0).toUpperCase()}${normalizedKeyword.slice(1)} restaurants`
      )
    : "";

  const searchLabel =
    type === "cafe"
      ? (keyword || "coffee shops")
      : type === "bakery"
      ? "bakeries"
      : type === "bar"
      ? "bars"
      : type === "convenience_store"
      ? (keyword || "convenience stores")
      : type === "pharmacy"
      ? "pharmacies"
      : type === "restaurant"
      ? (cuisineLabel || keyword || "restaurants")
      : type === "hotel"
      ? "hotels"
      : type === "hostel"
      ? "hostels"
      : "places";
  const modePart =
    mode === "24h"
      ? "open 24 hours"
      : mode === "late"
      ? "open late"
      : mode === "now"
      ? "open now"
      : "";

  const cleanArea = String(areaHint || "").trim();
  const cleanAnchor = String(anchorText || "").trim();

  // Suppress `near <cleanArea>` when the cleanArea text is actually a brand
  // or a self-location phrase (user typed the brand as their "area" by
  // accident). Uses the shared BRAND_CONTAINS_RE so all brand checks
  // stay in sync.
  const shouldSuppressLocationPart =
    /\b(near me|nearby|from here|close to me|around me)\b/i.test(cleanArea) ||
    BRAND_CONTAINS_RE.test(cleanArea);

  const locationPart = cleanAnchor
    ? `near ${cleanAnchor}`
    : cleanArea && !shouldSuppressLocationPart
    ? `near ${cleanArea}`
    : "";

  return [searchLabel, modePart, locationPart]
    .filter(Boolean)
    .join(" ")
    .replace(/\s+/g, " ")
    .trim();
}

function buildPlacesSearchLabel(placeType = null) {
  const type = placeType?.type || "";
  const keyword = String(placeType?.keyword || "").trim();
  const normalizedKeyword = keyword.toLowerCase();
  const cuisineLabel = [
    "chinese",
    "italian",
    "mexican",
    "indian",
    "thai",
    "french",
    "japanese",
    "vietnamese",
    "mediterranean",
    "american",
    "fusion",
    "soul food",
  ].includes(normalizedKeyword)
    ? (
        normalizedKeyword === "soul food"
          ? "Soul food restaurants"
          : `${normalizedKeyword.charAt(0).toUpperCase()}${normalizedKeyword.slice(1)} restaurants`
      )
    : "";

  return type === "cafe"
    ? (keyword || "coffee shops")
    : type === "bakery"
    ? "bakeries"
    : type === "bar"
    ? "bars"
    : type === "convenience_store"
    ? (keyword || "convenience stores")
    : type === "pharmacy"
    ? "pharmacies"
    : type === "restaurant"
    ? (cuisineLabel || keyword || "restaurants")
    : type === "hotel"
    ? "hotels"
    : type === "hostel"
    ? "hostels"
    : "places";
}

function isBareGenericPlacesQueryWithoutArea(text = "", locationContext = {}, placesContext = null) {
  const raw = String(text || "").trim();
  const normalized = normalizeIntentText(raw);
  if (!raw || !normalized) return false;

  if (!looksLikePlacesQuery(raw) && !looksLikeGenericLivePlacesSearch(raw)) {
    return false;
  }

  if (requiresExactLocationForPlacesQuery(raw)) {
    return false;
  }

  if (looksLikePlacesRefinementFollowUp(raw) || looksLikeAreaOnlyPlacesRefinement(raw)) {
    return false;
  }

  if (looksLikeSpecificPlaceOpenStatusQuery(raw, placesContext) || looksLikeNamedPlaceLookupQuery(raw, placesContext)) {
    return false;
  }

  const hasExplicitArea =
    Boolean(extractAreaHint(raw)) ||
    Boolean(extractParenthesizedPlaceContext(raw)?.anchorText);

  if (hasExplicitArea) {
    return false;
  }

  const hasTypedArea = Boolean(String(locationContext?.typedArea || "").trim());
  const hasSelectedPlaceAnchor = Boolean(
    String(
      locationContext?.selectedPlace?.anchorText ||
      locationContext?.selectedPlace?.label ||
      ""
    ).trim()
  );

  if (hasTypedArea || hasSelectedPlaceAnchor) {
    return false;
  }

  // If there is already an active places context with an area hint (e.g. from a prior
  // area-confirmation flow), do not re-ask for area — carry forward that context.
  const hasActivePlacesArea = Boolean(
    String(
      placesContext?.areaHint ||
      placesContext?.anchorLabel ||
      placesContext?.anchorText ||
      ""
    ).trim()
  );

  if (hasActivePlacesArea) {
    return false;
  }

  return /^(?:best\s+|top\s+|cheap\s+|affordable\s+|authentic\s+|high[- ]?rating\s+|highest[- ]?rated\s+|top[- ]?rated\s+|well[- ]?reviewed\s+|good\s+reviews\s+)?(?:coffee shops?|coffee|cafes?|restaurants?|hotels?|hostels?|baker(?:y|ies)|bars?|pharmacies?|convenience stores?|foods?|fast food|chinese(?: foods?)?|italian(?: foods?)?|mexican(?: foods?)?|indian(?: foods?)?|thai(?: foods?)?|french(?: foods?)?|japanese(?: foods?)?|vietnamese(?: foods?)?|mediterranean(?: foods?)?|american(?: foods?)?|fusion(?: foods?)?|soul food)(?:\s+open\s+24\s+hours|\s+24\s*hours?\s+open|\s+24\s*hours?|\s+24-hour|\s+24hr|\s+24\s+hrs?|\s+open\s+24\/7|\s+24\/7|\s+open\s+now|\s+currently\s+open|\s+open\s+late)?(?:\s+that\s+(?:has|have)\s+(?:high\s+rating|good\s+reviews))?$/i.test(
    normalized
  );
}

function buildGenericAreaQuestionReply(text = "") {
  const placeType = extractPlaceType(normalizeIntentText(text));
  const label = buildPlacesSearchLabel(placeType);

  // Generic prompt — no named cities. The previous version said "Cebu City,
  // Lapu-Lapu, or Mandaue" which privileged one region and confused users
  // anywhere else in the world. A city/district/landmark prompt works
  // globally without examples.
  return `Which area should I use so I can recommend ${label} properly?\n\nTell me a city, district, neighborhood, or landmark.`;
}

function distanceMetersBetweenCoords(a = null, b = null) {
  const lat1 = Number(a?.lat);
  const lng1 = Number(a?.lng);
  const lat2 = Number(b?.lat);
  const lng2 = Number(b?.lng);

  if (!Number.isFinite(lat1) || !Number.isFinite(lng1) || !Number.isFinite(lat2) || !Number.isFinite(lng2)) {
    return null;
  }

  const toRad = (deg) => (deg * Math.PI) / 180;
  const R = 6371000;

  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);

  const s1 = Math.sin(dLat / 2);
  const s2 = Math.sin(dLng / 2);

  const aa =
    s1 * s1 +
    Math.cos(toRad(lat1)) *
      Math.cos(toRad(lat2)) *
      s2 * s2;

  const c = 2 * Math.atan2(Math.sqrt(aa), Math.sqrt(1 - aa));
  return R * c;
}

function getLocalNearbyRadiusPlan({ queryText = "", anchorText = "", exactLocation = null } = {}) {
  const t = normalizeIntentText(queryText);

  const isVeryTightNearby =
    /\b(closest|nearest|walking distance|from here|near here|around here)\b/i.test(t);

  const isNearMeLike =
    /\b(near me|nearby|open now near me|open nearby)\b/i.test(t);

  const isBrandQuery = BRAND_CONTAINS_RE.test(t);

  if (anchorText) {
    return {
      primary: isVeryTightNearby ? 2000 : 3000,
      fallback: isVeryTightNearby ? 3000 : 4500,
    };
  }

  if (exactLocation) {
    if (isVeryTightNearby) {
      return { primary: 1500, fallback: 2500 };
    }

    if (isNearMeLike && isBrandQuery) {
      return { primary: 2200, fallback: 3200 };
    }

    if (isNearMeLike) {
      return { primary: 2500, fallback: 4000 };
    }

    return { primary: 3500, fallback: 5000 };
  }

  return {
    primary: 3500,
    fallback: 5000,
  };
}

function buildStructuredNearbyNoResultsReply({
  queryText = "",
  areaHint = "",
  anchorText = "",
  openNow = false,
  displayCount = 0,
} = {}) {
  const requestedCount =
    Number.isFinite(Number(displayCount)) && Number(displayCount) > 0
      ? Number(displayCount)
      : 3;

  const rawScopeLabel = String(anchorText || areaHint || "").trim();
  const normalizedScope = normalizeIntentText(rawScopeLabel);
  const normalizedQuery = normalizeIntentText(queryText);

  const scopeLooksLikeBrandLeak =
    BRAND_CONTAINS_RE.test(rawScopeLabel) &&
    /\b(near me|nearby|from here|close to me|around me)\b/i.test(rawScopeLabel);

  const scopeLabel =
    !rawScopeLabel ||
    ["me", "here", "to me", "near me", "nearby", "from here"].includes(normalizedScope) ||
    scopeLooksLikeBrandLeak
      ? (
          /\b(near me|nearby|from here|close to me|around me)\b/i.test(normalizedQuery)
            ? "your nearby area"
            : "the nearby area"
        )
      : rawScopeLabel;

  const countLabel = requestedCount === 1 ? "a matching place" : "matching places";

  if (openNow) {
    return `I couldn’t confirm ${countLabel} open now within ${scopeLabel}. Please verify current hours in Maps, widen the area slightly, or remove the open-now filter.`;
  }

  return `I couldn’t confirm ${countLabel} within ${scopeLabel}. Please widen the area slightly or try a different filter.`;
}

function extractLatestStatedUserArea(messages = []) {
  const userMsgs = [...messages]
    .filter((m) => m?.role === "user")
    .slice(-8)
    .reverse();
  // Allow optional intensifier words between the pronoun and the
  // preposition: "I'm actually in Paris", "I'm really in Cebu",
  // "I'm still in Davao", "I'm currently in Tokyo". Without this the
  // capture misses every message that isn't a plain "I'm in X".
  const STATE_RE =
    /\b(?:i[' ]?m|i am|im|currently|right now|based|staying)\s+(?:actually\s+|really\s+|still\s+|now\s+|currently\s+)?(?:in|at|near|around|staying in|staying at)\s+(\p{L}[\p{L}\p{M}\p{N}.' -]{2,60}?)(?=[.,!?]|$|\s+(?:right\s+now|now|today|tonight|currently)\b)/iu;
  const CATEGORY_WORDS =
    /\b(restaurant|restaurants|hotel|hotels|cafe|cafes|coffee|bar|bars|hostel|hostels|shop|shops|store|stores|mall|malls|market|markets|food)\b/i;
  // Reject fragments that are clearly not place names even when they
  // start with a letter. We no longer require an uppercase proper-noun
  // token because users frequently type city names in all lowercase
  // ("cebu city", "davao", "paris"). Instead we use an explicit
  // stopword list of English phrases that would slip past the letter
  // gate but aren't places.
  const STOPWORD_FRAGMENTS = new Set([
    "the airport", "the mall", "the city", "the area", "the house",
    "the hotel", "the office", "the building", "the park", "the beach",
    "the station", "the train", "the bus", "the car", "the plane",
    "trouble", "pain", "danger", "love", "a hurry", "a rush",
    "my hotel", "my room", "my house", "my office", "my car",
    "bed", "school", "class", "work", "town", "transit",
    "noon", "midnight", "morning", "afternoon", "evening", "night",
    "tonight", "today", "tomorrow", "yesterday",
  ]);
  // Reject captures where the first token is a pure English stopword
  // verb/preposition/determiner — these only appear here if the regex
  // over-captured into the sentence.
  const BAD_FIRST_TOKENS = new Set([
    "a", "an", "the", "this", "that", "these", "those",
    "my", "our", "your", "his", "her", "their",
    "any", "some", "every", "no",
    "is", "are", "was", "were", "be", "been",
    "to", "of", "for", "with", "without", "by",
  ]);
  for (const m of userMsgs) {
    const raw = String(m?.content || "");
    const match = raw.match(STATE_RE);
    if (match && match[1]) {
      const area = match[1].trim().replace(/\s+/g, " ");
      const lower = area.toLowerCase();
      const firstToken = lower.split(/\s+/)[0] || "";
      if (
        area &&
        area.length >= 3 &&
        !CATEGORY_WORDS.test(area) &&
        !STOPWORD_FRAGMENTS.has(lower) &&
        !BAD_FIRST_TOKENS.has(firstToken)
      ) {
        return area;
      }
    }
  }
  return "";
}

