function inferRegionCodeFromContext({
  statedChatArea = "",
  priorPlacesContextArea = "",
  locationContext = {},
  placesContext = null,
} = {}) {
  // Check all text sources from most recent to least recent.
  const candidates = [
    statedChatArea,
    priorPlacesContextArea,
    String(locationContext?.typedArea || ""),
    String(placesContext?.anchorAddress || ""),
    String(locationContext?.selectedPlace?.label || ""),
    String(locationContext?.selectedPlace?.address || ""),
  ].filter(Boolean);

  for (const text of candidates) {
    for (const hint of COUNTRY_HINTS) {
      if (hint.re.test(text)) return hint.code;
    }
  }
  return "";
}

async function resolveAnchorCenter(anchorText = "", options = {}) {
  const raw = String(anchorText || "").trim();
  if (!raw) return null;

  const regionCode = String(options?.regionCode || "").trim().toLowerCase();
  const requestedNameKey = normalizePlaceNameKey(raw.split(",")[0] || raw);

  try {
    const geocoded = await resolvePlaceAnchor(raw, { regionCode });
    if (geocoded && Number.isFinite(Number(geocoded.lat)) && Number.isFinite(Number(geocoded.lng))) {
      return {
        lat: Number(geocoded.lat),
        lng: Number(geocoded.lng),
        label: String(geocoded.label || "").trim(),
        address: String(geocoded.address || "").trim(),
      };
    }

    const candidates = await searchTextPlaces(raw, {
      textQuery: raw,
      openNow: false,
      maxResultCount: 5,
      useRawTextQuery: true,
      allowInferredType: false,
      includedType: "",
    });

    const ranked = [...(Array.isArray(candidates) ? candidates : [])]
      .filter((place) => Number.isFinite(Number(place?.location?.lat)) && Number.isFinite(Number(place?.location?.lng)))
      .sort((a, b) => {
        const aName = normalizePlaceNameKey(a?.name || "");
        const bName = normalizePlaceNameKey(b?.name || "");
        const aAddr = String(a?.address || "").toLowerCase();
        const bAddr = String(b?.address || "").toLowerCase();

        const aExact = aName === requestedNameKey ? 100 : aName.includes(requestedNameKey) ? 50 : 0;
        const bExact = bName === requestedNameKey ? 100 : bName.includes(requestedNameKey) ? 50 : 0;

        const aAddrBoost = aAddr.includes(String(raw).toLowerCase()) ? 10 : 0;
        const bAddrBoost = bAddr.includes(String(raw).toLowerCase()) ? 10 : 0;

        return (bExact + bAddrBoost) - (aExact + aAddrBoost);
      });

    const best = ranked[0] || null;
    if (!best?.location) return null;

    return {
      lat: Number(best.location.lat),
      lng: Number(best.location.lng),
      label: String(best.name || "").trim(),
      address: String(best.address || "").trim(),
    };
  } catch (e) {
    console.warn("[Places] resolveAnchorCenter failed:", String(e?.message || e || ""));
    return null;
  }
}

function extractLatestPlacesContext(messages = []) {
  const userMessages = [...messages]
    .filter((m) => m?.role === "user")
    .map((m) => String(m?.content || "").trim())
    .filter(Boolean);

  if (!userMessages.length) return null;

  let currentContext = null;
  let lastPlacesMessageIndex = -1;

  for (let _idx = 0; _idx < userMessages.length; _idx++) {
    const content = userMessages[_idx];
    const normalizedContent = normalizeIntentText(content);
    const parenthesized = extractParenthesizedPlaceContext(content);
    const isSpecificPlaceLookup =
      looksLikeSpecificPlaceOpenStatusQuery(content, currentContext) ||
      looksLikeNamedPlaceLookupQuery(content, currentContext);

    const isBareGenericCategorySearch =
      /^(?:best\s+|top\s+|cheap\s+|affordable\s+|authentic\s+|high[- ]?rating\s+|highest[- ]?rated\s+|top[- ]?rated\s+|well[- ]?reviewed\s+|good\s+reviews\s+)?(?:coffee shops?|coffee|cafes?|restaurants?|hotels?|hostels?|baker(?:y|ies)|bars?|pharmacies?|convenience stores?|foods?|fast food|chinese(?: foods?)?|italian(?: foods?)?|mexican(?: foods?)?|indian(?: foods?)?|thai(?: foods?)?|french(?: foods?)?|japanese(?: foods?)?|vietnamese(?: foods?)?|mediterranean(?: foods?)?|american(?: foods?)?|fusion(?: foods?)?|soul food)(?:\s+that\s+(?:has|have)\s+(?:high\s+rating|good\s+reviews))?$/i.test(
        normalizedContent
      );

    const isFreshPlacesQuery =
      !isSpecificPlaceLookup &&
      (
        looksLikePlacesQuery(content) ||
        looksLikeGenericLivePlacesSearch(content) ||
        isBareGenericCategorySearch ||
        Boolean(parenthesized)
      );

    if (isFreshPlacesQuery) {
      const requiresExactLocation = requiresExactLocationForPlacesQuery(content);
      const extractedAreaHint = extractAreaHint(content) || resolveNearThereTarget(content, messages);
      const nextPlaceType = extractPlaceType(normalizedContent || content);

      const shouldResetPlaceType =
        !parenthesized &&
        Boolean(currentContext) &&
        (
          normalizePlaceNameKey(buildPlacesSearchLabel(nextPlaceType)) !==
          normalizePlaceNameKey(buildPlacesSearchLabel(currentContext?.placeType || null))
        );

      // The stated AREA must survive a place-type change. When the user
      // says "I'm in Davao City" and asks for coffee shops, then follows
      // up with "Now show me restaurants open 24 hours", the place-type
      // flips (coffee → restaurants) but the AREA ("Davao City") must
      // carry forward. Previously, shouldResetPlaceType=true wiped the
      // area too, causing a geo-less text query that returned Singapore.
      const canCarryForwardSoftAreaOnly =
        !requiresExactLocation &&
        !parenthesized &&
        !extractedAreaHint &&
        Boolean(currentContext);

      const nextMode = wants24Hours(content)
        ? "24h"
        : wantsOpenLate(content)
        ? "late"
        : wantsOpenNow(content)
        ? "now"
        : "";

      const nextAnchorText = parenthesized?.anchorText || "";
      // Area inheritance priority:
      //   1. Area explicitly mentioned in THIS message.
      //   2. Area carried from previous places context (soft carry).
      //   3. Area carried from previous places context even across a
      //      place-type change (hard carry) — the user's stated location
      //      should not be erased just because they pivoted from coffee
      //      shops to restaurants.
      const carriedPriorArea = String(
        currentContext?.areaHint || currentContext?.anchorLabel || ""
      ).trim();
      const nextAreaHint =
        extractedAreaHint ||
        (canCarryForwardSoftAreaOnly ? currentContext.areaHint || "" : "") ||
        (!parenthesized && !requiresExactLocation ? carriedPriorArea : "");
      const nextAnchorLabel =
        parenthesized?.label ||
        (nextAnchorText
          ? ""
          : (
              extractedAreaHint ||
              (canCarryForwardSoftAreaOnly ? currentContext.anchorLabel || currentContext.areaHint || "" : "") ||
              (!requiresExactLocation ? carriedPriorArea : "")
            ));
      const nextAnchorAddress = parenthesized?.address || "";

      currentContext = {
        query:
          buildPlacesQueryFromContext({
            placeType: nextPlaceType,
            areaHint: nextAnchorText ? "" : nextAreaHint,
            anchorText: nextAnchorText,
            mode: nextMode,
          }) || content,
        areaHint: nextAreaHint,
        placeType: nextPlaceType,
        mode: nextMode,
        anchorText: nextAnchorText,
        anchorLabel: nextAnchorLabel,
        anchorAddress: nextAnchorAddress,
        resultsWindowStartUserIndex: _idx,
        requiresExactLocation,
        pendingSpecificPlaceName: "",
        userConfirmedPlaceName: "",
        userConfirmedPlaceAddress: "",
        selectedPlaceName: "",
        lastSpecificPlaceName: shouldResetPlaceType ? "" : (currentContext?.lastSpecificPlaceName || ""),
        lastSpecificPlaceAddress: shouldResetPlaceType ? "" : (currentContext?.lastSpecificPlaceAddress || ""),
        // Keep mall filtering neutral unless the user explicitly asks.
        mallPreference: extractMallPreference(content),
      };
      lastPlacesMessageIndex = _idx;
      continue;
    }

    if (isSpecificPlaceLookup) {
      const target = extractNamedPlaceLookupTarget(content, currentContext);
      const specificName = String(target.placeName || "").trim();
      if (specificName && !looksLikeCategoryTerm(specificName)) {
        currentContext = {
          ...(currentContext || {}),
          query: currentContext?.query || "",
          areaHint: currentContext?.areaHint || "",
          placeType: currentContext?.placeType || null,
          mode: currentContext?.mode || "",
          anchorText: currentContext?.anchorText || "",
          anchorLabel: currentContext?.anchorLabel || "",
          anchorAddress: currentContext?.anchorAddress || "",
          resultsWindowStartUserIndex:
            Number.isInteger(currentContext?.resultsWindowStartUserIndex)
              ? currentContext.resultsWindowStartUserIndex
              : _idx,
          requiresExactLocation: Boolean(currentContext?.requiresExactLocation),
          mallPreference: String(currentContext?.mallPreference || "").trim(),
          pendingSpecificPlaceName: specificName,
          lastSpecificPlaceName: specificName,
          lastSpecificPlaceAddress:
            String(target.areaHint || "").trim() ||
            currentContext?.userConfirmedPlaceAddress ||
            currentContext?.lastSpecificPlaceAddress ||
            "",
        };
        lastPlacesMessageIndex = _idx;
      }
      continue;
    }

    if (!currentContext) continue;

    const confirmedCorrection = extractUserConfirmedPlaceCorrection(content, currentContext);
    if (confirmedCorrection) {
      currentContext = {
        ...currentContext,
        userConfirmedPlaceName: String(confirmedCorrection.placeName || currentContext?.pendingSpecificPlaceName || "").trim(),
        userConfirmedPlaceAddress: String(confirmedCorrection.address || "").trim(),
        requiresExactLocation: Boolean(currentContext?.requiresExactLocation),
        mallPreference: String(currentContext?.mallPreference || "").trim(),
        lastSpecificPlaceName: String(confirmedCorrection.placeName || currentContext?.pendingSpecificPlaceName || currentContext?.lastSpecificPlaceName || "").trim(),
        lastSpecificPlaceAddress: String(confirmedCorrection.address || currentContext?.lastSpecificPlaceAddress || "").trim(),
      };
      lastPlacesMessageIndex = _idx;
      continue;
    }

    const startsNewNonPlacesTravelTopic =
      looksLikeAccommodationRecommendation(content) ||
      /\b(not the restaurant|name of the food|name of the dish|must[- ]?try\s+(?:food|dish)|what(?:'s| is)\s+the\s+must[- ]?try\s+(?:food|dish)|what(?:'s| is)\s+the\s+name\s+of\s+the\s+(?:food|dish)|what\s+(?:to|should i)\s+(?:bring|pack)|what\s+(?:should|do)\s+i\s+bring|stops?\s+recommendation)\b/i.test(
        content
      );

    if (
      looksLikeExplicitRouteQuery(content) ||
      looksLikeItineraryRequest(content) ||
      startsNewNonPlacesTravelTopic
    ) {
      currentContext = null;
      continue;
    }

    if (looksLikePlacesRefinementFollowUp(content) || looksLikeAreaOnlyPlacesRefinement(content)) {
      const nextParenthesized = extractParenthesizedPlaceContext(content);
      const wantsOutsideExpansion = /^(?:how about\s+|what about\s+)?outside\b/i.test(String(content || "").trim());
      const explicitAreaSwitchHint =
        wantsOutsideExpansion
          ? (extractAreaRefinementHint(content) || extractAreaHint(content) || "")
          : "";

      const nextAreaHint =
        wantsOutsideExpansion
          ? (explicitAreaSwitchHint || currentContext.areaHint || "")
          : (extractAreaRefinementHint(content) || extractAreaHint(content) || currentContext.areaHint || "");

      const hasExplicitPlaceType = messageHasExplicitPlaceType(content);

      const nextAnchorText =
        wantsOutsideExpansion
          ? ""
          : (nextParenthesized?.anchorText || currentContext.anchorText || "");

      const nextAnchorLabel =
        wantsOutsideExpansion
          ? ""
          : (nextParenthesized?.label || currentContext.anchorLabel || nextAreaHint);

      const nextAnchorAddress =
        wantsOutsideExpansion
          ? ""
          : (nextParenthesized?.address || currentContext.anchorAddress || "");

      const explicitMallPreference = extractMallPreference(content);
      const nextMallPreference = explicitMallPreference || currentContext.mallPreference || "";

      const preservesDisplayedResultsWindow =
        looksLikeShortContextualFollowUp(content) ||
        looksLikePlaceListSizeFollowUp(content) ||
        /\b(closest|nearest|which one is closest|which one is nearest|cheapest|lowest price|best value|how do i get there|how can i get there|how to get there|route there|directions there)\b/i.test(
          content
        );

      const nextResultsWindowStartUserIndex = preservesDisplayedResultsWindow
        ? (currentContext.resultsWindowStartUserIndex ?? _idx)
        : _idx;

      currentContext = {
        ...currentContext,
        query: buildPlacesQueryFromContext({
          placeType: hasExplicitPlaceType ? extractPlaceType(normalizeIntentText(content)) : currentContext.placeType,
          areaHint: nextAnchorText ? "" : nextAreaHint,
          anchorText: nextAnchorText,
          mode: wants24Hours(content)
            ? "24h"
            : wantsOpenLate(content)
            ? "late"
            : wantsOpenNow(content)
            ? "now"
            : currentContext.mode || "",
        }) || currentContext.query,
        areaHint: nextAreaHint,
        placeType: hasExplicitPlaceType ? extractPlaceType(normalizeIntentText(content)) : currentContext.placeType,
        mode: wants24Hours(content)
          ? "24h"
          : wantsOpenLate(content)
          ? "late"
          : wantsOpenNow(content)
          ? "now"
          : currentContext.mode || "",
        anchorText: nextAnchorText,
        anchorLabel: nextAnchorLabel,
        anchorAddress: nextAnchorAddress,
        requiresExactLocation:
          requiresExactLocationForPlacesQuery(content) ||
          (
            !nextAnchorText &&
            !nextAreaHint &&
            Boolean(currentContext?.requiresExactLocation)
          ),
        mallPreference: nextMallPreference,
        resultsWindowStartUserIndex: nextResultsWindowStartUserIndex,
      };
      lastPlacesMessageIndex = _idx;
    }
  }

  const STALENESS_WINDOW = 8;
  if (currentContext && lastPlacesMessageIndex >= 0) {
    const messagesSincePlaces = userMessages.length - 1 - lastPlacesMessageIndex;
    if (messagesSincePlaces > STALENESS_WINDOW) return null;
  }

  if (!currentContext) return null;

  const displayedPlaceData = collectDisplayedPlaceDataWithinFlow(
    messages,
    currentContext.resultsWindowStartUserIndex ?? 0
  );
  const assistantSpecificPlaceContext = extractLatestAssistantSpecificPlaceContext(
    messages,
    currentContext.resultsWindowStartUserIndex ?? 0
  );

  const confirmedSelectedPlaceName = String(
    currentContext?.userConfirmedPlaceName ||
    extractLatestSelectedPlace(messages) ||
    assistantSpecificPlaceContext.placeName ||
    ""
  ).trim();

  return {
    ...currentContext,
    selectedPlaceName: confirmedSelectedPlaceName,
    latestDisplayedPlaceNames: displayedPlaceData.names,
    latestDisplayedPlaceNameMap: displayedPlaceData.nameMap,
    lastStructuredPlacesResults: extractLatestStructuredPlacesResults(
      messages,
      currentContext.resultsWindowStartUserIndex ?? 0
    ),
    alreadyShownPlaceKeys: displayedPlaceData.names.map(normalizePlaceNameKey).filter(Boolean),
    userConfirmedPlaceName: String(currentContext?.userConfirmedPlaceName || "").trim(),
    userConfirmedPlaceAddress: String(currentContext?.userConfirmedPlaceAddress || "").trim(),
    lastSpecificPlaceName: String(
      currentContext?.userConfirmedPlaceName ||
      currentContext?.lastSpecificPlaceName ||
      assistantSpecificPlaceContext.placeName ||
      currentContext?.pendingSpecificPlaceName ||
      ""
    ).trim(),
    lastSpecificPlaceAddress: String(
      currentContext?.userConfirmedPlaceAddress ||
      currentContext?.lastSpecificPlaceAddress ||
      assistantSpecificPlaceContext.address ||
      ""
    ).trim(),
  };
}

function placeMatchesAreaFilter(place = {}, areaText = "") {
  const filter = String(areaText || "").trim().toLowerCase();
  if (!filter) return true;

  const normalizeText = (value = "") =>
    String(value || "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/gi, " ")
      .replace(/\s+/g, " ")
      .trim();

  const haystack = normalizeText(`${String(place?.name || "")} ${String(place?.address || "")}`);

  const phrases = filter
    .split(/[(),]/)
    .map((part) => normalizeText(part))
    .filter(Boolean);

  const primaryPhrase = phrases[0] || "";
  const primaryTokens = primaryPhrase
    .split(/\s+/)
    .map((token) => token.trim())
    .filter(
      (token) =>
        token.length >= 3 &&
        ![
          "area",
          "near",
          "only",
          "inside",
          "actually",
          "station",
          "city",
          "province",
          "country",
          "prefecture",
        ].includes(token)
    );

  if (primaryPhrase && phrases.length > 1) {
    if (haystack.includes(primaryPhrase)) return true;

    const primaryMatchedCount = primaryTokens.filter((token) => haystack.includes(token)).length;
    if (primaryMatchedCount >= Math.min(primaryTokens.length, 2)) return true;

    if (primaryTokens.length) return false;
  }

  const phraseMatch = phrases.some((phrase) => haystack.includes(phrase));
  if (phraseMatch) return true;

  const tokens = filter
    .split(/[^a-z0-9]+/i)
    .map((token) => token.trim())
    .filter(
      (token) =>
        token.length >= 3 &&
        ![
          "area",
          "near",
          "only",
          "inside",
          "actually",
          "station",
          "city",
          "province",
          "country",
          "prefecture",
        ].includes(token)
    );

  if (!tokens.length) {
    return haystack.includes(normalizeText(filter));
  }

  const matchedCount = tokens.filter((token) => haystack.includes(token)).length;
  return matchedCount >= Math.min(tokens.length, 2);
}

function extractMallPreference(text = "") {
  const raw = String(text || "").trim().toLowerCase();
  if (!raw) return "";

  if (/\b(?:outside\s+malls?|not\s+in\s+malls?|standalone)\b/i.test(raw)) {
    return "exclude";
  }

  if (
    /\b(?:only\s+inside\s+(?:the\s+)?malls?|inside\s+(?:the\s+)?mall\s+only|inside\s+malls?\s+only|mall\s+only|only\s+in\s+malls?)\b/i.test(raw)
  ) {
    return "only";
  }

  return "";
}

function isMallBasedPlace(place = {}) {
  const haystack = `${String(place?.name || "")} ${String(place?.address || "")}`.toLowerCase();
  if (!haystack.trim()) return false;

  // Structural mall-detection: any place whose name or address contains a
  // generic mall/shopping-center/plaza/arcade/outlet-mall term. Previously
  // this list also hardcoded PH mall brand names (Ayala Center, SM City,
  // Robinsons, Gaisano, Central Bloc, Market Market) which privileged one
  // region and missed every non-PH mall on Earth. The generic terms below
  // catch malls in any country — Dubai Mall, Westfield London, Galleria
  // Milano, Orchard Road mall, etc. — without a hardcoded list.
  return /\b(mall|shopping\s+(?:center|centre|mall|plaza|arcade)|galleria|outlet\s+mall)\b/i.test(haystack);
}

function applyMallPreferenceToPlaces(places = [], mallPreference = "") {
  if (!Array.isArray(places) || !places.length) return Array.isArray(places) ? places : [];

  // Neutral by default:
  // - no mallPreference => keep both mall and non-mall results
  // - "only" => strict mall-only
  // - "exclude" => exclude mall-based results
  if (mallPreference === "only") {
    return places.filter((place) => isMallBasedPlace(place));
  }

  if (mallPreference === "exclude") {
    return places.filter((place) => !isMallBasedPlace(place));
  }

  return places;
}

const HARD_DENY_NONFOOD_TYPES = new Set([
  "church",
  "mosque",
  "synagogue",
  "hindu_temple",
  "place_of_worship",
  "cemetery",
  "funeral_home",
  "park",
  "natural_feature",
  "tourist_attraction",
  "museum",
  "art_gallery",
  "library",
  "school",
  "primary_school",
  "secondary_school",
  "university",
  "hospital",
  "doctor",
  "dentist",
  "bank",
  "atm",
  "gym",
  "fitness_center",
  "stadium",
  "courthouse",
  "police",
  "fire_station",
  "post_office",
  "city_hall",
  "local_government_office",
  "embassy",
  "car_dealer",
  "car_repair",
  "car_rental",
  "car_wash",
  "gas_station",
  "parking",
  "real_estate_agency",
  "insurance_agency",
  "travel_agency",
  "beauty_salon",
  "hair_care",
  "spa",
  "laundry",
  "hardware_store",
  "electronics_store",
  "clothing_store",
  "furniture_store",
  "home_goods_store",
  "premise",
  "subpremise",
  "sublocality",
  "locality",
  "neighborhood",
  "route",
  "political",
]);

const FOOD_POSITIVE_TYPES = new Set([
  "restaurant",
  "food",
  "meal_takeaway",
  "meal_delivery",
  "fast_food_restaurant",
  "bakery",
  "bar",
  "cafe",
  "coffee_shop",
  "night_club",
  "pub",
  "ice_cream_shop",
]);

const LODGING_POSITIVE_TYPES = new Set([
  "lodging",
  "hotel",
  "resort_hotel",
  "motel",
  "inn",
  "guest_house",
  "bed_and_breakfast",
  "hostel",
  "campground",
]);

function placeMatchesRequestedType(place = {}, placeType = null) {
  const requestedType = String(placeType?.type || "").trim().toLowerCase();
  const requestedKeyword = String(placeType?.keyword || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/gi, " ")
    .replace(/\s+/g, " ")
    .trim();

  if (!requestedType) return true;

  const types = [
    String(place?.primaryType || "").trim().toLowerCase(),
    ...(Array.isArray(place?.types) ? place.types.map((v) => String(v || "").trim().toLowerCase()) : []),
  ].filter(Boolean);

  const text = `${String(place?.name || "")} ${String(place?.address || "")}`
    .toLowerCase()
    .replace(/[^a-z0-9]+/gi, " ")
    .replace(/\s+/g, " ")
    .trim();

  const compactText = text.replace(/\s+/g, "");
  const compactRequestedKeyword = requestedKeyword.replace(/\s+/g, "");

  const matchesRequestedKeyword = !requestedKeyword
    ? true
    : (
        text.includes(requestedKeyword) ||
        compactText.includes(compactRequestedKeyword)
      );

  // HARD DENY: for any food category, reject places whose primary/any type
  // is in the non-food deny list AND which have no positive food type.
  // This is what blocks churches, schools, parks, subdivisions, etc. from
  // ever appearing in a "restaurants" or "cafes" result set, regardless of
  // what the place name happens to contain.
  const FOOD_CATEGORIES = new Set([
    "restaurant",
    "cafe",
    "bakery",
    "bar",
    "convenience_store",
    "pharmacy",
  ]);
  if (FOOD_CATEGORIES.has(requestedType)) {
    const hasDenyType = types.some((t) => HARD_DENY_NONFOOD_TYPES.has(t));
    const hasFoodType = types.some((t) => FOOD_POSITIVE_TYPES.has(t));
    if (hasDenyType && !hasFoodType) return false;
  }
  if (requestedType === "hotel" || requestedType === "hostel") {
    const hasDenyType = types.some((t) => HARD_DENY_NONFOOD_TYPES.has(t));
    const hasLodgingType = types.some((t) => LODGING_POSITIVE_TYPES.has(t));
    if (hasDenyType && !hasLodgingType) return false;
  }

  if (requestedType === "cafe") {
    const hasCafeType = types.some((t) => /\b(cafe|coffee_shop|bakery)\b/.test(t));
    if (!hasCafeType) return false;
    return matchesRequestedKeyword;
  }

  if (requestedType === "restaurant") {
    const hasFoodType = types.some((t) =>
      /\b(restaurant|food|meal_takeaway|meal_delivery|fast_food_restaurant|bakery|bar)\b/.test(t)
    );
    if (!hasFoodType) return false;
    // Still exclude pure cafes unless they also carry a restaurant type.
    const isPureCafe =
      types.some((t) => /\b(cafe|coffee_shop)\b/.test(t)) &&
      !types.some((t) => /\brestaurant\b/.test(t));
    if (isPureCafe) return false;
    return matchesRequestedKeyword;
  }

  if (requestedType === "bakery") {
    const hasBakeryType = types.some((t) => /\bbakery\b/.test(t));
    if (!hasBakeryType) return false;
    return matchesRequestedKeyword;
  }

  if (requestedType === "bar") {
    const hasBarType = types.some((t) => /\b(bar|night_club|pub)\b/.test(t));
    if (!hasBarType) return false;
    return matchesRequestedKeyword;
  }

  if (requestedType === "convenience_store") {
    const hasConvType = types.some((t) => /\bconvenience_store\b/.test(t));
    if (!hasConvType) return false;
    return matchesRequestedKeyword;
  }

  if (requestedType === "pharmacy") {
    const hasPharmacyType = types.some((t) => /\b(pharmacy|drugstore)\b/.test(t));
    if (!hasPharmacyType) return false;
    return matchesRequestedKeyword;
  }

  if (requestedType === "hotel") {
    const hasHotelType = types.some((t) =>
      /\b(hotel|lodging|resort_hotel|motel|inn|guest_house|bed_and_breakfast)\b/.test(t)
    );
    if (!hasHotelType) return false;
    return matchesRequestedKeyword;
  }

  if (requestedType === "hostel") {
    const hasHostelType = types.some((t) => /\b(hostel|lodging|guest_house)\b/.test(t));
    if (!hasHostelType) return false;
    // For "hostel" specifically, also require the word "hostel" in name/address
    // OR an actual hostel type token, to avoid matching generic lodging.
    if (types.some((t) => /\bhostel\b/.test(t))) return matchesRequestedKeyword;
    return /\bhostel\b/.test(text) && matchesRequestedKeyword;
  }

  return false;
}

function extractLatestPriorExplicitPlaceType(messages = []) {
  const userMessages = [...messages]
    .filter((m) => m?.role === "user")
    .map((m) => String(m?.content || "").trim())
    .filter(Boolean);

  for (let i = userMessages.length - 1; i >= 0; i--) {
    const content = userMessages[i];

    if (messageHasExplicitPlaceType(content)) {
      return extractPlaceType(normalizeIntentText(content));
    }
  }

  return null;
}

function buildPlacesFollowUpQuery(lastUser = "", placesContext = null, messages = []) {
  const priorQuery = String(placesContext?.query || "").trim();
  const current = String(lastUser || "").trim();
  const normalizedCurrent = normalizeIntentText(current);
  const isAreaOnlyRefinement = looksLikeAreaOnlyPlacesRefinement(current);
  const isFreshPlacesQuery = looksLikePlacesQuery(current);
  const isFreshNearMeRequery =
    /^(?:how about|what about)\b/i.test(current) &&
    requiresExactLocationForPlacesQuery(current);

  const isPureTimeRefinementWithoutPlace =
    /^(?:how about\s+)?now\??$/i.test(current) ||
    /^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tomorrow|tonight)\??$/i.test(normalizedCurrent);

  const keepAsFollowUpRefinement =
    isAreaOnlyRefinement ||
    (
      /^(?:how about|what about)\b/i.test(current) &&
      !isFreshNearMeRequery &&
      !isPureTimeRefinementWithoutPlace
    );

  if (
    looksLikeAffirmativeFollowUp(current) ||
    looksLikeNegativeFollowUp(current) ||
    looksLikePlacesCapacityQuestion(current) ||
    looksLikeLocationDiscussionMessage(current) ||
    looksLikeSpecificPlaceOpenStatusQuery(current, placesContext) ||
    looksLikeNamedPlaceLookupQuery(current, placesContext) ||
    isPureTimeRefinementWithoutPlace
  ) {
    return null;
  }

  if (!priorQuery || (isFreshPlacesQuery && !keepAsFollowUpRefinement) || (!looksLikePlacesRefinementFollowUp(current) && !isAreaOnlyRefinement && !keepAsFollowUpRefinement)) return null;

const requestedCount = extractRequestedPlacesCount(current, 5);
  const shownNames = Array.isArray(placesContext?.latestDisplayedPlaceNames)
    ? placesContext.latestDisplayedPlaceNames
    : extractLatestDisplayedPlaceNames(messages);
  const latestDisplayedPlaceNameMap =
    placesContext?.latestDisplayedPlaceNameMap &&
    typeof placesContext.latestDisplayedPlaceNameMap === "object"
      ? placesContext.latestDisplayedPlaceNameMap
      : extractLatestDisplayedPlaceNameMap(messages);
  const selectedPlaceName =
    extractLatestSelectedPlace(messages) || placesContext?.selectedPlaceName || "";

  const hasExplicitPlaceType = messageHasExplicitPlaceType(current);

  const switchesTypeOnly = /\binstead\b/i.test(current) && hasExplicitPlaceType;

  const currentPlaceType = hasExplicitPlaceType
    ? extractPlaceType(normalizeIntentText(current))
    : extractPlaceType(current);

  const latestPriorExplicitPlaceType = extractLatestPriorExplicitPlaceType(messages);
  const contextPlaceType = placesContext?.placeType || null;
  const queryPlaceType = priorQuery ? extractPlaceType(priorQuery) : null;

  const normalizedTypeKey = (value = null) =>
    normalizePlaceNameKey(buildPlacesSearchLabel(value || null));

  const freshestExplicitPlaceType =
    latestPriorExplicitPlaceType?.type
      ? latestPriorExplicitPlaceType
      : null;

  const priorPlaceType =
    freshestExplicitPlaceType &&
    normalizedTypeKey(freshestExplicitPlaceType) &&
    normalizedTypeKey(freshestExplicitPlaceType) !== normalizedTypeKey(contextPlaceType)
      ? freshestExplicitPlaceType
      : contextPlaceType ||
        freshestExplicitPlaceType ||
        queryPlaceType;

  const placeType =
    (hasExplicitPlaceType || switchesTypeOnly) && currentPlaceType?.type
      ? currentPlaceType
      : priorPlaceType;

  const currentParenthesized = extractParenthesizedPlaceContext(current);
  const areaRefinementHint = extractAreaRefinementHint(current);
  const wantsOutsideExpansion = /^(?:how about\s+|what about\s+)?outside\b/i.test(current);
  const shouldUseCurrentParenthesizedAnchor =
    Boolean(currentParenthesized?.anchorText) && !areaRefinementHint && !wantsOutsideExpansion;

  const explicitAreaSwitchHint =
    wantsOutsideExpansion
      ? (areaRefinementHint || extractAreaHint(current) || "")
      : "";

  const anchorText =
    shouldUseCurrentParenthesizedAnchor
      ? currentParenthesized.anchorText
      : wantsOutsideExpansion
      ? ""
      : (placesContext?.anchorText || "");

  const anchorLabel =
    shouldUseCurrentParenthesizedAnchor
      ? (currentParenthesized?.label || "")
      : wantsOutsideExpansion
      ? ""
      : (placesContext?.anchorLabel || "");

  const anchorAddress =
    shouldUseCurrentParenthesizedAnchor
      ? (currentParenthesized?.address || "")
      : wantsOutsideExpansion
      ? ""
      : (placesContext?.anchorAddress || "");

  const isMallOrVenueConstraint =
    /\b(?:inside|within|in|include)\s+(?:the|a|any)?\s*(?:mall|malls|shopping center|shopping centre|market)\b/i.test(current) ||
    /\b(?:only|include)\s+(?:inside|within|in)\b/i.test(current);

  const currentAreaHint =
    wantsOutsideExpansion
      ? explicitAreaSwitchHint
      : isMallOrVenueConstraint
      ? (placesContext?.areaHint || "")
      : (
          areaRefinementHint ||
          (anchorText ? "" : (extractAreaHint(current) || placesContext?.areaHint || ""))
        );

  const mode = wants24Hours(current)
    ? "24h"
    : wantsOpenLate(current)
    ? "late"
    : wantsOpenNow(current)
    ? "now"
    : placesContext?.mode || "";

  const isClosestFollowUp =
    /\b(closest|nearest|which one is closest|which one is nearest|closest walk|closest walk from here|walk from here)\b/i.test(
      current
    );

  const wantsMoreContinuation =
    looksLikeShortContextualFollowUp(current) ||
    looksLikePlaceListSizeFollowUp(current) ||
    /\bmore\b/i.test(normalizeIntentText(current));

  const wantsStrictAreaContainment =
    isMallOrVenueConstraint ||
    /\b(which ones are actually in|actually in|inside|inside the area only)\b/i.test(current);

  const wantsCheapest =
    /\b(cheapest|cheaper|lowest price|best value)\b/i.test(current);

  const wantsRouteToSelectedPlace =
    selectedPlaceName &&
    /\b(how do i get there|how can i get there|how to get there|route there|directions there|how do i get there from|from .+ there)\b/i.test(current);

    const mallPreference =
      extractMallPreference(current) || String(placesContext?.mallPreference || "").trim();

    const query =
    buildPlacesQueryFromContext({
      placeType,
      areaHint: currentAreaHint,
      anchorText,
      mode,
    }) || priorQuery;

  const fetchCount =
    wantsMoreContinuation && shownNames.length
      ? Math.min(10, shownNames.length + requestedCount)
      : isClosestFollowUp || wantsCheapest
      ? Math.min(10, Math.max(5, requestedCount))
      : requestedCount;

  const freshQueryNeedsExactLocation = requiresExactLocationForPlacesQuery(current);
  const followUpRequiresExactLocation =
    freshQueryNeedsExactLocation ||
    (
      !looksLikePlacesQuery(current) &&
      Boolean(placesContext?.requiresExactLocation)
    );

  const softAreaHintForGenericQuery =
    !followUpRequiresExactLocation &&
    !extractAreaHint(query) &&
    !extractParenthesizedPlaceContext(query)
      ? String(
          currentAreaHint ||
          placesContext?.areaHint ||
          placesContext?.anchorLabel ||
          placesContext?.anchorAddress ||
          ""
        ).trim()
      : "";

  const finalQuery =
    softAreaHintForGenericQuery
      ? (
          buildPlacesQueryFromContext({
            placeType,
            areaHint: softAreaHintForGenericQuery,
            anchorText: "",
            mode,
          }) || query
        )
      : query;

  return {
    query: finalQuery,
    maxResultCount: fetchCount,
    requestedDisplayCount: isClosestFollowUp || wantsCheapest ? 1 : requestedCount,
    requiresExactLocation: followUpRequiresExactLocation,
    excludeNames: wantsMoreContinuation ? shownNames : [],
    constrainToNames: isClosestFollowUp ? shownNames : [],
    preferSingleClosest: isClosestFollowUp,
    preferCheapest: wantsCheapest,
    expandSearchBeyondArea: wantsOutsideExpansion,
    excludedAreaFilter: wantsOutsideExpansion ? explicitAreaSwitchHint : "",
    mallPreference,
    areaContainmentFilter:
      wantsOutsideExpansion
        ? ""
        : (
            wantsStrictAreaContainment
              ? (currentAreaHint || anchorLabel || anchorAddress || anchorText)
              : ""
          ),
    selectedPlaceName,
    selectedPlaceDisplayName:
      latestDisplayedPlaceNameMap[normalizePlaceNameKey(selectedPlaceName)] ||
      selectedPlaceName,
    routeToSelectedPlaceFrom: wantsRouteToSelectedPlace
      ? (
          /\bfrom here\b/i.test(current)
            ? (anchorText || currentAreaHint || placesContext?.anchorLabel || placesContext?.areaHint || "")
            : ((current.match(/\bfrom\s+(.+)$/i)?.[1] || "").trim().replace(/[?.!]+$/, ""))
        )
      : "",
  };
}

function hasRecentTravelContext(messages = []) {
  const recent = [...messages].slice(-6);

  return recent.some((m) => {
    const content = String(m?.content || "").trim();
    if (!content) return false;

    if (m.role === "user") {
      return looksTravel(content) || looksLikePlacesQuery(content) || looksLikeItineraryRequest(content);
    }

    if (m.role === "assistant") {
      return (
        isLikelyItineraryText(content) ||
        /\b(hotel|hostel|accommodation|accomodation|lodging|resort|guesthouse|inn|room|rooms|stay|beach|restaurant|cafe|route|terminal|airport|travel|trip|destination)\b/i.test(
          content
        )
      );
    }

    return false;
  });
}

function looksLikeTransportDetailFollowUp(text = "") {
  const t = String(text || "").trim();
  if (!t) return false;
  return /\b(?:transportation|transport|transfers?|how\s+to\s+get|how\s+do\s+we\s+get|how\s+can\s+we\s+get|how\s+to\s+go|how\s+to\s+get\s+around|getting\s+around|commute|fare|fares)\b/i.test(t);
}

function looksLikeActiveItineraryComplaint(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  return (
    /^(?:this|that|it|the itinerary|the plan|transportation|transport)?\s*(?:is\s+)?(?:so\s+)?(?:wrong|incorrect|not right|not correct|bad|off|mali|sayop)\s*[.!?]*$/.test(t) ||
    /\b(?:this is so wrong|that is so wrong|this is wrong|that is wrong|wrong itinerary|wrong plan|wrong route|wrong transportation|not based on the itinerary|base it on the itinerary|based it on itinerary|use the itinerary|follow the itinerary)\b/.test(t)
  );
}

function looksLikeTransportDetailFollowUp(text = "") {
  const t = String(text || "").trim();
  if (!t) return false;
  return /\b(?:transportation|transport|transfers?|how\s+to\s+get|how\s+do\s+we\s+get|how\s+can\s+we\s+get|how\s+to\s+go|how\s+to\s+get\s+around|getting\s+around|commute|fare|fares)\b/i.test(t);
}

function transportLegEstimate(prev = {}, next = {}, destination = "") {
  const combined = `${prev.place || ""} ${next.place || ""} ${destination || ""}`.toLowerCase();
  const prevText = String(prev.place || "").toLowerCase();
  const nextText = String(next.place || "").toLowerCase();

  if (/\bcebu\s+south\s+bus\s+terminal\b/.test(prevText) && /\b(?:moalboal\s+public\s+market|moalboal\s+bus\s+terminal|moalboal\s+town)\b/.test(nextText)) {
    return "Mode/route: Ceres bus or Cebu-Moalboal van from Cebu South Bus Terminal to Moalboal town/terminal; time: about 3-4.5 hours depending on traffic; cost: about ₱200-₱350 per person; tip: ask the conductor for Moalboal town or Panagsama drop-off options and keep small bills for the onward tricycle";
  }
  if (/\b(?:moalboal\s+public\s+market|moalboal\s+bus\s+terminal|moalboal\s+town)\b/.test(prevText) && /\bpanagsama\b/.test(nextText)) {
    return "Mode/route: tricycle or habal-habal from Moalboal town/terminal to Panagsama Beach; time: about 10-20 minutes; cost: about ₱50-₱150 per person or ₱150-₱250 private depending on luggage and negotiation; tip: agree on the fare before leaving the terminal/town area";
  }
  if (/\bpanagsama\b/.test(prevText) && /\bpescador\b/.test(nextText)) {
    return "Mode/route: island-hopping boat from the Panagsama launch area toward Pescador Island/viewpoint; time: about 15-30 minutes on the water plus boarding; cost: commonly about ₱500-₱1,500 per person depending on shared/private tour; tip: confirm inclusions, snorkel gear, and weather before paying";
  }
  if (/\bpescador\b/.test(prevText) && /\bpanagsama\b/.test(nextText)) {
    return "Mode/route: boat back to Panagsama, then walk or short tricycle along Panagsama Road; time: about 20-40 minutes including docking; cost: usually covered by the island tour plus about ₱20-₱80 for any short local ride; tip: keep dry clothes and cash ready after the boat leg";
  }
  if (/\b(?:moalboal|panagsama|backpacker\s+lodge)\b/.test(prevText) && /\bkawasan\b/.test(nextText)) {
    return "Mode/route: tricycle/habal-habal or bus via the Moalboal-Badian highway to Kawasan Falls; time: about 30-50 minutes; cost: about ₱50-₱200 per person depending on mode; tip: leave early and confirm whether canyoneering fees are separate";
  }
  if (/\bkawasan\b/.test(prevText) && /\bbadian\s+public\s+market\b/.test(nextText)) {
    return "Mode/route: tricycle or habal-habal from Kawasan Falls area to Badian Public Market; time: about 10-20 minutes; cost: about ₱20-₱100 per person; tip: use this as the nearest practical food/cash stop before heading back";
  }
  if (/\bbadian\s+public\s+market\b/.test(prevText) && /\b(?:panagsama|moalboal)\b/.test(nextText)) {
    return "Mode/route: bus/jeepney toward Moalboal plus tricycle to Panagsama, or direct habal-habal; time: about 45-75 minutes; cost: about ₱80-₱220 per person; tip: check the last return options before lingering in Badian";
  }
  if (/\b(?:panagsama|moalboal)\b/.test(prevText) && /\bsea\s+park\b/.test(nextText)) {
    return "Mode/route: short tricycle/habal-habal or walk if nearby; time: about 5-20 minutes; cost: about ₱0-₱100 per person; tip: pin the exact entrance because local drivers may know it by a nearby resort or landmark";
  }
  if (/\b(?:panagsama|moalboal)\b/.test(prevText) && /\bbackpacker\s+lodge\b/.test(nextText)) {
    return "Mode/route: walk, tricycle, or habal-habal from the Panagsama/Moalboal base to Moalboal Backpacker Lodge; time: about 5-15 minutes; cost: about ₱0-₱100 per person depending on exact distance; tip: confirm the lodge pin before riding because many budget stays have similar names";
  }
  if (/\b(?:moalboal|panagsama|backpacker\s+lodge|public\s+market)\b/.test(prevText) && /\bcebu\s+south\s+bus\s+terminal\b/.test(nextText)) {
    return "Mode/route: tricycle to Moalboal town/highway, then Ceres bus back to Cebu South Bus Terminal; time: about 3-4.5 hours; cost: about ₱220-₱350 per person including local ride; tip: build in traffic buffer when returning to Cebu City";
  }
  if (/\bcebu\s+south\s+bus\s+terminal\b/.test(prevText) && /\b(?:cebu\s+south\s+bus\s+terminal|afternoon\s+buffer|home|onward)\b/.test(nextText)) {
    return "Mode/route: onward taxi/Grab/jeepney from Cebu South Bus Terminal to your next Cebu stop or home; time: about 15-60 minutes depending on traffic; cost: about ₱15-₱300+ depending on mode and distance; tip: keep the afternoon buffer flexible for Cebu City traffic";
  }
  if (/\bmandaue\b/.test(prevText) && /\bhagnaya\b/.test(nextText)) {
    return "Mode/route: bus or van via Cebu North Bus Terminal to Hagnaya Port; time: about 3-4 hours; cost: about ₱250-₱400 per person; tip: leave early and keep ferry buffer";
  }
  if (/\bhagnaya\b/.test(prevText) && /\bsanta\s+fe\s+port\b/.test(nextText)) {
    return "Mode/route: ferry from Hagnaya Port to Santa Fe Port; time: about 1-1.5 hours plus boarding; cost: about ₱200-₱350 per person; tip: keep cash ready";
  }
  if (/\bsanta\s+fe\s+port\b/.test(prevText) && /\bhagnaya\b/.test(nextText)) {
    return "Mode/route: ferry from Santa Fe Port to Hagnaya Port; time: about 1-1.5 hours plus boarding; cost: about ₱200-₱350 per person; tip: confirm return schedules early";
  }
  if (/\bhagnaya\b/.test(prevText) && /\bmandaue\b/.test(nextText)) {
    return "Mode/route: bus or van from Hagnaya toward Cebu North/Mandaue; time: about 3-4 hours; cost: about ₱250-₱400 per person; tip: allow traffic buffer near Cebu";
  }
  if (/\bairport\b/.test(combined)) {
    return "Mode/route: airport transfer by shared van, shuttle, taxi, or arranged pickup depending on the destination; time: depends on flight arrival, baggage, queues, and road traffic; cost: varies by operator and distance; tip: keep a flight and luggage buffer before the next stop";
  }

  if (/\bport|pier|ferry|harbor|harbour|wharf|jetty\b/.test(combined)) {
    return "Mode/route: local transfer plus boat or ferry connection if needed; time: depends on boarding, weather, and queue conditions; cost: varies by operator and route; tip: confirm the return schedule before leaving the port area";
  }

  if (/\bterminal|station\b/.test(combined)) {
    return "Mode/route: bus, van, taxi, local shuttle, or short local ride depending on the route; time: depends on queues and traffic; cost: varies by operator and distance; tip: keep ticket and luggage buffer";
  }

  if (/\bisland\b/.test(combined)) {
    return "Mode/route: boat transfer or island-hopping boat arranged through a local operator; time: depends on sea conditions, boarding, and route order; cost: usually priced per shared tour or private boat; tip: confirm inclusions, weather, and return time before paying";
  }

  return "Mode/route: tricycle, habal-habal, local shuttle, walking, or arranged ride depending on distance and road access; time: usually about 10-35 minutes for nearby stops, longer for cross-town or rural routes; cost: confirm locally before riding; tip: agree on fare and pickup point first";
}

function getItinerarySearchableDestinationLabels(text = "") {
  const source = String(text || "").trim();
  if (!source) return [];

  const labels = new Set();

  const titleDestination =
    extractDestinationFromItineraryText(source) ||
    String(source.split("\n").find((line) => line.includes("•")) || "").split("•")[0].trim();

  if (titleDestination) labels.add(titleDestination);

  for (const label of ["Destination", "Hotel/base", "Base", "Accommodation"]) {
    const value = extractSummaryFieldValue(source, [label]);
    if (value) labels.add(value);
  }

  const baseLine = source
    .split("\n")
    .map((line) => String(line || "").trim())
    .find((line) => /^Base:/i.test(line));

  if (baseLine) {
    const baseValue = baseLine
      .replace(/^Base:\s*/i, "")
      .split("•")[0]
      .trim();

    if (baseValue) labels.add(baseValue);
  }

  return [...labels]
    .map((label) => String(label || "").trim())
    .filter(Boolean);
}

function requestedDestinationFromTransportQuestion(text = "", messages = []) {
  const source = String(text || "").trim();
  if (!source) return "";

  const explicitForMatch = source.match(/\bfor\s+(?:the\s+)?([a-zA-Z][a-zA-Z\s.'-]{2,80}?)(?:\s+(?:itinerary|trip|plan|transport|transportation)\b|[?.!]*$)/i);
  if (explicitForMatch?.[1]) {
    const candidate = explicitForMatch[1]
      .replace(/\b(?:detailed|transportation|transport|route|itinerary|trip|plan|please|provide|me|the|a|an|for)\b/gi, " ")
      .replace(/\s+/g, " ")
      .trim();

    if (candidate && candidate.length >= 3) return candidate;
  }

  const normalized = normalizeConstraintKey(source);
  const allMessages = Array.isArray(messages) ? messages : [];

  for (let i = allMessages.length - 1; i >= 0; i -= 1) {
    const message = allMessages[i];
    if (message?.role !== "assistant") continue;

    const content = String(message?.content || "").trim();
    if (!content || !isLikelyItineraryText(content)) continue;

    for (const label of getItinerarySearchableDestinationLabels(content)) {
      const key = normalizeConstraintKey(label);
      if (key && normalized.includes(key)) return label;
    }
  }

  return "";
}

function findLatestItineraryTextForDestination(messages = [], requestedDestination = "") {
  const wantedKey = normalizeConstraintKey(requestedDestination);
  if (!wantedKey) return "";

  const allMessages = Array.isArray(messages) ? messages : [];

  for (let i = allMessages.length - 1; i >= 0; i -= 1) {
    const message = allMessages[i];
    if (message?.role !== "assistant") continue;

    const content = String(message?.content || "").trim();
    if (!content || !isLikelyItineraryText(content)) continue;

    const labels = getItinerarySearchableDestinationLabels(content)
      .map((label) => normalizeConstraintKey(label))
      .filter(Boolean);

    if (
      labels.some((labelKey) =>
        labelKey === wantedKey ||
        labelKey.includes(wantedKey) ||
        wantedKey.includes(labelKey)
      )
    ) {
      return content;
    }
  }

  return "";
}

function buildTransportBreakdownForActiveItinerary(messages = [], itineraryContext = null, requestedDestination = "") {
  const requestedItinerary = requestedDestination
    ? findLatestItineraryTextForDestination(messages, requestedDestination)
    : "";

  const canonical = String(itineraryContext?.latestItinerary || "").trim();
  const visible = String(itineraryContext?.latestVisibleItinerary || "").trim();

  const visibleDays = countItineraryDays(visible);
  const canonicalDays = countItineraryDays(canonical);

  const active =
    requestedItinerary ||
    (
      visible &&
      (
        !canonical ||
        Number(itineraryContext?.latestVisibleItineraryIndex || -1) > Number(itineraryContext?.lastItineraryIndex || -1) ||
        visibleDays >= canonicalDays
      )
        ? visible
        : canonical
    );

  if (!active.trim()) return "";

  const activities = parseItineraryActivities(active);
  if (!activities.length) return "";

  const destination =
    extractDestinationFromItineraryText(active) ||
    String(active.split("\n").find((line) => line.includes("•")) || "").split("•")[0].trim() ||
    "the active itinerary";
  const confirmedDetails = buildConfirmedTripDetailsForValidation(messages);
  const activeOrigin =
    extractSummaryFieldValue(active, ["Origin", "Starting point"]) ||
    "";
  const rawActiveBase =
    extractSummaryFieldValue(active, ["Hotel/base", "Base", "Accommodation"]) ||
    String(
      active
        .split("\n")
        .map((line) => String(line || "").trim())
        .find((line) => /^Base:/i.test(line)) || ""
    )
      .replace(/^Base:\s*/i, "")
      .trim();

  const activeBase = String(rawActiveBase || "")
    .split("•")[0]
    .replace(/\s+Style:\s*.*$/i, "")
    .replace(/\s+Budget:\s*.*$/i, "")
    .trim();

  const originLabel =
    String(activeOrigin || "").trim() ||
    String(confirmedDetails.origin || "").trim() ||
    "Trip starting point";

  const baseLabel =
    String(activeBase || "").trim() ||
    String(confirmedDetails.baseArea || "").trim() ||
    destination;

  const conversationText = Array.isArray(messages)
    ? messages.map((m) => String(m?.content || "")).join("\n")
    : "";
  const isSantaFeBantayan =
    /\b(?:santa\s+fe|bantayan|kota\s+beach|sugar\s+beach|ogtong|hagnaya)\b/i.test(`${active}\n${conversationText}`);
  const startsFromMandaue = /\bmandaue\b/i.test(conversationText);

  const byDay = new Map();
  for (const activity of activities) {
    const day = Number(activity.day || 0);
    if (!day) continue;
    if (!byDay.has(day)) byDay.set(day, []);
    byDay.get(day).push(activity);
  }

  const lines = [`Transportation plan for ${destination}`];

  if (isSantaFeBantayan && startsFromMandaue) {
    lines.push(
      "",
      "Main transfer route",
      "- Mandaue → Cebu North Bus Terminal: taxi/Grab or jeepney, roughly 20–45 minutes depending on traffic.",
      "- Cebu North Bus Terminal → Hagnaya Port: bus or van, roughly 3–4 hours, about ₱250–₱400 per person.",
      "- Hagnaya Port → Santa Fe Port: ferry, roughly 1–1.5 hours plus boarding time, about ₱200–₱350 per person.",
      "- Santa Fe Port → Santa Fe town/beach area: tricycle, roughly 5–15 minutes; agree on the fare before riding."
    );
  }

  for (const [day, dayActivities] of [...byDay.entries()].sort((a, b) => a[0] - b[0])) {
    lines.push("", `Day ${day}`);
    const first = dayActivities[0];
    if (first?.place) {
      const startAnchor = day === 1 ? originLabel : baseLabel;
      if (startAnchor && !normalizeConstraintKey(first.place).includes(normalizeConstraintKey(startAnchor))) {
        lines.push(`- ${startAnchor} → ${first.place}: ${transportLegEstimate({ place: startAnchor }, first, destination)}`);
      }
    }
    if (dayActivities.length < 2) {
      const only = first;
      if (only) {
        lines.push(`- ${only.start} ${only.place}: no inter-stop transfer in the saved itinerary; keep this as a relaxed stop.`);
      }
      continue;
    }
    for (let i = 0; i < dayActivities.length - 1; i += 1) {
      const prev = dayActivities[i];
      const next = dayActivities[i + 1];
      const time = prev.end || next.start || prev.start;
      lines.push(
        `- ${time} ${prev.place} → ${next.place}: ${transportLegEstimate(prev, next, destination)}`
      );
    }
  }

  if (isSantaFeBantayan && startsFromMandaue) {
    lines.push(
      "",
      "Return route",
      "- Santa Fe Port → Hagnaya Port: ferry, roughly 1–1.5 hours plus boarding time.",
      "- Hagnaya Port → Cebu North Bus Terminal / Mandaue: bus or van, roughly 3–4 hours; add traffic buffer near Cebu."
    );
  }

  return lines.join("\n").trim();
}

function transportBreakdownEndsWithBareDayHeading(replyText = "") {
  const text = String(replyText || "").trim();
  return /(?:^|\n)\s*(?:#{1,4}\s*)?Day\s+\d{1,2}\s*[:—-]?\s*$/i.test(text);
}

function isCompleteTransportBreakdownForActiveItinerary(activeItinerary = "", replyText = "") {
  const reply = String(replyText || "").trim();
  if (!reply) return false;
  if (transportBreakdownEndsWithBareDayHeading(reply)) return false;

  const expectedDays = extractItineraryDayNumbers(activeItinerary);
  if (!expectedDays.length) return true;

  const actualDays = extractItineraryDayNumbers(reply);
  return expectedDays.every((day) => actualDays.includes(day));
}

function looksLikeRemoveStopEditRequest(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;
  return /\b(?:remove|delete|take\s+out|drop|omit|skip|leave\s+out)\b/.test(t) &&
    (
      /\b(?:airport|flight|stop|activity|place|itinerary|day\s*\d+|schedule)\b/.test(t) ||
      /\d{1,2}:\d{2}\s*[–—-]\s*\d{1,2}:\d{2}/.test(String(text || ""))
    );
}

function buildRemoveStopEditReplyFromActiveItinerary(activeItinerary = "", userText = "", messages = []) {
  const raw = String(userText || "").trim();
  const itinerary = String(activeItinerary || "").trim();
  if (!raw || !itinerary || !looksLikeRemoveStopEditRequest(raw)) return "";

  const split = splitReplyAndMapBlock(itinerary);
  const prose = String(split.prose || "").trim();
  if (!prose) return "";

  const removeAirport =
    /\b(?:airport|mactan|return\s+flight|check[-\s]?in|departure)\b/i.test(raw) ||
    localTripShouldNeverUseAirport(prose, messages);

  const timeMatch = raw.match(/(\d{1,2}:\d{2})\s*[–—-]\s*(\d{1,2}:\d{2})/);
  const requestedStart = timeMatch ? timeMatch[1] : "";
  const requestedEnd = timeMatch ? timeMatch[2] : "";

  const afterTime = timeMatch
    ? raw.slice(raw.indexOf(timeMatch[0]) + timeMatch[0].length)
    : raw;

  const requestedPlace = afterTime
    .replace(/[—-].*$/s, "")
    .replace(/\b(?:remove|delete|take\s+out|drop|omit|skip|leave\s+out)\b/ig, "")
    .replace(/\b(?:from|on|in|the|my|our|itinerary|trip|plan|schedule|stop|activity)\b/ig, " ")
    .replace(/[^\p{L}\p{N}\s.'-]/gu, " ")
    .replace(/\s+/g, " ")
    .trim();

  const requestedKey = normalizeConstraintKey(requestedPlace);
  const lines = prose.split(/\r?\n/);
  const kept = [];
  const removedLabels = [];

  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    const trimmed = String(line || "").trim();

    const combined = trimmed.match(/^(\d{1,2}:\d{2})[–—-](\d{1,2}:\d{2})\s*-\s*([^\n—]+?)(?:\s+—\s+(.+))?$/);
    if (combined) {
      const label = String(combined[3] || "").trim();
      const note = String(combined[4] || "").trim();
      const labelKey = normalizeConstraintKey(`${label} ${note}`);
      const timeMatches = !requestedStart || (combined[1] === requestedStart && combined[2] === requestedEnd);
      const airportMatches = removeAirport && (AIRPORT_OR_INTERCITY_TERMINAL_RX.test(`${label} ${note}`) || RETURN_FLIGHT_INTENT_RX.test(`${label} ${note}`));
      const placeMatches = requestedKey && labelKey.includes(requestedKey);

      if (timeMatches && (airportMatches || placeMatches)) {
        removedLabels.push(label);
        continue;
      }
    }

    const timeOnly = trimmed.match(/^(\d{1,2}:\d{2})[–—-](\d{1,2}:\d{2})$/);
    if (timeOnly && i + 1 < lines.length) {
      const nextLine = String(lines[i + 1] || "").trim();
      const labelText = nextLine.replace(/\s+—\s+.*$/s, "").trim();
      const nextKey = normalizeConstraintKey(nextLine);
      const timeMatches = !requestedStart || (timeOnly[1] === requestedStart && timeOnly[2] === requestedEnd);
      const airportMatches = removeAirport && (AIRPORT_OR_INTERCITY_TERMINAL_RX.test(nextLine) || RETURN_FLIGHT_INTENT_RX.test(nextLine));
      const placeMatches = requestedKey && nextKey.includes(requestedKey);

      if (timeMatches && (airportMatches || placeMatches)) {
        removedLabels.push(labelText || nextLine);
        i += 1;
        continue;
      }
    }

    kept.push(line);
  }

  if (!removedLabels.length) return "";

  let cleaned = kept.join("\n").replace(/\n{3,}/g, "\n\n").trim();
  cleaned = stripAirportFromLocalTripItinerary(cleaned, messages);
  cleaned = stripWeakFillerStops(cleaned);

  const removedText = [...new Set(removedLabels)].join(", ");
  return [
    `Updated — I removed ${removedText} from the itinerary.`,
    "",
    cleaned,
  ].join("\n").trim();
}

async function answerItineraryFollowUpDirectly({
  client,
  model,
  messages = [],
  lastUser = "",
  appContext = {},
  continuity = {},
  intent = null,
} = {}) {
  const itineraryContext = continuity?.itineraryContext || {};
  const isTransportFollowUp = looksLikeTransportDetailFollowUp(lastUser);
  const requestedTransportDestination = isTransportFollowUp
    ? requestedDestinationFromTransportQuestion(lastUser, messages)
    : "";

  const requestedTransportItinerary = requestedTransportDestination
    ? findLatestItineraryTextForDestination(messages, requestedTransportDestination)
    : "";

  const activeItinerary = String(
    requestedTransportItinerary ||
    itineraryContext.activeItineraryText ||
    itineraryContext.latestItinerary ||
    itineraryContext.latestVisibleItinerary ||
    ""
  ).trim();

  if (!activeItinerary) return "";

  const directRemoveEdit = buildRemoveStopEditReplyFromActiveItinerary(activeItinerary, lastUser, messages);
  if (directRemoveEdit) return directRemoveEdit;

  if (isTransportFollowUp) {
    const deterministic = buildTransportBreakdownForActiveItinerary(
      messages,
      itineraryContext,
      requestedTransportDestination
    );
    if (isCompleteTransportBreakdownForActiveItinerary(activeItinerary, deterministic)) {
      return deterministic;
    }
  }

  const systemContent =
    "You are TravelMate. The user has an active itinerary and is asking a focused follow-up question " +
    "(transport, cost, timing, hours, alternatives, or clarification). " +
    "Answer only that question unless the user asks to see the full, current, latest, or updated itinerary; in that case, present the active itinerary from the supplied context. Do not add MAP_STOPS_JSON. " +
    "Do not add a 'Would you like to save this itinerary?' line. Do not restart intake or ask for destination, base, dates, travelers, or budget. " +
    "Use the active itinerary as the source of truth. If the question is about transport, give per-leg detail for every itinerary day: mode, route, approximate time, approximate cost in ₱, and one practical tip. Do not stop at a bare day heading; if the itinerary has Day 1 through Day 3, the answer must include Day 1, Day 2, and Day 3. " +
    "If the answer is not present in the active itinerary, say that plainly and offer the most useful next step. Vary the wording naturally; do not use fixed closing lines.";

  const userContent = [
    `Active itinerary (do not repeat in full):\n${splitReplyAndMapBlock(activeItinerary).prose}`,
    "",
    `User question: ${lastUser}`,
    "",
    `Classifier intent: ${intent?.intent || ""}`,
    `Classifier rationale: ${intent?.rationale || ""}`,
    `Timezone: ${String(appContext?.timezone || "").trim() || "UTC"}`,
  ].join("\n");

  try {
    const reply = await callChatCompletion(client, {
      model,
      messages: [
        { role: "system", content: systemContent },
        { role: "user", content: userContent },
      ],
      temperature: 0.4,
      max_completion_tokens: isTransportFollowUp ? 1800 : 900,
    });
    const cleanReply = sanitizeUiLeakageReply(splitReplyAndMapBlock(reply).prose).trim();
    if (
      isTransportFollowUp &&
      !isCompleteTransportBreakdownForActiveItinerary(activeItinerary, cleanReply)
    ) {
      const deterministic = buildTransportBreakdownForActiveItinerary(
        messages,
        itineraryContext,
        requestedTransportDestination
      );
      if (deterministic) return deterministic;
    }
    return cleanReply;
  } catch (err) {
    console.warn("[llm.service] answerItineraryFollowUpDirectly failed", {
      err: String(err?.message || err || ""),
    });
    return "";
  }
}

function looksLikeTripSummaryFormattingRequest(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;
  return /\b(?:trip\s+summary|summary)\b/.test(t) &&
    /\b(?:bullet|bulleted|format|reformat|cleaner|clean version|hard to read|not bullet form|not bulleted|again)\b/.test(t);
}

function buildBulletedTripSummaryFromActiveItinerary(activeItinerary = "") {
  const prose = splitReplyAndMapBlock(activeItinerary).prose;
  const lines = prose.split("\n").map((line) => String(line || "").trim()).filter(Boolean);
  if (lines.length < 3) return "";
  const header = lines[0] || "";
  const dates = (lines.find((line) => /^Trip dates:/i.test(line)) || "").replace(/^Trip dates:\s*/i, "");
  const baseLine = lines.find((line) => /^Base:/i.test(line)) || "";
  const baseMatch = baseLine.match(/^Base:\s+(.+?)\s+•\s+Style:\s+(.+?)\s+•\s+Budget:\s+(.+)$/i);
  const destination = header.split("•")[0]?.trim() || "";
  const dayEntries = [];
  const parsed = _parseProseByDay(prose);
  for (const [day, entry] of [...parsed.days.entries()].sort((a, b) => a[0] - b[0])) {
    const labels = (entry.activities || [])
      .map((activity) => String(activity.label || "").trim())
      .filter(Boolean)
      .slice(0, 4);
    if (labels.length) dayEntries.push(`- **Day ${day}:** ${labels.join(" → ")}`);
  }
  return [
    "**Trip summary:**",
    destination ? `- **Destination:** ${destination}` : "",
    dates ? `- **Trip dates:** ${dates}` : "",
    dayEntries.length ? `- **Duration:** ${dayEntries.length} day${dayEntries.length === 1 ? "" : "s"}` : "",
    baseMatch?.[1] ? `- **Hotel/base:** ${baseMatch[1].trim()}` : "",
    baseMatch?.[2] ? `- **Style:** ${baseMatch[2].trim()}` : "",
    baseMatch?.[3] ? `- **Budget:** ${baseMatch[3].trim()}` : "",
    ...dayEntries,
  ].filter(Boolean).join("\n");
}

function looksLikeFullItineraryFollowUpRequest(text = "") {
  const t = normalizeIntentText(text);
  if (!t) return false;

  if (
    /\b(whole|full|entire|complete|current|updated)\b/.test(t) &&
    /\b(itinerary|trip|plan|schedule)\b/.test(t)
  ) {
    return true;
  }

  if (
    /\b(show|give|provide|send|return|rebuild)\b/.test(t) &&
    /\b(whole|full|entire|complete|current|updated)\b/.test(t) &&
    /\b(itinerary|trip|plan|schedule)\b/.test(t)
  ) {
    return true;
  }

  if (
    /\bagain\b/.test(t) &&
    /\b(itinerary|trip|plan|schedule)\b/.test(t) &&
    /\b(show|give|provide|send|return|rebuild)\b/.test(t)
  ) {
    return true;
  }

  if (/^(start|continue|go ahead with|proceed with)\s+(the\s+)?(itinerary|trip|plan|schedule)$/i.test(t)) {
    return true;
  }

  // Match "a full itinerary" with inline stop instructions like
  // "a full itinerary, sugbo mercado dinner and tops lookout last stop"
  if (/\b(?:a\s+)?full\s+itinerary\b/.test(t)) {
    return true;
  }

  // Match "create/make/build a full/complete itinerary"
  if (
    /\b(create|make|build|generate)\b/.test(t) &&
    /\b(full|complete|entire)\b/.test(t) &&
    /\b(itinerary|plan|schedule)\b/.test(t)
  ) {
    return true;
  }

  return false;
}

function countItineraryDays(text = "") {
  const prose = splitReplyAndMapBlock(text).prose;
  const matches = prose.match(/(^|\n)Day\s+(\d+)\s+—\s+[A-Za-z]{3}\s+\d{1,2}(?:\s+\(Today\))?\b/gm) || [];
  const dayNumbers = new Set();

  for (const match of matches) {
    const m = String(match || "").match(/Day\s+(\d+)/i);
    const day = m ? Number(m[1]) : 0;
    if (day) dayNumbers.add(day);
  }

  return dayNumbers.size;
}

function getItineraryDayBlockLines(prose = "", day = null) {
  const dayNum = Number(day) || 0;
  if (!dayNum) return [];

  const lines = String(prose || "").split("\n");
  let start = -1;
  let end = lines.length;
  for (let i = 0; i < lines.length; i += 1) {
    const trimmed = String(lines[i] || "").trim();
    if (new RegExp(`^Day\\s+${dayNum}\\s+—`, "i").test(trimmed)) {
      start = i;
      break;
    }
  }
  if (start < 0) return [];

  for (let i = start + 1; i < lines.length; i += 1) {
    if (/^Day\s+\d+\s+—/i.test(String(lines[i] || "").trim())) {
      end = i;
      break;
    }
  }

  const block = lines.slice(start, end);
  while (block.length && !String(block[block.length - 1] || "").trim()) block.pop();
  return block;
}

function trimEditedDayBlockForMerge(lines = []) {
  const kept = [];
  for (const line of lines) {
    const trimmed = String(line || "").trim();
    if (!trimmed && !kept.length) continue;
    if (/^---\s*$/.test(trimmed)) break;
    if (/^<{3}MAP_STOPS_JSON>{3}/i.test(trimmed)) break;
    if (/^(?:##\s*)?(?:Estimated Budget|Budget hotel suggestions|Hotel suggestions)\b/i.test(trimmed)) break;
    if (/\b(?:Would you like another detail|Would you like to save this itinerary|Should I update the itinerary)\b/i.test(trimmed)) break;
    kept.push(line);
  }
  while (kept.length && !String(kept[kept.length - 1] || "").trim()) kept.pop();
  return kept;
}

function extractEditedDayOnlyNumber(editedText = "", triggerText = "") {
  const prose = splitReplyAndMapBlock(editedText).prose;
  const explicit = prose.match(/\bUpdated\s+Day\s+(\d+)\s+only\b/i);
  if (explicit) return Number(explicit[1]) || null;

  const dayHeaders = [...prose.matchAll(/^Day\s+(\d+)\s+—/gim)]
    .map((m) => Number(m[1]) || 0)
    .filter(Boolean);
  if (dayHeaders.length === 1) return dayHeaders[0];

  return extractRequestedDayNumber(triggerText);
}

function mergeEditedDayIntoCanonicalItinerary(canonicalText = "", editedText = "", triggerText = "") {
  const canonicalDayCount = countItineraryDays(canonicalText);
  const editedDayCount = countItineraryDays(editedText);
  if (canonicalDayCount < 2) return { changed: false, reply: canonicalText, day: null };

  const editedProse = splitReplyAndMapBlock(editedText).prose;
  const isDayOnlyEdit =
    /\bUpdated\s+Day\s+\d+\s+only\b/i.test(editedProse) ||
    (editedDayCount === 1 && editedDayCount < canonicalDayCount);
  if (!isDayOnlyEdit) return { changed: false, reply: canonicalText, day: null };

  const day = extractEditedDayOnlyNumber(editedText, triggerText);
  if (!day) return { changed: false, reply: canonicalText, day: null };

  const canonicalProse = splitReplyAndMapBlock(canonicalText).prose;
  const oldBlock = getItineraryDayBlockLines(canonicalProse, day);
  if (!oldBlock.length) return { changed: false, reply: canonicalText, day };

  let newBlock = trimEditedDayBlockForMerge(getItineraryDayBlockLines(editedProse, day));
  if (!newBlock.length) {
    const activityLines = String(editedProse || "")
      .split("\n")
      .map((line) => String(line || "").trim())
      .filter((line) => STRICT_ACTIVITY_LINE_RX.test(line));
    if (activityLines.length) newBlock = [oldBlock[0], ...activityLines];
  }
  if (!newBlock.length) return { changed: false, reply: canonicalText, day };

  const lines = String(canonicalProse || "").split("\n");
  const start = lines.findIndex((line) => new RegExp(`^\\s*Day\\s+${day}\\s+—`, "i").test(String(line || "")));
  if (start < 0) return { changed: false, reply: canonicalText, day };
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i += 1) {
    if (/^\s*Day\s+\d+\s+—/i.test(String(lines[i] || ""))) {
      end = i;
      break;
    }
  }

  lines.splice(start, end - start, ...newBlock);
  return {
    changed: true,
    reply: replaceReplyProse(canonicalText, lines.join("\n")),
    day,
  };
}

function getLastUserMessageBeforeIndex(messages = [], endIndex = -1) {
  for (let i = Math.min(endIndex - 1, messages.length - 1); i >= 0; i--) {
    if (messages[i]?.role === "user") {
      return String(messages[i]?.content || "").trim();
    }
  }
  return "";
}

function getItineraryTriggerType(text = "") {
  const t = String(text || "").trim();
  if (!t) return "";

  if (looksLikeItineraryEditRequest(t)) return "edit";
  if (looksLikeMapDayFollowUp(t)) return "day-filter";
  if (looksLikeFullItineraryFollowUpRequest(t)) return "full-view";
  if (looksLikeItineraryRequest(t)) return "create";

  return "other";
}

function extractLatestItineraryContext(messages = []) {
  const assistantItineraries = [...messages]
    .map((m, index) => {
      const content = String(m.content || "").trim();
      const triggerText = getLastUserMessageBeforeIndex(messages, index);
      const triggerType = getItineraryTriggerType(triggerText);

      return {
        ...m,
        index,
        content,
        triggerText,
        triggerType,
        dayCount: countItineraryDays(content),
      };
    })
    .filter((m) => m.role === "assistant" && isLikelyItineraryText(String(m.content || "")));

  if (!assistantItineraries.length) {
    // When the backend returned buildProviderValidationFailureReply in the
    // previous turn, the assistant message is a plain "I couldn't finalize
    // this itinerary safely…" note that does NOT match isLikelyItineraryText.
    // Without this check the next user message (e.g. "regenerate the plan
    // around provider-supported opening hours" or "dont include Manila
    // Cathedral in the itinerary") would be routed as general-travel, which
    // is what caused the follow-up misrouting. Treat the failure reply as a
    // pending repair state so itinerary follow-up intents stay active.
    const lastAssistant = [...messages].reverse().find((m) => m && m.role === "assistant");
    const failureText = String(lastAssistant?.content || "");
    const isPendingProviderRepair =
      /I could\s*n[\u2019'`]?t finalize this itinerary safely because some provider-backed schedule conflicts/i.test(failureText) ||
      /Ask me to regenerate the plan around provider-supported opening hours/i.test(failureText);

    return {
      hasActiveItinerary: isPendingProviderRepair,
      pendingProviderRepair: isPendingProviderRepair,
      latestItinerary: isPendingProviderRepair ? failureText : null,
      previousItinerary: null,
      latestVisibleItinerary: isPendingProviderRepair ? failureText : null,
      lastItineraryIndex: -1,
      latestVisibleItineraryIndex: -1,
      previousItineraryIndex: -1,
      latestEditRequest: "",
      latestActionType: isPendingProviderRepair ? "repair" : "",
      latestTriggerType: "",
      latestVisibleTriggerType: "",
      latestDayCount: 0,
      latestVisibleDayCount: 0,
      destination: "",
    };
  }

  const canonicalItineraries = [];

  for (const entry of assistantItineraries) {
    const lastCanonical = canonicalItineraries[canonicalItineraries.length - 1] || null;
    let nextEntry = entry;
    if (lastCanonical && entry.triggerType === "edit") {
      const merged = mergeEditedDayIntoCanonicalItinerary(
        lastCanonical.content,
        entry.content,
        entry.triggerText
      );
      if (merged.changed) {
        console.log("[itinerary] persisting canonical state after edit", { day: merged.day });
        nextEntry = {
          ...entry,
          content: merged.reply,
          dayCount: countItineraryDays(merged.reply),
          mergedDay: merged.day,
        };
      }
    }
    const shouldPromoteToCanonical =
      !lastCanonical ||
      nextEntry.triggerType === "create" ||
      nextEntry.triggerType === "edit" ||
      nextEntry.dayCount >= lastCanonical.dayCount ||
      nextEntry.index > lastCanonical.index;
    if (shouldPromoteToCanonical) {
      canonicalItineraries.push(nextEntry);
    }
  }

  const latestVisible = assistantItineraries[assistantItineraries.length - 1];
  const latestCanonical = canonicalItineraries[canonicalItineraries.length - 1] || latestVisible;
  const previousCanonical =
    canonicalItineraries.length >= 2 ? canonicalItineraries[canonicalItineraries.length - 2] : null;

  const betweenPrevAndLatest = previousCanonical
    ? messages.slice(previousCanonical.index + 1, latestCanonical.index)
    : messages.slice(0, latestCanonical.index);

  const latestEditRequest =
    [...betweenPrevAndLatest]
      .reverse()
      .find((m) => m.role === "user" && looksLikeItineraryEditRequest(String(m.content || "")))
      ?.content ||
    (latestCanonical.triggerType === "edit" ? latestCanonical.triggerText : "");

  return {
    hasActiveItinerary: true,
    activeItineraryText: String(latestCanonical.content || "").trim(),
    latestItinerary: String(latestCanonical.content || "").trim(),
    previousItinerary: previousCanonical ? String(previousCanonical.content || "").trim() : null,
    latestVisibleItinerary: String(latestVisible.content || "").trim(),
    lastItineraryIndex: latestCanonical.index,
    latestVisibleItineraryIndex: latestVisible.index,
    previousItineraryIndex: previousCanonical ? previousCanonical.index : -1,
    latestEditRequest,
    latestActionType: latestCanonical.triggerType === "edit" ? "edit" : "create",
    latestTriggerType: latestCanonical.triggerType || "",
    latestVisibleTriggerType: latestVisible.triggerType || "",
    latestDayCount: latestCanonical.dayCount || 0,
    latestVisibleDayCount: latestVisible.dayCount || 0,
    destination: extractDestinationFromItineraryText(String(latestCanonical.content || "")),
  };
}

