  const statedBudgetPerPerson = extractLatestTripBudgetPerPerson(messages);
  const latestUserRequestsCostAppendix =
    shouldPreparePostItineraryAppendix &&
    /\b(?:budget|cost|costs|price|estimated|estimate|total|expense|expenses)\b/i.test(String(lastUser || ""));
